1	import { notFound } from "next/navigation";
2	import { getHostingAccount } from "@/lib/actions-hosting";
3	import { db } from "@/lib/db";
4	import { decryptSecret } from "@/lib/crypto-box";
5	import { hostingProvisioningStep } from "@/lib/provisioning-step";
6	import { StatusDot, Badge } from "@/components/ui/primitives";
7	import { AutoRefresh } from "@/components/AutoRefresh";
8	import { Provisioning } from "@/components/nx/Provisioning";
9	import { HostingTabs } from "@/components/customer/hosting/HostingTabs";
10	
11	export const dynamic = "force-dynamic";
12	
13	export default async function HostingAccountPage({
14	  params,
15	  searchParams,
16	}: {
17	  params: Promise<{ id: string }>;
18	  searchParams: Promise<{ tab?: string; path?: string; purchase?: string }>;
19	}) {
20	  const [{ id }, { tab, path, purchase }] = await Promise.all([params, searchParams]);
21	
22	  // getHostingAccount enforces owner-or-admin (throws) and returns null if missing.
23	  let account: Awaited<ReturnType<typeof getHostingAccount>> = null;
24	  try {
25	    account = await getHostingAccount(id);
26	  } catch {
27	    notFound();
28	  }
29	  if (!account) notFound();
30	
31	  const transitional = account.status === "PENDING" || account.status === "PROVISIONING";
32	
33	  // Ownership/admin access was already established by getHostingAccount above —
34	  // this second, narrower lookup just pulls the extra raw fields the overlay
35	  // needs (the encrypted SFTP credential, the node's address) that the public
36	  // HostingAccountView doesn't carry. Real progress label: see
37	  // lib/provisioning-step.ts — while PENDING/PROVISIONING it's the worker's own
38	  // per-command-group label; once ACTIVE it's whichever content task (most
39	  // commonly a WordPress install queued at order time) is still running.
40	  const [raw, stepLabel] = await Promise.all([
41	    db.hostingAccount.findUnique({
42	      where: { id: account.id },
43	      select: { sftpPasswordEnc: true, node: { select: { publicIp: true, hostnameFqdn: true } } },
44	    }),
45	    hostingProvisioningStep(account.id),
46	  ]);
47	  const sftpPassword = raw?.sftpPasswordEnc ? decryptSecret(raw.sftpPasswordEnc) : null;
48	  const sftpHost = raw?.node?.hostnameFqdn || raw?.node?.publicIp || null;
49	  // True while a real follow-on step (e.g. that WordPress install) is still
50	  // running even though the account itself already flipped ACTIVE — see
51	  // ProvisioningOverlay's `liveStepActive` prop doc for why this is safe against
52	  // hijacking the screen for a later, casual install.
53	  const installStepActive = account.status === "ACTIVE" && stepLabel !== null;
54	
55	  /* The Nexion provisioning screen, the SAME component the VPS flow uses, so a
56	     hosting customer sees the design rather than the old overlay card. Driven by
57	     the same real signals: the account's status and `hostingProvisioningStep`.
58	     `service="hosting"` picks the cloud mark and the resources panel; there is
59	     no game tier here, so no slots. */
60	  const overlay = (
61	    <Provisioning
62	      phase={account.status === "ERROR" ? "error" : transitional ? "working" : "ready"}
63	      liveStep={stepLabel}
64	      simulate={process.env.NXEON_SANDBOX === "1" && !stepLabel}
65	      service="hosting"
66	      hostname={account.primaryDomain}
67	      planName={account.planName}
68	      osName=""
69	      connectAddress={sftpHost ? `sftp://${account.username}@${sftpHost}` : null}
70	      error={account.error}
71	      dashboardHref={`/dashboard/hosting/${account.id}`}
72	      specs={[
73	        /* Real figures off the account view. Disk is the plan quota plus any
74	           extra bought at deploy, the same total the rest of the page shows. */
75	        { icon: "database", text: `${Math.round(account.diskQuotaMB / 1024) + account.extraDiskGB} GB storage` },
76	        { icon: "globe3", text: `${account.maxSites} site${account.maxSites === 1 ? "" : "s"}` },
77	        { icon: "envelope", text: account.planMailboxes < 0 ? "Unlimited mailboxes" : `${account.planMailboxes} mailboxes` },
78	      ]}
79	    />
80	  );
81	
82	  return (
83	    <div>
84	      {overlay}
85	      {(transitional || installStepActive) && <AutoRefresh />}
86	
87	      <div className="mb-6">
88	        <div className="flex flex-wrap items-center gap-3">
89	          <h1 className="page-title">{account.primaryDomain}</h1>
90	          <StatusDot status={account.status} />
91	          {account.sslActive && <Badge tone="green">HTTPS</Badge>}
92	        </div>
93	        <div className="mt-2 flex flex-wrap items-center gap-2">
94	          <Badge tone="slate">{account.planName}</Badge>
95	          <Badge tone="slate">PHP {account.phpVersion}</Badge>
96	          <a href="/dashboard/hosting" className="text-xs text-slate-500 hover:text-slate-300 hover:underline">← All hosting</a>
97	        </div>
98	      </div>
99	
100	      {transitional && (
101	        <div className="card mb-6 border-amber-500/30 text-sm text-amber-300">
102	          Your account is being set up — this usually takes under a minute. This page refreshes automatically.
103	        </div>
104	      )}
105	
106	      <HostingTabs account={account} initialTab={tab} initialPath={path} />
107	    </div>
108	  );
109	}
