1	"use client";
2	
3	import { useEffect, useMemo, useRef, useState } from "react";
4	import { useRouter } from "next/navigation";
5	import { retryHostingProvision, recheckHostingHealth, type HostingAccountView } from "@/lib/actions-hosting";
6	import { termPriceCents } from "@/lib/billing-terms";
7	import { StatusDot, EmptyState, fmtMoney } from "@/components/ui/primitives";
8	import { MeterBar } from "@/components/ui/charts";
9	import { DeployButton } from "@/components/customer/DeployButton";
10	import {
11	  IconStack,
12	  IconGlobe,
13	  IconDb,
14	  IconDisk,
15	  IconMail,
16	  IconCalendar,
17	  IconExternal,
18	  IconDotsVertical,
19	  IconSearch,
20	  IconSliders,
21	} from "@/components/customer/hosting/OverviewIcons";
22	
23	const PAGE_SIZE = 10;
24	
25	type Tab = "all" | "active" | "expired";
26	
27	/* --------------------------------------------------------------- helpers --- */
28	
29	/**
30	 * Tier -> color mapping, keyed off the REAL HostingPlan.slug (falling back to
31	 * sortOrder for any tier this map hasn't seen yet, e.g. a future 4th plan). The
32	 * three tiers that exist today (prisma/seed-hosting-plans.ts): starter (sortOrder
33	 * 0), business (1), pro (2, the top/most expensive tier) — hence violet for the
34	 * entry tier, teal for the mid "Business" tier, and orange for the top "Pro" tier.
35	 */
36	const TIER_COLORS: Record<string, { icon: string; badge: string }> = {
37	  starter: { icon: "bg-gradient-to-br from-brand-500/30 to-brand-600/10 text-brand-300", badge: "border-brand-500/40 bg-brand-500/10 text-brand-300" },
38	  business: { icon: "bg-gradient-to-br from-teal-500/30 to-emerald-600/10 text-teal-300", badge: "border-teal-500/40 bg-teal-500/10 text-teal-300" },
39	  pro: { icon: "bg-gradient-to-br from-orange-500/30 to-orange-600/10 text-orange-300", badge: "border-orange-500/40 bg-orange-500/10 text-orange-300" },
40	};
41	const TIER_COLOR_RAMP = [
42	  { icon: "bg-gradient-to-br from-brand-500/30 to-brand-600/10 text-brand-300", badge: "border-brand-500/40 bg-brand-500/10 text-brand-300" },
43	  { icon: "bg-gradient-to-br from-accent-blue/30 to-blue-600/10 text-blue-300", badge: "border-blue-500/40 bg-blue-500/10 text-blue-300" },
44	  { icon: "bg-gradient-to-br from-teal-500/30 to-emerald-600/10 text-teal-300", badge: "border-teal-500/40 bg-teal-500/10 text-teal-300" },
45	  { icon: "bg-gradient-to-br from-orange-500/30 to-orange-600/10 text-orange-300", badge: "border-orange-500/40 bg-orange-500/10 text-orange-300" },
46	];
47	function tierColor(a: Pick<HostingAccountView, "planSlug" | "planSortOrder">) {
48	  return TIER_COLORS[a.planSlug] ?? TIER_COLOR_RAMP[a.planSortOrder % TIER_COLOR_RAMP.length];
49	}
50	
51	function fmtDate(iso: string | null): string {
52	  if (!iso) return "—";
53	  return new Date(iso).toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" });
54	}
55	
56	/** Real per-cycle charge + its unit label — never hardcoded to "/month". Uses the
57	 *  SAME formula the renewal sweep actually bills (lib/billing-terms.termPriceCents)
58	 *  against the term + discount this account was SOLD on, so the number shown here
59	 *  matches what the customer is really charged at renewal. */
60	function termLabel(months: number): string {
61	  if (months === 1) return "/ month";
62	  if (months % 12 === 0) return months === 12 ? "/ year" : `/ ${months / 12} years`;
63	  return `/ ${months} mo`;
64	}
65	
66	function pct(used: number, total: number): number {
67	  if (!total || total <= 0) return 0;
68	  return Math.max(0, Math.min(100, (used / total) * 100));
69	}
70	
71	/** Extra sites (subdomains + addon domains) vs the plan's site budget — the exact
72	 *  same "extra sites" metric already shown on the account detail page's Overview
73	 *  tab (components/customer/hosting/HostingTabs.tsx QuotaTile), just aggregated /
74	 *  reused here. The primary domain is always live and isn't counted against the
75	 *  budget, matching that existing convention. */
76	function siteUsage(a: HostingAccountView) {
77	  return { used: a.subdomainsUsed + a.addonDomainsUsed, total: a.maxSites };
78	}
79	function dbUsage(a: HostingAccountView) {
80	  return { used: a.databasesUsed, total: a.maxDatabases };
81	}
82	function storageUsageMB(a: HostingAccountView) {
83	  return { used: a.diskUsedMB ?? 0, total: a.diskQuotaMB, measured: a.diskUsedMB != null };
84	}
85	
86	/* ---------------------------------------------------------------- widget --- */
87	
88	function MiniUsage({
89	  icon,
90	  label,
91	  used,
92	  total,
93	  color,
94	  unlimited = false,
95	  noUsageNote,
96	  format,
97	}: {
98	  icon: React.ReactNode;
99	  label: string;
100	  used: number;
101	  total: number;
102	  color: string;
103	  unlimited?: boolean;
104	  /** Set when there is no real "used" number for this dimension — renders the
105	   *  total only, with a note, and skips the bar rather than fabricating a used
106	   *  value. */
107	  noUsageNote?: string;
108	  format?: (n: number) => string;
109	}) {
110	  const f = format ?? ((n: number) => String(n));
111	  return (
112	    <div className="min-w-[92px]" title={noUsageNote}>
113	      <div className="flex items-center gap-1 text-[10px] font-medium uppercase tracking-wide text-slate-500">
114	        <span className="h-3 w-3 text-slate-500">{icon}</span>
115	        {label}
116	      </div>
117	      <div className="mt-0.5 text-xs font-semibold text-slate-200">
118	        {unlimited ? "Unlimited" : noUsageNote ? `${f(total)} incl.` : `${f(used)} / ${f(total)}`}
119	      </div>
120	      {!unlimited && !noUsageNote && (
121	        <div className="mt-1 w-20">
122	          <MeterBar value={used} max={total || 1} color={color} className="h-1.5" />
123	        </div>
124	      )}
125	    </div>
126	  );
127	}
128	
129	/* ------------------------------------------------------------------ menu --- */
130	
131	function RowMenu({
132	  a,
133	  onRetry,
134	  onRecheck,
135	}: {
136	  a: HostingAccountView;
137	  onRetry: () => void;
138	  onRecheck: () => void;
139	}) {
140	  const [open, setOpen] = useState(false);
141	  const ref = useRef<HTMLDivElement>(null);
142	
143	  useEffect(() => {
144	    if (!open) return;
145	    function onDoc(e: MouseEvent) {
146	      if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false);
147	    }
148	    document.addEventListener("mousedown", onDoc);
149	    return () => document.removeEventListener("mousedown", onDoc);
150	  }, [open]);
151	
152	  const itemClass = "block w-full rounded-lg px-3 py-1.5 text-left text-xs text-slate-300 hover:bg-white/[0.06] hover:text-white";
153	
154	  return (
155	    <div ref={ref} className="relative" onClick={(e) => e.stopPropagation()}>
156	      <button
157	        type="button"
158	        aria-label="Account actions"
159	        className="rounded-lg p-1.5 text-slate-500 hover:bg-white/[0.06] hover:text-white"
160	        onClick={() => setOpen((o) => !o)}
161	      >
162	        <IconDotsVertical className="h-4 w-4" />
163	      </button>
164	      {open && (
165	        <div className="absolute right-0 top-full z-20 mt-1 w-48 rounded-xl border border-white/10 bg-navy-900 p-1.5 shadow-2xl">
166	          <a href={`/dashboard/hosting/${a.id}`} className={itemClass}>Manage</a>
167	          {a.status === "ACTIVE" && (
168	            <a href={`https://${a.primaryDomain}`} target="_blank" rel="noreferrer" className={itemClass}>
169	              Visit site ↗
170	            </a>
171	          )}
172	          {a.status === "ACTIVE" && (
173	            <button type="button" className={itemClass} onClick={() => { setOpen(false); onRecheck(); }}>
174	              Check now / Go live
175	            </button>
176	          )}
177	          {a.status === "FAILED" && (
178	            <button type="button" className={itemClass} onClick={() => { setOpen(false); onRetry(); }}>
179	              Retry setup
180	            </button>
181	          )}
182	          <a href={`/dashboard/hosting/${a.id}?tab=settings`} className={`${itemClass} text-red-300 hover:text-red-200`}>
183	            Cancel account
184	          </a>
185	        </div>
186	      )}
187	    </div>
188	  );
189	}
190	
191	/* ------------------------------------------------------------------- row --- */
192	
193	function PlanRow({
194	  a,
195	  onRetry,
196	  onRecheck,
197	}: {
198	  a: HostingAccountView;
199	  onRetry: () => void;
200	  onRecheck: () => void;
201	}) {
202	  const router = useRouter();
203	  const tier = tierColor(a);
204	  const sites = siteUsage(a);
205	  const dbs = dbUsage(a);
206	  const storage = storageUsageMB(a);
207	  const cycleCents = termPriceCents(a.planPriceCents, a.termMonths, a.annualDiscountPct ?? undefined);
208	
209	  return (
210	    <div
211	      role="button"
212	      tabIndex={0}
213	      onClick={() => router.push(`/dashboard/hosting/${a.id}`)}
214	      onKeyDown={(e) => {
215	        if (e.key === "Enter") router.push(`/dashboard/hosting/${a.id}`);
216	      }}
217	      className="grid cursor-pointer grid-cols-1 gap-4 p-4 transition-colors hover:bg-white/[0.03] sm:p-5 md:grid-cols-[minmax(190px,1.5fr)_minmax(280px,2fr)_120px_110px_100px_28px] md:items-center md:gap-3"
218	    >
219	      {/* Plan */}
220	      <div className="flex items-start gap-3">
221	        <div className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-xl ${tier.icon}`}>
222	          <IconGlobe className="h-5 w-5" />
223	        </div>
224	        <div className="min-w-0">
225	          <div className="flex flex-wrap items-center gap-2">
226	            {/* HostingAccount has no separate customer-set label field — the display
227	                name IS the primary domain (see report). */}
228	            <span className="truncate font-semibold text-slate-100">{a.primaryDomain}</span>
229	            <span className={`inline-flex items-center rounded-full border px-2 py-0.5 text-[10px] font-medium ${tier.badge}`}>
230	              {a.planName}
231	            </span>
232	          </div>
233	          <a
234	            href={`https://${a.primaryDomain}`}
235	            target="_blank"
236	            rel="noreferrer"
237	            onClick={(e) => e.stopPropagation()}
238	            className="mt-0.5 inline-flex items-center gap-1 text-xs text-slate-500 hover:text-brand-300 hover:underline"
239	          >
240	            {a.primaryDomain}
241	            <IconExternal className="h-3 w-3" />
242	          </a>
243	        </div>
244	      </div>
245	
246	      {/* Usage */}
247	      <div className="flex flex-wrap gap-4">
248	        <MiniUsage icon={<IconGlobe />} label="Sites" used={sites.used} total={sites.total} color="#8a70fb" />
249	        <MiniUsage icon={<IconDb />} label="DBs" used={dbs.used} total={dbs.total} color="#3b82f6" />
250	        <MiniUsage
251	          icon={<IconDisk />}
252	          label="Storage"
253	          used={storage.used / 1024}
254	          total={storage.total / 1024}
255	          color="#22d3ee"
256	          format={(n) => n.toFixed(n < 10 ? 1 : 0)}
257	          noUsageNote={storage.measured ? undefined : "Not measured yet — updates once the account is live"}
258	        />
259	        <MiniUsage
260	          icon={<IconMail />}
261	          label="Mail"
262	          used={0}
263	          total={a.planMailboxes}
264	          color="#fb923c"
265	          unlimited={a.planMailboxes === -1}
266	          noUsageNote={a.planMailboxes === -1 ? undefined : "Mailbox usage isn't tracked for shared hosting yet — included allowance shown"}
267	        />
268	      </div>
269	
270	      {/* Renewal */}
271	      <div className="flex items-center gap-1.5 text-xs text-slate-400">
272	        <IconCalendar className="h-3.5 w-3.5 shrink-0 text-slate-500" />
273	        {fmtDate(a.expiresAt)}
274	      </div>
275	
276	      {/* Status */}
277	      <div>
278	        <StatusDot status={a.status} />
279	      </div>
280	
281	      {/* Cost */}
282	      <div className="flex items-baseline gap-1">
283	        <span className="text-sm font-bold text-slate-100">{fmtMoney(cycleCents)}</span>
284	        <span className="text-[11px] text-slate-500">{termLabel(a.termMonths)}</span>
285	      </div>
286	
287	      {/* Actions */}
288	      <div className="flex justify-end">
289	        <RowMenu a={a} onRetry={onRetry} onRecheck={onRecheck} />
290	      </div>
291	    </div>
292	  );
293	}
294	
295	/* ----------------------------------------------------------------- stats --- */
296	
297	function SummaryCell({
298	  icon,
299	  label,
300	  value,
301	  pctValue,
302	  color,
303	  note,
304	  statusDot,
305	}: {
306	  icon: React.ReactNode;
307	  label: string;
308	  value: React.ReactNode;
309	  pctValue?: number;
310	  color?: string;
311	  note?: string;
312	  statusDot?: boolean;
313	}) {
314	  return (
315	    <div className="p-5">
316	      <div className="flex items-center gap-2 text-slate-400">
317	        <span className="flex h-8 w-8 items-center justify-center rounded-lg border border-white/[0.08] bg-white/[0.03] text-brand-300">
318	          <span className="h-4 w-4 [&>svg]:h-4 [&>svg]:w-4">{icon}</span>
319	        </span>
320	        <span className="text-xs font-medium uppercase tracking-wide">{label}</span>
321	      </div>
322	      <div className="mt-2 flex items-center gap-2">
323	        <span className="text-xl font-bold tracking-tight text-slate-100">{value}</span>
324	        {statusDot && <span className="h-2 w-2 rounded-full bg-emerald-400" />}
325	      </div>
326	      {pctValue != null && color && (
327	        <div className="mt-2">
328	          <MeterBar value={pctValue} max={100} color={color} className="h-1.5" />
329	        </div>
330	      )}
331	      {note && <p className="mt-1 text-[10px] text-slate-500">{note}</p>}
332	    </div>
333	  );
334	}
335	
336	/* ----------------------------------------------------------------- main --- */
337	
338	export function HostingClient({ accounts }: { accounts: HostingAccountView[] }) {
339	  const [error, setError] = useState("");
340	  const [tab, setTab] = useState<Tab>("all");
341	  const [query, setQuery] = useState("");
342	  const [tierFilter, setTierFilter] = useState<string | null>(null);
343	  const [filterOpen, setFilterOpen] = useState(false);
344	  const [page, setPage] = useState(1);
345	  const filterRef = useRef<HTMLDivElement>(null);
346	
347	  useEffect(() => {
348	    if (!filterOpen) return;
349	    function onDoc(e: MouseEvent) {
350	      if (filterRef.current && !filterRef.current.contains(e.target as Node)) setFilterOpen(false);
351	    }
352	    document.addEventListener("mousedown", onDoc);
353	    return () => document.removeEventListener("mousedown", onDoc);
354	  }, [filterOpen]);
355	
356	  async function retry(id: string) {
357	    setError("");
358	    const res = await retryHostingProvision(id);
359	    if (res.error) {
360	      setError(res.error);
361	      return;
362	    }
363	    window.location.reload();
364	  }
365	
366	  async function recheck(id: string) {
367	    setError("");
368	    const res = await recheckHostingHealth(id);
369	    if (res.error) {
370	      setError(res.error);
371	      return;
372	    }
373	    window.location.reload();
374	  }
375	
376	  const tiers = useMemo(() => Array.from(new Set(accounts.map((a) => a.planName))).sort(), [accounts]);
377	
378	  // Bucket mapping for the tabs: HostingAccountStatus has no literal "EXPIRED"
379	  // state — an unpaid/past-due account is flipped to SUSPENDED by the renewal
380	  // sweep (worker/product-renewals.ts suspendUnpaidHostingAccount), so "Expired"
381	  // == SUSPENDED. PENDING/PROVISIONING/FAILED/DELETING accounts show under "All
382	  // Plans" only (they're neither a healthy active plan nor a lapsed one).
383	  const filtered = useMemo(() => {
384	    const q = query.trim().toLowerCase();
385	    return accounts.filter((a) => {
386	      if (tab === "active" && a.status !== "ACTIVE") return false;
387	      if (tab === "expired" && a.status !== "SUSPENDED") return false;
388	      if (tierFilter && a.planName !== tierFilter) return false;
389	      if (q && !a.primaryDomain.toLowerCase().includes(q) && !a.planName.toLowerCase().includes(q)) return false;
390	      return true;
391	    });
392	  }, [accounts, tab, tierFilter, query]);
393	
394	  useEffect(() => {
395	    setPage(1);
396	  }, [tab, tierFilter, query]);
397	
398	  const totalPages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
399	  const clampedPage = Math.min(page, totalPages);
400	  const pageRows = filtered.slice((clampedPage - 1) * PAGE_SIZE, clampedPage * PAGE_SIZE);
401	
402	  // Fleet-wide summary — always over ALL of the customer's accounts (not the
403	  // current tab/search filter), so it reads as a stable "your whole hosting
404	  // footprint" tile rather than shifting under a filter.
405	  const activeCount = accounts.filter((a) => a.status === "ACTIVE").length;
406	  const sitesTotal = accounts.reduce((s, a) => s + siteUsage(a).total, 0);
407	  const sitesUsed = accounts.reduce((s, a) => s + siteUsage(a).used, 0);
408	  const dbTotal = accounts.reduce((s, a) => s + dbUsage(a).total, 0);
409	  const dbUsed = accounts.reduce((s, a) => s + dbUsage(a).used, 0);
