3	import { useEffect, useState, type ReactNode } from "react";
4	import { Icon } from "@/components/nx/Icon";
5	import { VpsHero, VpsStateBanner } from "./VpsHero";
6	import { SubNav, type SubSection } from "./ui";
7	import type { VpsHeaderData } from "./types";
8	
9	/**
10	 * The VPS panel's shell: a pinned identity hero, a pinned tab rail, one tab.
11	 *
12	 * TEN TABS TO EIGHT.
13	 * - Metrics folded into Overview. The old dashboard reported CPU and memory in
14	 *   three places that could not agree — a hypervisor instant, RRD history, and
15	 *   an in-guest process snapshot.
16	 * - Snapshots merged into Backups: both answer "put this machine back how it
17	 *   was", differing in mechanism, not intent.
18	 * - Upgrade folded into Settings. Resizing is a setting, not a destination; it
19	 *   does not belong in a rail beside Console and Files as though it were
20	 *   visited daily. Reinstall went with it, for the same reason.
21	 * - "Control panel" renamed Services, for what it actually manages.
22	 *
23	 * Every tab with sub-sections uses the side rail from GameSettingsShell rather
24	 * than a second row of pills, so Backups, Networking, Activity and Settings all
25	 * navigate the same way.
26	 */
27	
28	type TabKey =
29	  | "overview" | "console" | "files" | "services"
30	  | "backups" | "networking" | "activity" | "settings";
31	
32	const TABS: { key: TabKey; label: string; icon: string }[] = [
33	  { key: "overview",   label: "Overview",   icon: "donut" },
34	  { key: "console",    label: "Console",    icon: "terminal" },
35	  { key: "files",      label: "Files",      icon: "folder" },
36	  { key: "services",   label: "Services",   icon: "sliders" },
37	  { key: "backups",    label: "Backups",    icon: "archive" },
38	  { key: "networking", label: "Networking", icon: "nodes" },
39	  { key: "activity",   label: "Activity",   icon: "activity" },
40	  { key: "settings",   label: "Settings",   icon: "gear" },
41	];
42	
43	/** Retired keys that links, bookmarks and worker notifications still use. */
44	const ALIASES: Record<string, TabKey> = {
45	  resize: "settings",
46	  upgrade: "settings",
47	  reinstall: "settings",
48	  metrics: "overview",
49	  snapshots: "backups",
50	  "control panel": "services",
51	  controlpanel: "services",
52	  cpanel: "services",
53	};
54	
55	function resolveTab(raw: string | undefined): TabKey {
56	  const k = (raw ?? "").toLowerCase().trim();
57	  if (TABS.some((t) => t.key === k)) return k as TabKey;
58	  return ALIASES[k] ?? "overview";
59	}
60	
61	const RESTORE: SubSection<"backups" | "snapshots">[] = [
62	  { key: "backups", label: "Backups", sub: "Full archives you can restore", icon: "archive" },
63	  { key: "snapshots", label: "Snapshots", sub: "Point-in-time disk state", icon: "layers" },
64	];
65	
66	const HISTORY: SubSection<"jobs" | "access">[] = [
67	  { key: "jobs", label: "Server jobs", sub: "What we ran for you", icon: "activity" },
68	  { key: "access", label: "SSH access", sub: "Sign-ins and failures", icon: "key" },
69	];
70	
71	export function VpsPanelShell({
72	  data, busy, suspendReason, provisionError,
73	  overviewPanel, consolePanel, filesPanel, servicesPanel,
74	  backupsPanel, snapshotsPanel, networkingPanel, settingsPanel,
75	  activityPanel, accessPanel, initialTab,
76	}: {
77	  data: VpsHeaderData;
78	  /** A job is in flight — power controls disable themselves. */
79	  busy: boolean;
80	  suspendReason: string | null;
81	  provisionError: string | null;
82	  overviewPanel: ReactNode;
83	  consolePanel: ReactNode;
84	  filesPanel: ReactNode;
85	  servicesPanel: ReactNode;
86	  backupsPanel: ReactNode;
87	  snapshotsPanel: ReactNode;
88	  networkingPanel: ReactNode;
89	  settingsPanel: ReactNode;
90	  activityPanel: ReactNode;
91	  accessPanel: ReactNode;
92	  initialTab?: string;
93	}) {
94	  const [tab, setTab] = useState<TabKey>(() => resolveTab(initialTab));
95	
96	  useEffect(() => {
97	    const onPop = () => {
98	      const t = new URLSearchParams(window.location.search).get("tab") ?? undefined;
99	      setTab(resolveTab(t));
100	    };
101	    window.addEventListener("popstate", onPop);
102	    return () => window.removeEventListener("popstate", onPop);
103	  }, []);
104	
105	  const go = (t: TabKey) => {
106	    setTab(t);
107	    const url = new URL(window.location.href);
108	    url.searchParams.set("tab", t);
109	    window.history.pushState(null, "", url);
110	    window.scrollTo({ top: 0, behavior: "smooth" });
111	  };
112	
113	  return (
114	    /* A max-width on the panel. At full bleed on a wide monitor the cards
115	       stretch to fill 1500px+ and read as banners rather than cards; this pulls
116	       the column in so they keep a card's proportions. */
117	    <div className="mx-auto flex w-full max-w-[1480px] flex-col gap-4">
118	      <VpsStateBanner data={data} suspendReason={suspendReason} provisionError={provisionError} />
119	
120	      <div className="sticky top-0 z-20 -mx-1 flex flex-col gap-2 bg-[color-mix(in_srgb,var(--color-bg)_82%,transparent)] px-1 pb-2 pt-1 backdrop-blur-xl">
121	        <VpsHero data={data} busy={busy} />
122	
123	        <nav className="flex gap-1 overflow-x-auto rounded-[14px] border border-rim-hi bg-surface p-1.5">
124	          {TABS.map((t) => {
125	            const on = tab === t.key;
126	            return (
127	              <button
128	                key={t.key}
129	                type="button"
130	                onClick={() => go(t.key)}
131	                aria-current={on ? "page" : undefined}
132	                className={
133	                  "inline-flex flex-none items-center gap-2 whitespace-nowrap rounded-[10px] px-3.5 py-2 text-[13px] font-semibold transition " +
134	                  (on
135	                    ? "bg-[linear-gradient(120deg,rgba(80,40,190,.55),rgba(30,44,130,.42))] text-[#fff] shadow-[inset_0_0_0_1px_rgba(139,92,255,.5)]"
136	                    : "text-tx-dim hover:bg-[color-mix(in_srgb,var(--fg)_5%,transparent)] hover:text-tx")
137	                }
138	              >
139	                <Icon name={t.icon} size={14} tone="inherit" className={on ? "text-[#fff]" : "text-tx-dim"} />
140	                {t.label}
141	              </button>
142	            );
143	          })}
144	        </nav>
145	      </div>
146	
147	      <div className="min-w-0">
148	        {tab === "overview" && overviewPanel}
149	        {tab === "console" && consolePanel}
150	        {tab === "files" && filesPanel}
151	        {tab === "services" && servicesPanel}
152	        {tab === "networking" && networkingPanel}
153	        {tab === "settings" && settingsPanel}
154	
155	        {tab === "backups" && (
156	          <SubNav sections={RESTORE} slots={{ backups: backupsPanel, snapshots: snapshotsPanel }} />
157	        )}
158	
159	        {tab === "activity" && (
160	          <SubNav sections={HISTORY} slots={{ jobs: activityPanel, access: accessPanel }} />
161	        )}
162	      </div>
163	    </div>
164	  );
165	}
