2	
3	import { useEffect, useRef, useState, type ReactNode } from "react";
4	import { createPortal } from "react-dom";
5	import { Icon } from "@/components/nx/Icon";
6	
7	/**
8	 * The VPS command centre's component kit.
9	 *
10	 * One set of primitives for the whole panel, so Networking and Settings and
11	 * Overview cannot drift into three dialects again. Surfaces and motion live in
12	 * globals.css under the `.nxp` prefix; this file is the React side.
13	 *
14	 * Two rules worth keeping:
15	 *   1. Not everything needs a container. `Section` exists for content that
16	 *      wants a heading and rhythm WITHOUT a box — use it over `Panel` unless
17	 *      the content genuinely needs to be separated from what surrounds it.
18	 *   2. Anything that can be unknown takes `null`, not `0`. A tile handed null
19	 *      draws an em dash and a reason; it never draws a zero, because a zero is
20	 *      a measurement and "we could not ask" is not.
21	 */
22	
23	/* ── surfaces ─────────────────────────────────────────────────────────── */
24	
25	/** A bare titled block — heading, optional action, content. No box. */
26	export function Section({ title, sub, action, children, className = "" }: {
27	  title?: string; sub?: string; action?: ReactNode; children: ReactNode; className?: string;
28	}) {
29	  return (
30	    <section className={"flex min-w-0 flex-col " + className}>
31	      {(title || action) && (
32	        <div className="mb-3 flex flex-wrap items-end justify-between gap-3">
33	          <div className="min-w-0">
34	            {title && <h2 className="text-[13px] font-bold uppercase tracking-[0.14em] text-tx-faint">{title}</h2>}
35	            {sub && <p className="mt-1 text-[12.5px] leading-relaxed text-tx-dim">{sub}</p>}
36	          </div>
37	          {action}
38	        </div>
39	      )}
40	      {children}
41	    </section>
42	  );
43	}
44	
45	/** A contained panel. `interactive` adds the hover illumination. */
46	export function Panel({ title, action, children, className = "", interactive, pad = true, accent, icon, ink, fill = true }: {
47	  title?: string; action?: ReactNode; children: ReactNode;
48	  className?: string; interactive?: boolean; pad?: boolean;
49	  /** A `--tone` hex for .card-glass — the per-card edge accent. */
50	  accent?: string;
51	  /** A bare glowing icon beside the title. No plate; the card carries the hue. */
52	  icon?: string;
53	  ink?: string;
54	  /**
55	   * Fill the cell (the bento default) or size to content.
56	   *
57	   * `h-full` is right in a grid whose row height is set by its tallest cell. It
58	   * is WRONG in a plain `flex-col` stack: every card asks for 100% of a height
59	   * its own content defined, the total overflows, flexbox shrinks them all and
60	   * `overflow-auto` quietly clips the bottom of each one. That is how the
61	   * Resources tab lost the bottom of its plan card. Pass `fill={false}` for a
62	   * stacked column; the default keeps every existing bento caller identical.
63	   */
64	  fill?: boolean;
65	}) {
66	  return (
67	    /* h-full + overflow-hidden so a card fills its bento cell and clips its own
68	       content instead of stretching the grid row. */
69	    /* `card card-glass` is the product's own liquid-glass surface — transparent
70	       pane, 24px backdrop blur, flat tinted border and a corner-tracing inner
71	       glow, with --tone setting the edge accent. Same treatment SupportView and
72	       WhatsNewView use. */
73	    <section
74	      className={`card card-glass ${interactive ? "card-i" : ""} flex ${fill ? "h-full" : "flex-none"} min-w-0 flex-col overflow-hidden p-0 ${className}`}
75	      style={accent ? ({ "--tone": accent } as React.CSSProperties) : undefined}
76	    >
77	      {title && (
78	        <div className="relative z-[1] flex flex-none items-center gap-2.5 border-b border-white/[0.07] px-4 py-2.5">
79	          {icon && <Icon name={icon} size={15} tone="inherit" className={`nxp-ico flex-none ${ink ?? "text-[#8fb6ff]"}`} />}
80	          <h3 className="text-[13px] font-extrabold tracking-[-0.01em] text-tx">{title}</h3>
81	          {action && <span className="ml-auto flex-none">{action}</span>}
82	        </div>
83	      )}
84	      <div className={"relative z-[1] min-w-0 flex-1 " + (fill ? "overflow-auto " : "") + (pad ? "p-3.5" : "")}>{children}</div>
85	    </section>
86	  );
87	}
88	
89	/* ── status ───────────────────────────────────────────────────────────── */
90	
91	export type Tone = "ok" | "warn" | "bad" | "busy" | "idle";
92	
93	const TONE: Record<Tone, { dot: string; ink: string; ring: string }> = {
94	  ok:   { dot: "bg-emerald-400", ink: "text-emerald-300", ring: "border-emerald-400/40 bg-emerald-500/12" },
95	  warn: { dot: "bg-amber-400",   ink: "text-amber-300",   ring: "border-amber-400/40 bg-amber-500/12" },
96	  bad:  { dot: "bg-rose-400",    ink: "text-rose-300",    ring: "border-rose-400/40 bg-rose-500/12" },
97	  busy: { dot: "bg-sky-400",     ink: "text-sky-300",     ring: "border-sky-400/40 bg-sky-500/12" },
98	  idle: { dot: "bg-slate-400",   ink: "text-slate-300",   ring: "border-slate-400/30 bg-slate-500/12" },
99	};
100	
101	export function StatusPill({ tone, label, live }: { tone: Tone; label: string; live?: boolean }) {
102	  const t = TONE[tone];
103	  return (
104	    <span className={`inline-flex items-center gap-2 rounded-full border px-2.5 py-1 text-[11.5px] font-bold ${t.ring} ${t.ink}`}>
105	      <span className={`relative h-1.5 w-1.5 flex-none rounded-full ${t.dot} ${live ? "nxp-live" : ""}`} />
106	      {label}
107	    </span>
108	  );
109	}
110	
111	export function Tag({ children, tone = "idle" }: { children: ReactNode; tone?: Tone }) {
112	  const t = TONE[tone];
113	  return (
114	    <span className={`rounded-[6px] border px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide ${t.ring} ${t.ink}`}>
115	      {children}
116	    </span>
117	  );
118	}
119	
120	/* ── figures ──────────────────────────────────────────────────────────── */
121	
122	/** A measured figure. `value === null` means unmeasured — em dash plus reason,
123	 *  never a zero and never an empty bar. */
124	export function Metric({ icon, ink, label, value, sub, pct, tone, unknown, compact }: {
125	  icon: string; ink: string; label: string;
126	  value: string | null; sub?: string; pct?: number; tone?: string;
127	  unknown?: string; compact?: boolean;
128	}) {
129	  const known = value !== null;
