216	/** A dropdown anchored to its trigger. Portalled to the body: a backdrop-filter
217	 *  ancestor would otherwise become the containing block for a fixed child. */
218	export function Menu({ label, icon = "ellipsis", items }: {
219	  label?: string;
220	  icon?: string;
221	  items: { key: string; label: string; icon?: string; danger?: boolean; onSelect: () => void }[];
222	}) {
223	  const [open, setOpen] = useState(false);
224	  const [rect, setRect] = useState<{ top: number; right: number } | null>(null);
225	  const btn = useRef<HTMLButtonElement | null>(null);
226	
227	  useEffect(() => {
228	    if (!open) return;
229	    const close = () => setOpen(false);
230	    window.addEventListener("scroll", close, true);
231	    window.addEventListener("resize", close);
232	    const esc = (e: KeyboardEvent) => e.key === "Escape" && setOpen(false);
233	    window.addEventListener("keydown", esc);
234	    return () => {
235	      window.removeEventListener("scroll", close, true);
236	      window.removeEventListener("resize", close);
237	      window.removeEventListener("keydown", esc);
238	    };
239	  }, [open]);
240	
241	  return (
242	    <>
243	      <button
244	        ref={btn}
245	        type="button"
246	        onClick={() => {
247	          const r = btn.current?.getBoundingClientRect();
248	          if (r) setRect({ top: r.bottom + 8, right: window.innerWidth - r.right });
249	          setOpen((v) => !v);
250	        }}
251	        className="inline-flex items-center gap-1.5 rounded-[10px] border border-rim-hi bg-[color-mix(in_srgb,var(--fg)_4%,transparent)] px-3 py-2 text-[12.5px] font-semibold text-tx-body transition hover:border-[#8b5cff]/45 hover:text-tx"
252	      >
253	        {label}
254	        <Icon name={icon} size={14} tone="inherit" />
255	      </button>
256	      {open && rect &&
257	        createPortal(
258	          <>
259	            <div className="fixed inset-0 z-[80]" onClick={() => setOpen(false)} />
260	            <div
261	              className="card card-glass nxp-modal fixed z-[81] min-w-[212px] overflow-hidden p-1"
262	              style={{ top: rect.top, right: rect.right }}
263	            >
264	              {items.map((it) => (
265	                <button
266	                  key={it.key}
267	                  type="button"
268	                  onClick={() => { setOpen(false); it.onSelect(); }}
269	                  className={
270	                    "flex w-full items-center gap-2.5 rounded-[9px] px-3 py-2 text-left text-[12.5px] font-semibold transition " +
271	                    (it.danger
272	                      ? "text-rose-300 hover:bg-rose-500/12"
273	                      : "text-tx-body hover:bg-[color-mix(in_srgb,var(--fg)_6%,transparent)] hover:text-tx")
274	                  }
275	                >
