53	/* ── the side sub-navigation ──────────────────────────────────────────────
54	   Lifted from GameSettingsShell, which is the arrangement the owner asked for
55	   on every tab that has sub-sections: a 252px rail of named sections with a
56	   one-line description each, and the section's own cards to the right.
57	
58	   Generic on the key so Settings, Networking and Backups can all use it
59	   without three near-identical copies. */
60	
61	export type SubSection<K extends string> = {
62	  key: K;
63	  label: string;
64	  sub: string;
65	  icon: string;
66	  tone?: "danger";
67	};
68	
69	export function SubNav<K extends string>({ sections, slots, initial }: {
70	  sections: SubSection<K>[];
71	  slots: Partial<Record<K, ReactNode>>;
72	  initial?: K;
73	}) {
74	  const shown = sections.filter((s) => slots[s.key]);
75	  const [sec, setSec] = useState<K | undefined>(initial ?? shown[0]?.key);
76	  const active = shown.find((s) => s.key === sec) ?? shown[0];
77	
78	  if (!active) return null;
79	
80	  return (
81	    <div className="grid gap-4 lg:grid-cols-[252px_minmax(0,1fr)]">
82	      <nav className="flex h-fit flex-col gap-1 rounded-[16px] border border-rim-hi bg-surface p-2">
83	        {shown.map((s) => {
84	          const on = active.key === s.key;
85	          const danger = s.tone === "danger";
86	          return (
87	            <button
88	              key={s.key}
89	              type="button"
90	              onClick={() => setSec(s.key)}
91	              aria-current={on ? "true" : undefined}
92	              className={
93	                "flex items-center gap-3 rounded-[11px] border px-3 py-2.5 text-left transition " +
94	                (on
95	                  ? danger
96	                    ? "border-red-500/45 bg-red-500/12"
97	                    : "border-[#8b5cff]/70 bg-[linear-gradient(120deg,rgba(80,40,190,.42),rgba(30,40,120,.3))]"
98	                  : "border-transparent hover:bg-[color-mix(in_srgb,var(--fg)_4%,transparent)]")
99	              }
100	            >
101	              <Icon
102	                name={s.icon}
103	                size={16}
104	                tone="inherit"
105	                className={"flex-none " + (danger ? "text-red-400" : on ? "text-[#fff]" : "text-tx-dim")}
106	              />
107	              <span className="flex min-w-0 flex-col">
108	                <span className={"truncate text-[13px] font-bold " + (danger ? "text-red-300" : on ? "text-[#fff]" : "text-tx-dim")}>
109	                  {s.label}
110	                </span>
111	                <span className="truncate text-[11px] text-tx-faint">{s.sub}</span>
112	              </span>
113	            </button>
114	          );
115	        })}
116	      </nav>
117	
118	      <div className="flex min-w-0 flex-col gap-4 [&_.card]:rounded-[16px]">{slots[active.key]}</div>
119	    </div>
120	  );
121	}
