function toView(a: {
  id: string; primaryDomain: string; status: string; username: string; diskQuotaMB: number; extraDiskGB?: number; maxSites: number;
  maxDatabases: number; sslActive: boolean; phpVersion: string; error: string | null; expiresAt: Date | null; createdAt: Date;
  dbToolPath?: string | null;
  diskUsedMB?: number | null; inodesUsed?: number | null; usageAt?: Date | null;
  termMonths?: number; annualDiscountPct?: number | null;
  serveHttpOk?: boolean | null; serveHttpsOk?: boolean | null; healthNote?: string | null; healthCheckedAt?: Date | null;
  plan: { name: string; phpVersions: string; slug?: string; sortOrder?: number; priceCents?: number; mailboxes?: number };
  node: { publicIp: string; hostnameFqdn: string | null };
  _count?: { databases?: number; addonDomains?: number; subdomains?: number };
}): HostingAccountView {
  const pt = pointToRecords(a.node);
  return {
    id: a.id, primaryDomain: a.primaryDomain, isFreeSubdomain: isFreeSubdomain(a.primaryDomain),
    planName: a.plan.name, planSlug: a.plan.slug ?? "", planSortOrder: a.plan.sortOrder ?? 0,
    planPriceCents: a.plan.priceCents ?? 0, planMailboxes: a.plan.mailboxes ?? 0,
    termMonths: a.termMonths ?? 1, annualDiscountPct: a.annualDiscountPct ?? null,
    status: a.status, username: a.username,
    pointToA: pt.aRecord, pointToCname: pt.cnameTarget, diskQuotaMB: a.diskQuotaMB, extraDiskGB: a.extraDiskGB ?? 0, maxSites: a.maxSites,
    diskUsedMB: a.diskUsedMB ?? null, inodesUsed: a.inodesUsed ?? null, usageAt: a.usageAt?.toISOString() ?? null,
    maxDatabases: a.maxDatabases, sslActive: a.sslActive, phpVersion: a.phpVersion,
    addonDomainsUsed: a._count?.addonDomains ?? 0, subdomainsUsed: a._count?.subdomains ?? 0, databasesUsed: a._count?.databases ?? 0,
    serveHttpOk: a.serveHttpOk ?? null, serveHttpsOk: a.serveHttpsOk ?? null,
    healthNote: a.healthNote ?? null, healthCheckedAt: a.healthCheckedAt?.toISOString() ?? null,
    phpVersions: planLimits({ diskGB: 1, maxSites: 1, maxDatabases: 0, bandwidthTB: 0, phpVersions: a.plan.phpVersions }).phpVersions,
    dbToolPath: a.dbToolPath ?? null,
    error: a.error, expiresAt: a.expiresAt?.toISOString() ?? null, createdAt: a.createdAt.toISOString(),
  };
}

/** Decrypt + return the account's SFTP password (owner or admin). cPanel-style. */
export async function revealHostingSftpPassword(accountId: string): Promise<{ password?: string; error?: string }> {
  const user = await requireUser();
  // An impersonating admin must not exfiltrate a customer's live SFTP credential
  // (matches orderHostingAccount/createHostingDatabase — audit LOW-1).
  await assertNotImpersonating();
  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { userId: true, sftpPasswordEnc: true } });
  if (!a) return { error: "Not found." };
  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  const pw = a.sftpPasswordEnc ? decryptSecret(a.sftpPasswordEnc) : null;
  if (!pw) return { error: "No password on record yet — the account is still being set up." };
  return { password: pw };
}

// Shared include for both list + detail lookups: real per-account usage counts
// (databases/addonDomains/subdomains) via Prisma `_count`, plus the plan fields
// the redesigned overview page needs (tier slug/sortOrder for color mapping,
// priceCents/mailboxes for the cost + email columns) — sourced from the DB, never
// fabricated in the view layer.
const HOSTING_ACCOUNT_INCLUDE = {
  plan: { select: { name: true, phpVersions: true, slug: true, sortOrder: true, priceCents: true, mailboxes: true } },
  node: { select: { publicIp: true, hostnameFqdn: true } },
  _count: { select: { databases: true, addonDomains: true, subdomains: true } },
} as const;

export async function listHostingAccounts(): Promise<HostingAccountView[]> {
  const user = await requireUser();
  const rows = await db.hostingAccount.findMany({
    where: { userId: user.id },
    orderBy: { createdAt: "desc" },
    include: HOSTING_ACCOUNT_INCLUDE,
  });
  return rows.map(toView);
}

export async function getHostingAccount(id: string): Promise<HostingAccountView | null> {
  const user = await requireUser();
  const a = await db.hostingAccount.findUnique({
    where: { id },
    include: HOSTING_ACCOUNT_INCLUDE,
  });
  if (!a) return null;
  if (a.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return toView(a);
}

/**
 * Customer "Check now / Go live" — flag an ACTIVE account for an immediate
 * serve-verification + SSL recheck. The worker's fast lane (~30s) picks up
 * recheckRequested accounts before their routine 10-min cadence, verifies HTTP/
 * HTTPS from the node, self-heals a stale cert vhost, and nudges the SSL sweep so a
 * trusted certificate can start issuing. Owner or admin; a no-op for non-active
 * accounts (nothing to verify until it's provisioned).
 */
export async function recheckHostingHealth(id: string): Promise<HostingResult> {
  const user = await requireUser();
  const a = await db.hostingAccount.findUnique({ where: { id }, select: { userId: true, status: true } });
  if (!a) return { error: "Not found." };
  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
  await db.hostingAccount.update({ where: { id }, data: { recheckRequested: true } });
  revalidatePath(`/dashboard/hosting/${id}`);
  return { ok: true };
}

/** Re-queue a FAILED account for the provisioner. Owner or admin. */
export async function retryHostingProvision(id: string): Promise<HostingResult> {
  const user = await requireUser();
  const a = await db.hostingAccount.findUnique({ where: { id } });
  if (!a) return { error: "Not found." };
  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  if (a.status !== "FAILED") return { error: "This account isn’t in a failed state." };
  await db.hostingAccount.update({ where: { id }, data: { status: "PENDING", error: null } });
  revalidatePath("/dashboard/hosting");
  return { ok: true };
}

