"use client";

import { useEffect, useState, type ReactNode } from "react";
import { Icon } from "@/components/nx/Icon";
import { fmtBytes } from "@/components/ui/primitives";
import { VpsResourceMonitor } from "./VpsResourceMonitor";
import { Panel, Segmented, CopyChip, Skeleton } from "./kit";
import type { VpsHeaderData } from "./types";

/**
 * Overview — the control centre, laid out to fit one screen.
 *
 * A live figure row under the tabs, the resource monitor and insights down the
 * main column, and health / activity / subscription / backups / quick-connect
 * down the rail. Nothing here restates the hero.
 *
 * Every check and every figure is derived from a measurement, and anything
 * unmeasured says so rather than showing a confident green tick. That matters
 * most in Server health, where a tick is a claim.
 */

/* ── live figures ─────────────────────────────────────────────────────── */

function LiveStat({ icon, accent, ink, label, value, sub, pct, tone, unknown }: {
  icon: string; accent: string; ink: string; label: string;
  value: string | null; sub?: string; pct?: number; tone: string; unknown?: string;
}) {
  const known = value !== null;
  return (
    /* The colour is the CARD's — a tinted rim and its matching bloom — with the
       icon bare and glowing in the same hue. The plate that used to sit behind
       it was just a grey square swallowing the accent. */
    <div className="card card-glass card-i flex items-center gap-3 px-4 py-3">
      <Icon name={icon} size={20} tone="inherit" className={`nxp-ico flex-none ${ink}`} />
      <span className="flex min-w-0 flex-1 flex-col">
        <span className="text-[10px] font-bold uppercase tracking-[0.13em] text-tx-faint">{label}</span>
        <span className={"num truncate text-[17px] font-extrabold leading-tight " + (known ? "text-tx" : "text-tx-dim")}>
          {known ? value : "—"}
        </span>
        {known && pct !== undefined && (
          <span className="mt-1.5 h-[4px] w-full overflow-hidden rounded-full bg-white/10">
            <span className="block h-full rounded-full transition-[width] duration-700" style={{ width: `${Math.min(100, Math.max(0, pct))}%`, background: tone }} />
          </span>
        )}
        <span className="mt-0.5 truncate text-[10.5px] text-tx-dim">{known ? sub : unknown}</span>
      </span>
    </div>
  );
}

/* ── server health ────────────────────────────────────────────────────── */

type Check = { label: string; state: "ok" | "warn" | "bad" | "unknown"; note: string };

function buildChecks(data: VpsHeaderData, diskPct: number | null): Check[] {
  const memPct = data.live && data.live.maxMemBytes ? (data.live.memBytes / data.live.maxMemBytes) * 100 : null;
  const bwPct = data.bandwidth.allowanceTB
    ? ((data.bandwidth.inBytes + data.bandwidth.outBytes) / (data.bandwidth.allowanceTB * 1024 ** 4)) * 100
    : null;

  const lim = (v: number | null, warn: number, bad: number, okNote: string): Check["state"] =>
    v === null ? "unknown" : v >= bad ? "bad" : v >= warn ? "warn" : "ok";

  return [
    {
      label: "System",
      state: data.status === "RUNNING" ? "ok" : data.status === "SUSPENDED" || data.status === "ERROR" ? "bad" : "warn",
      note: data.status === "RUNNING" ? "Operating normally" : data.status.toLowerCase(),
    },
    {
      label: "CPU",
      state: lim(data.live?.cpuPct ?? null, 80, 95, ""),
      note: data.live ? (data.live.cpuPct >= 80 ? `At ${data.live.cpuPct.toFixed(0)}%` : "Within limits") : "Not reported",
    },
    {
      label: "Memory",
      state: lim(memPct, 85, 95, ""),
      note: memPct === null ? "Not reported" : memPct >= 85 ? `At ${memPct.toFixed(0)}%` : "Within limits",
    },
    {
      label: "Disk",
      state: lim(diskPct, 80, 92, ""),
      note: diskPct === null ? "Not measured" : diskPct >= 80 ? `${diskPct.toFixed(0)}% full` : "Healthy",
    },
    {
      label: "Bandwidth",
      state: lim(bwPct, 80, 95, ""),
      note: bwPct === null ? "No allowance set" : bwPct >= 80 ? `${bwPct.toFixed(0)}% used` : "Within allowance",
    },
    {
      /* Reachability we can actually attest to: the hypervisor answered for
         this VM. We do not probe port 22 from here, so this does not claim
         "SSH accessible" — that would be a guess dressed as a check. */
      label: "Hypervisor",
      state: data.pveUnavailable ? "warn" : data.live ? "ok" : "unknown",
      note: data.pveUnavailable ? "Didn't answer" : data.live ? "Reporting" : "No reading",
    },
  ];
}

const CHECK_INK: Record<Check["state"], { icon: string; ink: string }> = {
  ok: { icon: "checkcircle", ink: "text-emerald-300" },
  warn: { icon: "warntriangle", ink: "text-amber-300" },
  bad: { icon: "warncircle", ink: "text-rose-300" },
  unknown: { icon: "dotgrey", ink: "text-slate-500" },
};

function HealthCard({ data, diskPct, upgradeHref }: {
  data: VpsHeaderData; diskPct: number | null; upgradeHref: string;
}) {
  const checks = buildChecks(data, diskPct);
  const scored = checks.filter((c) => c.state !== "unknown");
  /* The score is the share of checks that PASSED, out of the checks we could
     actually make — and the coverage is stated next to it, always. A "100"
     resting on two of six readings is a confident grade on almost no evidence,
     which is exactly the kind of number this tree does not render bare. Below
     half coverage it is withheld entirely. */
  const covered = scored.length;
  const score = covered >= checks.length / 2
    ? Math.round((scored.reduce((a, c) => a + (c.state === "ok" ? 1 : c.state === "warn" ? 0.5 : 0), 0) / covered) * 100)
    : null;
  const strained = checks.some((c) => c.state !== "ok" && c.state !== "unknown" && ["CPU", "Memory", "Disk", "Bandwidth"].includes(c.label));

  const ring = score === null ? "#64748b" : score >= 90 ? "#34d399" : score >= 70 ? "#f59e0b" : "#f43f5e";
  const C = 2 * Math.PI * 34;

  return (
    <Panel title="Server health" accent="#50b4ff" icon="shieldcheck" ink="text-sky-300">
      <div className="flex items-center gap-4">
        <div className="relative grid h-[80px] w-[80px] flex-none place-items-center">
          <svg viewBox="0 0 80 80" className="absolute inset-0 -rotate-90">
            <circle cx="40" cy="40" r="34" fill="none" stroke="rgb(120 175 255 / 0.12)" strokeWidth="7" />
            {score !== null && (
              <circle
                cx="40" cy="40" r="34" fill="none" stroke={ring} strokeWidth="7" strokeLinecap="round"
                strokeDasharray={C} strokeDashoffset={C - (score / 100) * C}
                style={{ transition: "stroke-dashoffset .9s cubic-bezier(.4,0,.2,1)", filter: `drop-shadow(0 0 6px ${ring}66)` }}
              />
            )}
          </svg>

