export function VpsActivityCard({ items, href }: {
  items: { id: string; kind: string; label: string; detail: string | null; at: string }[];
  href: string;
}) {
  const INK: Record<string, { icon: string; ink: string }> = {
    job: { icon: "activity", ink: "text-sky-300" },
    login: { icon: "unlock", ink: "text-emerald-300" },
    failed: { icon: "lock", ink: "text-amber-300" },
    logout: { icon: "logout", ink: "text-slate-300" },
