  return (
    <Panel title="Recent activity" accent="#a78bfa" icon="activity" ink="text-violet-300" action={<a href={href} className="text-[11.5px] font-semibold text-brand-300 hover:text-tx">View all →</a>}>
      {items.length === 0 ? (
        <p className="text-[12px] text-tx-faint">Nothing has happened to this server yet.</p>
      ) : (
        <ul className="flex flex-col gap-2">
          {items.map((e) => {
            const k = INK[e.kind] ?? INK.job;
            return (
              <li key={e.id} className="flex items-center gap-2.5">
                <Icon name={k.icon} size={13} tone="inherit" className={`flex-none ${k.ink}`} />
