"use client";

import { useEffect, useState } from "react";
import { createHostingDatabase, listHostingDatabases, revealHostingDbPassword, resetHostingDbPassword, type HostingDbView } from "@/lib/actions-hosting";
import { DbManager } from "./DbManager";

/** Database create/list UI for a hosting account. The database manager is Nxeon DB
 *  Studio (the proprietary in-portal manager — see DbManager), which runs all SQL
 *  server-side as the account's scoped MySQL user. (The old Adminer drop-in fallback
 *  has been removed.) */
export function DatabasesPanel({ accountId, username, maxDatabases }: { accountId: string; username: string; maxDatabases: number }) {
  const [dbs, setDbs] = useState<HostingDbView[]>([]);
  const [dbLabel, setDbLabel] = useState("");
  const [dbBusy, setDbBusy] = useState(false);
  const [dbErr, setDbErr] = useState("");
  const [newDbPassword, setNewDbPassword] = useState<{ name: string; password: string } | null>(null);

  useEffect(() => { listHostingDatabases(accountId).then(setDbs).catch(() => {}); }, [accountId]);

  async function addDb() {
    if (!dbLabel.trim()) return;
    setDbBusy(true);
    setDbErr("");
    try {
      const res = await createHostingDatabase(accountId, dbLabel.trim());
      if (res.error) setDbErr(res.error);
      else {
        setNewDbPassword({ name: `${username}_${dbLabel.trim().toLowerCase().replace(/[^a-z0-9]/g, "").slice(0, 12) || "db"}`, password: res.password ?? "" });
        setDbLabel("");
        listHostingDatabases(accountId).then(setDbs).catch(() => {});
      }
    } finally {
      setDbBusy(false);
    }
  }

  if (maxDatabases <= 0) {
    return <p className="text-sm text-slate-400">Databases aren’t included on this plan. Upgrade to add MySQL databases.</p>;
  }

  return (
    <div className="space-y-4">
      {/* PRIMARY: proprietary in-portal manager (Nxeon DB Studio). */}
      <DbManager accountId={accountId} />

      <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2">
        <div className="mb-1 flex items-center justify-between">
          <p className="text-sm font-medium text-slate-300">
            Databases <span className="text-xs text-slate-500">({dbs.length}/{maxDatabases})</span>
          </p>
        </div>
        <p className="mb-1 text-[11px] text-slate-500">
          Create databases here, then browse and query them in <span className="text-slate-400">Nxeon DB Studio</span> above.
        </p>
        {dbs.length > 0 && (
          <ul className="mb-2 space-y-1 text-xs">
            {dbs.map((d) => (
              <DbRow key={d.id} db={d} />
            ))}
          </ul>
        )}
        {newDbPassword && (
          <div className="mb-2 rounded border border-emerald-500/30 bg-emerald-500/10 px-2 py-1.5 text-xs text-emerald-200">
            Created <span className="font-mono">{newDbPassword.name}</span> — password (shown once):{" "}
            <span className="font-mono">{newDbPassword.password}</span>
          </div>
        )}
        {dbs.length < maxDatabases ? (
          <div className="flex items-center gap-2">
            <input className="input flex-1 text-xs" placeholder="database name" value={dbLabel} onChange={(e) => setDbLabel(e.target.value)} />
            <button className="btn-secondary text-xs" disabled={dbBusy || !dbLabel.trim()} onClick={addDb}>{dbBusy ? "…" : "Create"}</button>
          </div>
        ) : (
          <p className="text-xs text-slate-500">You’ve used all the databases on your plan.</p>
        )}
        {dbErr && <p className="mt-1 text-xs text-amber-300">{dbErr}</p>}
      </div>
    </div>
  );
}

/** One database row with inline "Show password" + "Reset" controls. Mirrors the
 *  SFTP reveal UX (HostingTabs) — the password is shown inline in mono, and a reset
 *  shows the freshly-generated password once with a "queued" note. */
function DbRow({ db }: { db: HostingDbView }) {
  const [pw, setPw] = useState<string | null>(null);
  const [reset, setReset] = useState<string | null>(null);
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState<"show" | "reset" | null>(null);

  async function show() {
    setBusy("show");
    setErr("");
    try {
      const res = await revealHostingDbPassword(db.id);
      if (res.error) setErr(res.error);
      else setPw(res.password ?? "");
    } finally {
      setBusy(null);
    }
  }

  async function doReset() {
    setBusy("reset");
    setErr("");
    try {
      const res = await resetHostingDbPassword(db.id);
      if (res.error) setErr(res.error);
      else {
        setReset(res.password ?? "");
        setPw(res.password ?? "");
      }
    } finally {
      setBusy(null);
    }
  }

  return (
    <li className="text-slate-400">
      <div className="flex flex-wrap items-center gap-2">
        <span className="font-mono text-slate-200">{db.name}</span>
        <span className="text-slate-500">user {db.dbUser}</span>
        <span className={db.status === "ACTIVE" ? "text-emerald-300" : "text-amber-300"}>{db.status.toLowerCase()}</span>
        {pw ? (
          <span className="font-mono text-brand-200">{pw}</span>
        ) : (
          <button type="button" className="text-brand-300 hover:underline disabled:opacity-50" disabled={busy !== null} onClick={show}>
            {busy === "show" ? "…" : "Show password"}
          </button>
        )}
        <button type="button" className="text-slate-400 hover:underline disabled:opacity-50" disabled={busy !== null} onClick={doReset}>
          {busy === "reset" ? "…" : "Reset"}
        </button>
      </div>
      {reset && (
        <p className="mt-0.5 text-[11px] text-emerald-300/90">
          New password (shown once): <span className="font-mono text-emerald-200">{reset}</span> — queued, active in a moment.
        </p>
      )}
      {err && <p className="mt-0.5 text-[11px] text-amber-300">{err}</p>}
    </li>
  );
}
################ CronPanel
"use client";

import { useCallback, useEffect, useState } from "react";
import {
  listHostingCrons,
  createCron,
  deleteCron,
  type HostingCronView,
} from "@/lib/actions-hosting";
import { StatusPill } from "@/components/customer/cpanel/shared";

const PRESETS: { label: string; value: string }[] = [
  { label: "Every 5 minutes", value: "*/5 * * * *" },
  { label: "Every hour", value: "0 * * * *" },
  { label: "Every day at 03:00", value: "0 3 * * *" },
  { label: "Every Monday at 06:00", value: "0 6 * * 1" },
  { label: "First of the month", value: "0 0 1 * *" },
];

export function CronPanel({ accountId, username }: { accountId: string; username: string }) {
  const [rows, setRows] = useState<HostingCronView[] | null>(null);
  const [schedule, setSchedule] = useState("0 3 * * *");
  const [command, setCommand] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");

  const refresh = useCallback(() => {
    listHostingCrons(accountId).then(setRows).catch(() => setRows([]));
  }, [accountId]);

  useEffect(() => { refresh(); }, [refresh]);
  useEffect(() => {
    if (!rows?.some((r) => r.status === "PENDING" || r.status === "DELETING")) return;
    const t = setInterval(refresh, 4000);
    return () => clearInterval(t);
  }, [rows, refresh]);

  async function add() {
    if (command.trim().length < 2) return;
    setBusy(true); setErr("");
    const r = await createCron(accountId, schedule.trim(), command.trim());
    setBusy(false);
    if (r.error) setErr(r.error);
    else { setCommand(""); refresh(); }
  }

  return (
    <div className="space-y-6">
      <div className="card">
        <h3 className="mb-1 font-semibold">Add a cron job</h3>
        <p className="mb-4 text-sm text-slate-400">
          Schedules run as your account user <code className="font-mono text-xs text-brand-300">{username}</code> — confined to your own hosting environment.
        </p>
        <div className="grid gap-3">
          <div className="flex flex-wrap items-end gap-3">
            <div>
              <label className="label">Schedule</label>
              <input className="input w-40 font-mono" value={schedule} onChange={(e) => setSchedule(e.target.value)} disabled={busy} />
            </div>
            <div>
              <label className="label">Preset</label>
              <select className="input w-56" value="" onChange={(e) => e.target.value && setSchedule(e.target.value)} disabled={busy}>
                <option value="">Choose…</option>
                {PRESETS.map((p) => (<option key={p.value} value={p.value}>{p.label} ({p.value})</option>))}
              </select>
            </div>
          </div>
          <div>
            <label className="label">Command</label>
            <input className="input font-mono" placeholder="php /home/you/public_html/cron.php" value={command} onChange={(e) => setCommand(e.target.value)} disabled={busy} maxLength={500} />
          </div>
          <div>
            <button className="btn-primary" onClick={add} disabled={busy || command.trim().length < 2}>{busy ? "Working…" : "Add cron job"}</button>
          </div>
        </div>
        {err && <p className="mt-2 text-sm text-red-400">{err}</p>}
      </div>

      <div className="card p-0">
        <p className="section-label px-4 pt-4">Cron jobs</p>
        {rows === null ? (
          <p className="px-4 py-6 text-sm text-slate-500">Loading…</p>
        ) : rows.length === 0 ? (
          <p className="px-4 py-6 text-sm text-slate-500">No cron jobs yet. Schedule recurring commands — backups, cache warmers, cleanup.</p>
        ) : (
          <table className="table-shell mt-2">
            <thead>
              <tr>
                <th>Schedule</th>
                <th>Command</th>
                <th>Status</th>
                <th className="text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((r) => {
                const settling = r.status === "PENDING" || r.status === "DELETING";
                return (
                  <tr key={r.id}>
                    <td className="font-mono text-xs text-slate-100">{r.schedule}</td>
                    <td><div className="max-w-md truncate font-mono text-xs text-slate-300" title={r.command}>{r.command}</div></td>
                    <td><StatusPill status={r.status} /></td>
                    <td>
                      <div className="flex items-center justify-end">
                        <button
                          className="btn-danger px-2.5 py-1 text-xs"
                          disabled={settling}
                          onClick={() => { if (confirm("Delete this cron job?")) deleteCron(r.id).then((res) => { if (res.error) alert(res.error); else refresh(); }); }}
                        >
                          Delete
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}
