"use client";

"use client";

import { useEffect, useState } from "react";
import { listHostingUpgradePlans, upgradeHostingPlan, type UpgradePlanView } from "@/lib/actions-hosting";

function money(cents: number): string {
  return `$${(cents / 100).toFixed(2)}`;
}

/**
 * Plan picker for upgrading a hosting account. Lists the larger plans the account
 * may move UP to (from listHostingUpgradePlans) with the exact price delta charged
 * now, and confirms before charging the wallet via upgradeHostingPlan. Up-only —
 * the server re-checks and never downgrades.
 */
export function PlanUpgrade({ accountId }: { accountId: string }) {
  const [plans, setPlans] = useState<UpgradePlanView[] | null>(null);
  const [busyId, setBusyId] = useState<string | null>(null);
  const [err, setErr] = useState("");
  const [done, setDone] = useState(false);

  useEffect(() => {
    listHostingUpgradePlans(accountId).then((r) => { if (!r.error) setPlans(r.plans ?? []); else setPlans([]); }).catch(() => setPlans([]));
  }, [accountId]);

  async function upgrade(p: UpgradePlanView) {
    if (!window.confirm(`Upgrade to ${p.name}? Your wallet will be charged ${money(p.deltaCents)} now (the price difference for this term).`)) return;
    setBusyId(p.id); setErr("");
    const res = await upgradeHostingPlan(accountId, p.id);
    setBusyId(null);
    if (res.error) { setErr(res.error); return; }
    setDone(true);
    // Reflect the new plan across the page.
    setTimeout(() => window.location.reload(), 900);
  }

  if (plans === null) return <p className="text-xs text-slate-500">Loading upgrade options…</p>;
  if (done) return <p className="text-sm text-emerald-300">Plan upgraded — applying the new limits…</p>;
  if (plans.length === 0) return <p className="text-xs text-slate-500">You’re on our largest plan. Nothing bigger to move up to.</p>;

  return (
    <div>
      <p className="mb-3 text-sm font-medium text-slate-300">Upgrade your plan</p>
      <p className="mb-3 text-xs text-slate-500">
        Move up to a larger plan instantly. You’re charged only the price difference for the current term; your renewal date doesn’t change.
      </p>
      <div className="space-y-2">
        {plans.map((p) => (
          <div key={p.id} className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2">
            <div className="min-w-0">
              <p className="text-sm font-medium text-slate-200">{p.name}</p>
              <p className="text-xs text-slate-500">
                {p.diskGB} GB · {p.maxSites} site{p.maxSites === 1 ? "" : "s"} · {p.maxDatabases} database{p.maxDatabases === 1 ? "" : "s"}
                {p.tagline ? ` · ${p.tagline}` : ""}
              </p>
            </div>
            <button
              type="button"
              className="btn-secondary whitespace-nowrap text-xs"
              disabled={busyId !== null}
              onClick={() => upgrade(p)}
            >
              {busyId === p.id ? "Upgrading…" : `Upgrade (+${money(p.deltaCents)})`}
            </button>
          </div>
        ))}
      </div>
      {err && <p className="mt-2 text-xs text-amber-300">{err}</p>}
    </div>
  );
}
############ upgrade plans action
export type UpgradePlanView = {
  id: string;
  name: string;
  priceCents: number;
  diskGB: number;
  maxSites: number;
  maxDatabases: number;
  bandwidthTB: number;
  tagline: string;
  /** How much more than the current plan, per term — the delta charged now. */
  deltaCents: number;
};

/** The higher plans an account may move UP to (never a downgrade): active plans
 *  priced at-or-above and disk at-or-above the current plan, and strictly larger
 *  in at least one, excluding the current plan. Owner or admin. */
export async function listHostingUpgradePlans(accountId: string): Promise<{ currentPlanName?: string; plans?: UpgradePlanView[]; error?: string }> {
  const user = await requireUser();
  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, include: { plan: true } });
  if (!a) return { error: "Account not found." };
  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  const cur = a.plan;
  const all = await db.hostingPlan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } });
  const plans = all
    .filter((p) => p.id !== cur.id && p.priceCents >= cur.priceCents && p.diskGB >= cur.diskGB && (p.priceCents > cur.priceCents || p.diskGB > cur.diskGB))
    .map((p) => ({
      id: p.id, name: p.name, priceCents: p.priceCents, diskGB: p.diskGB, maxSites: p.maxSites,
      maxDatabases: p.maxDatabases, bandwidthTB: p.bandwidthTB, tagline: p.tagline,
      deltaCents: Math.max(0, p.priceCents - cur.priceCents),
    }));
  return { currentPlanName: cur.name, plans };
}

/**
 * Move a hosting account UP to a larger plan. Same purchase discipline as
 * orderHostingAccount: no spending while impersonating, wallet charge in the same
 * tx that mutates the account.
 *
 * Billing choice (kept simple + honest): we charge the FULL per-term price
 * DIFFERENCE (new − current) now, and leave the renewal date unchanged; future
 * terms bill at the new plan price. No mid-term proration or refunds — that keeps
 * the flow one debit and never owes the customer money back. The customer sees the
 * exact delta before confirming. Only UP is allowed (a downgrade would need a
 * refund path we don't have).
 */
export async function upgradeHostingPlan(accountId: string, newPlanId: string): Promise<HostingResult> {
  const user = await requireUser();
  await assertNotImpersonating();
  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, include: { plan: true } });
  if (!a) return { error: "Account not found." };
  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  if (a.status !== "ACTIVE") return { error: "The account is still being set up." };
  const newPlan = await db.hostingPlan.findUnique({ where: { id: newPlanId } });
  if (!newPlan || !newPlan.active) return { error: "That plan isn’t available." };
  if (newPlan.id === a.planId) return { error: "You’re already on this plan." };
  const cur = a.plan;
  // Up-only guard (re-checked server-side; never trust the client's picker).
  if (newPlan.priceCents < cur.priceCents || newPlan.diskGB < cur.diskGB) {
    return { error: "You can only move to a larger plan." };
  }
  const limits = planLimits(newPlan);
  const chargeCents = Math.max(0, newPlan.priceCents - cur.priceCents);
  if (user.balanceCents < chargeCents) return { error: "Insufficient balance. Top up your wallet first." };

  try {
    await db.$transaction(async (tx) => {
      if (chargeCents > 0) {
        await debitWallet(tx, user.id, chargeCents);
        await tx.walletTransaction.create({
          data: { userId: user.id, amountCents: -chargeCents, description: `Web Hosting upgrade: ${cur.name} → ${newPlan.name} for ${a.primaryDomain}` },
        });
      }
      // Snapshot the new plan's limits onto the account (same as orderHostingAccount
      // does at creation), so a later plan edit can't silently re-quota this account.
      // phpVersion is left as-is: an upgrade only widens the allowed set.
      await tx.hostingAccount.update({
        where: { id: a.id },
        data: { planId: newPlan.id, diskQuotaMB: limits.diskGB * 1024, maxSites: limits.maxSites, maxDatabases: limits.maxDatabases },
      });
      // Enact the node-level change (raise disk quota + rewrite FPM pool).
      await tx.hostingTask.create({ data: { accountId: a.id, kind: "APPLY_PLAN_LIMITS" } });
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance. Top up your wallet first." };
    return { error: "Couldn’t upgrade the plan. Your wallet was not charged — try again." };
  }

  await db.auditLog.create({ data: { userId: user.id, action: "hosting.upgrade", detail: `${cur.name} → ${newPlan.name} · ${a.primaryDomain}` } }).catch(() => {});
  revalidatePath(`/dashboard/hosting/${accountId}`);
  return { ok: true };
}

export async function createHostingBackup(accountId: string): Promise<HostingResult> {
  const ctx = await ownedActiveAccount(accountId);
  if ("error" in ctx) return { error: ctx.error };
  // Rate-limit: one backup task in flight at a time.
  const inFlight = await db.hostingTask.findFirst({ where: { accountId, kind: "BACKUP", status: { in: ["PENDING", "RUNNING"] } } });
  if (inFlight) return { error: "A backup is already running." };
  await db.hostingTask.create({ data: { accountId, kind: "BACKUP" } });

