/// An ADDITIONAL, FOLDER-SCOPED SFTP login on a hosting account.
///
/// The account itself has exactly one credential (HostingAccount.username +
/// sftpPasswordEnc), chrooted to /home/<username> by the sshd include the
/// provisioner writes. That is all-or-nothing: handing a developer the account
/// password hands them every site on the plan. This model is the second axis —
/// extra unix users whose sshd `Match User` block chroots them to ONE directory
/// inside the account, so "FTP user A sees only /domains/shop.com, FTP user B
/// sees only /subdomains/blog" is enforced by sshd, not by the panel.
///
/// `scopeKey` is the site key the customer picked ("account" for the whole plan,
/// else "primary" / "subdomain:<id>" / "addon:<id>"); `chrootPath` is the
/// chroot-relative directory that key resolved to AT CREATION TIME, frozen so a
/// later rename cannot silently widen an existing login's reach. Both are
/// re-derived and re-validated in the worker before anything reaches a shell.
///
/// `passwordEnc` is persistent (not cleared after first read) because an SFTP
/// login has no other recovery path — the customer must be able to look it up
/// again, exactly like HostingAccount.sftpPasswordEnc. Reveal is owner-only and
/// blocked under impersonation.
model HostingFtpUser {
  id          String                @id @default(cuid())
  accountId   String
  account     HostingAccount        @relation(fields: [accountId], references: [id], onDelete: Cascade)
  /// Real unix username on the node: <account.username>_<label>. Globally unique
  /// because a node's /etc/passwd is one namespace.
  username    String                @unique
  /// Customer-facing label (the part after the underscore). Lowercase alnum.
  label       String
  /// Site key this login was scoped to: "account" | "primary" | "subdomain:<id>" | "addon:<id>".
  scopeKey    String                @default("account")
  /// The chroot-relative directory the login is confined to, e.g. "" (whole
  /// account home), "public_html", "domains/shop.com", "subdomains/blog".
  chrootPath  String                @default("")
  /// Read-only logins get their unix account removed from the account's write
  /// group, so sshd/internal-sftp refuses writes. Enforced by POSIX, not the UI.
  readOnly    Boolean               @default(false)
  passwordEnc String?
  status      HostingResourceStatus @default(PENDING)
  error       String?
  lastLoginAt DateTime?
  createdAt   DateTime              @default(now())

  @@unique([accountId, label])
  @@index([accountId])
}

/// The picture shown for ONE website on a hosting account.
///
/// Three sources, and the row records which one it actually is so the UI never
/// implies a capture happened when it did not:
///   • CAPTURE — a real headless-Chromium screenshot of the live hostname, taken
///     server-side by the CAPTURE_SITE_THUMB task. `status` is PENDING until it
///     runs, FAILED (with `error`) when the site did not answer.
///   • UPLOAD  — bytes the customer supplied. Always READY.
/// No row at all = no picture; the UI falls back to the product's own stock
/// hosting plate, which is labelled as a placeholder rather than passed off as
/// the customer's site.
///
/// `hostname` is the name that was captured/uploaded FOR. When a site's hostname
/// changes (a promoted primary domain, say) the stored shot no longer depicts the
/// current site, and the UI says so instead of showing a stale picture as current.
///
/// Bytes live in Postgres like ChatAttachment/SignatureImage — a thumbnail is
/// ~100-300 KB and this keeps it off a disk path that would need its own backup
/// and its own permissions story.
model HostingSiteThumb {
  id         String         @id @default(cuid())
  accountId  String
  account    HostingAccount @relation(fields: [accountId], references: [id], onDelete: Cascade)
  /// "primary" | "subdomain:<id>" | "addon:<id>" — same keys as HostingWebsiteView.key.
  siteKey    String
  hostname   String
  /// CAPTURE | UPLOAD
  source     String
  /// PENDING | READY | FAILED
  status     String         @default("PENDING")
  mime       String?
  sizeBytes  Int            @default(0)
  width      Int?
  height     Int?
  data       Bytes?
  error      String?
  capturedAt DateTime?
  createdAt  DateTime       @default(now())
  updatedAt  DateTime       @updatedAt

  @@unique([accountId, siteKey])
  @@index([accountId])
}

