input.content:
/**
 * Shared vocabulary for "a website on a hosting account", and for the
 * folder-scoped SFTP logins that point at one.
 *
 * A shared-hosting plan is the unit of billing and of every limit. A WEBSITE is
 * the unit the customer actually works in, and a plan holds several: the primary
 * domain, plus each subdomain and each addon domain. Those three live in three
 * different tables, so everything that needs to name one uses a SITE KEY —
 * `"primary"`, `"subdomain:<id>"`, `"addon:<id>"` — which is exactly the `key`
 * `listWebsites()` already returns.
 *
 * This module is a plain (non-"use server") module on purpose: the worker daemon
 * imports the same path derivation the server actions validate against, so the
 * panel and the box can never disagree about which directory a scoped login was
 * confined to. Same discipline as lib/mod-install-support.ts.
 *
 * WHAT IS AND IS NOT ISOLATED, because the UI is required to be honest about it:
 *   • Files ARE separated per website — each site has its own docroot under the
 *     account home (`public_html`, `subdomains/<label>/public_html`,
 *     `domains/<domain>/public_html`), which is why a scoped SFTP login is
 *     meaningful at all.
 *   • Databases are NOT. Every database on the account is granted to the same
 *     account-level MySQL user and reachable from every site's PHP, because all
 *     the sites run in one FPM pool as one unix user. `HostingDatabase.siteKey`
 *     is a label the customer sets, and the panel calls it that.
 */

/* ── site keys ────────────────────────────────────────────────────────── */

export type SiteKind = "primary" | "subdomain" | "addon";

export type ParsedSiteKey =
  | { kind: "primary"; id: null }
  | { kind: "subdomain"; id: string }
  | { kind: "addon"; id: string };

const CUID_RE = /^[a-z0-9]{20,40}$/;

/** Parse a site key, or null if it is not one. Never throws. */
export function parseSiteKey(key: string | null | undefined): ParsedSiteKey | null {
  const k = String(key ?? "").trim();
  if (k === "primary") return { kind: "primary", id: null };
  const m = /^(subdomain|addon):([a-z0-9]+)$/.exec(k);
  if (!m || !CUID_RE.test(m[2])) return null;
  return { kind: m[1] as "subdomain" | "addon", id: m[2] };
}

export function isSiteKey(key: string | null | undefined): boolean {
  return parseSiteKey(key) !== null;
}

export function siteKeyOf(kind: SiteKind, id: string | null): string {
  return kind === "primary" || !id ? "primary" : `${kind}:${id}`;
}

/* ── the directories a site owns ──────────────────────────────────────── */

/**
 * The two chroot-relative paths a website occupies inside the account home.
 *
 * `container` is the directory that HOLDS the site — for the primary site that
 * is the account home itself; for a subdomain/addon it is the per-site wrapper
 * the provisioner created. `docroot` is what nginx serves.
 *
 * The split matters for scoped SFTP: sshd refuses to chroot into a directory any
 * non-root user can write, and the docroot is deliberately writable by the
 * account (WordPress uploads). So a scoped login chroots to the CONTAINER and
 * the customer lands one level above their `public_html` — which is also what
 * they need, because that is where a site's non-public files live.
 */
export function siteDirs(site: { kind: SiteKind; label?: string | null; domain?: string | null }): {
  container: string;
  docroot: string;
} {
  if (site.kind === "subdomain") {
    const label = String(site.label ?? "");
    return { container: `subdomains/${label}`, docroot: `subdomains/${label}/public_html` };
  }
  if (site.kind === "addon") {
    const domain = String(site.domain ?? "");
    return { container: `domains/${domain}`, docroot: `domains/${domain}/public_html` };
  }
  // The primary site is served straight out of the account home.
  return { container: "", docroot: "public_html" };
}

/* ── scoped SFTP logins ───────────────────────────────────────────────── */

/** How many extra logins one account may hold. Each is a real unix user on a
 *  shared node, so this is a resource bound, not a UI preference. */
export const MAX_FTP_USERS = 8;

/** "account" means the whole plan — every site, the account home as the chroot. */
export const FTP_SCOPE_ACCOUNT = "account";

const FTP_LABEL_RE = /^[a-z0-9](?:[a-z0-9-]{0,14}[a-z0-9])?$/;

/**
 * A label for an extra login. Lowercase alnum with internal hyphens, ≤16 chars —
 * short because it becomes part of a unix username, and unix usernames are
 * length-bounded (32 on Linux) and must be shell-inert.
 */
export function isValidFtpLabel(label: string): boolean {
  return FTP_LABEL_RE.test(String(label ?? "").trim().toLowerCase());
}

/** The real unix username a label becomes: `<account>_<label>`, clipped to 32. */
export function ftpUsernameFor(accountUsername: string, label: string): string {
  return `${accountUsername}_${label}`.slice(0, 32);
}

/**
 * Is a chroot path one this account may actually hand out?
 *
 * Deliberately a strict allow-list of shapes rather than a traversal filter: the
 * only directories a scoped login may be confined to are the account home and
 * the per-site containers the provisioner itself creates. Anything else — an
 * absolute path, a `..`, a path into `tmp`, an invented directory — is refused
 * here AND re-refused in the worker before it reaches a shell.
 */
export function isValidFtpChroot(path: string): boolean {
  const p = String(path ?? "");
  if (p === "") return true; // the account home
  if (p.startsWith("/") || p.includes("..") || p.includes("//")) return false;
  if (p === "public_html") return true;
  if (/^subdomains\/[a-z0-9](?:[a-z0-9-]{0,30}[a-z0-9])?$/.test(p)) return true;
  if (/^domains\/[a-z0-9]([a-z0-9.-]{0,251}[a-z0-9])?$/.test(p)) return true;
  return false;
}

/** A human label for a chroot path, for the credentials list. */
export function ftpScopeLabel(chrootPath: string): string {
  if (!chrootPath) return "Whole account";
  if (chrootPath === "public_html") return "Main website files";
  const sub = /^subdomains\/(.+)$/.exec(chrootPath);
  if (sub) return `Subdomain · ${sub[1]}`;
  const dom = /^domains\/(.+)$/.exec(chrootPath);
  if (dom) return `Domain · ${dom[1]}`;
  return chrootPath;
}

/* ── thumbnails ───────────────────────────────────────────────────────── */

/** Capture size. 16:10 because that is the aspect the website cards draw at, and
 *  a capture that has to be re-cropped in CSS wastes half the bytes it stores. */
export const THUMB_WIDTH = 1280;
export const THUMB_HEIGHT = 800;

/** Hard cap on a stored thumbnail, capture or upload. */
export const MAX_THUMB_BYTES = 4 * 1024 * 1024;

export type ThumbSource = "CAPTURE" | "UPLOAD";
export type ThumbStatus = "PENDING" | "READY" | "FAILED";

