"use server";

/**
 * Per-website management for a shared-hosting account.
 *
 * The account is the unit of billing and of every limit; a WEBSITE is the unit
 * the customer works in. Everything here is scoped to one website inside one
 * account, plus the two account-level things the redesigned panel needed and the
 * platform did not have: extra SFTP logins that can be confined to one site's
 * folder, and a picture of what a site actually looks like.
 *
 * Guard discipline is copied from lib/actions-hosting.ts and must stay copied:
 * `requireUser()` for identity, owner-or-admin on every row, `assertNotImpersonating()`
 * on anything that mints a credential or spends money, and a Serializable
 * transaction wherever a plan cap is being counted against.
 */

import { randomBytes } from "node:crypto";
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser, assertNotImpersonating } from "./auth";
import { SANDBOX } from "./sandbox";
import { encryptSecret, decryptSecret } from "./crypto-box";
import { debitWallet, InsufficientBalanceError } from "./wallet";
import { isValidUnixUsername } from "./hosting";
import {
  extraDiskCentsAt,
  extraDiskProrateCents,
  effectiveDiskGB,
  isValidExtraDiskAddGB,
  maxAddableExtraDiskGB,
  normalizeExtraDiskGB,
  EXTRA_DISK_STEP_GB,
  EXTRA_DISK_MIN_GB,
} from "./extra-disk";
import { extraDiskPerGbCents } from "./disk-expand";
import { remainingMonths } from "./proration";
import {
  parseSiteKey,
  siteDirs,
  isValidFtpLabel,
  isValidFtpChroot,
  ftpUsernameFor,
  ftpScopeLabel,
  MAX_FTP_USERS,
  FTP_SCOPE_ACCOUNT,
  type SiteKind,
} from "./hosting-sites";

type Fail = { error: string };
type Ok = { ok: true };
export type SiteResult = { ok?: boolean; error?: string };

/* ── ownership ────────────────────────────────────────────────────────── */

/**
 * Owner-or-admin on an account, optionally requiring it to be live.
 *
 * Same three refusals the hosting actions already use, in the same order, so a
 * customer gets the same wording here as everywhere else: not found → forbidden
 * → still provisioning.
 */
async function ownedAccount(accountId: string, opts: { active?: boolean } = {}) {
  const user = await requireUser();
  const a = await db.hostingAccount.findUnique({
    where: { id: accountId },
    select: {
      id: true, userId: true, status: true, username: true, primaryDomain: true,
      diskQuotaMB: true, extraDiskGB: true, expiresAt: true, planId: true,
      plan: { select: { diskGB: true, name: true } },
    },
  });
  if (!a) return { error: "Account not found." as const };
  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." as const };
  if (opts.active && a.status !== "ACTIVE") return { error: "The account is still being set up." as const };
  return { user, a };
}

/** Resolve a site key to the row it names, on THIS account. Null if it isn't one
 *  of this account's sites — which is the cross-tenant guard for every action
 *  below that takes a siteKey from the client. */
async function resolveSite(accountId: string, siteKey: string): Promise<
  { kind: SiteKind; id: string | null; hostname: string; container: string; docroot: string } | null
> {
  const parsed = parseSiteKey(siteKey);
  if (!parsed) return null;
  if (parsed.kind === "primary") {
    const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { primaryDomain: true } });
    if (!a) return null;
    const d = siteDirs({ kind: "primary" });
    return { kind: "primary", id: null, hostname: a.primaryDomain, ...d };
  }
  if (parsed.kind === "subdomain") {
    const s = await db.hostingSubdomain.findFirst({
      where: { id: parsed.id, accountId, status: { not: "DELETING" } },
      select: { id: true, label: true, fqdn: true },
    });
    if (!s) return null;
    const d = siteDirs({ kind: "subdomain", label: s.label });
    return { kind: "subdomain", id: s.id, hostname: s.fqdn, ...d };
  }
  const ad = await db.hostingAddonDomain.findFirst({
    where: { id: parsed.id, accountId, status: { not: "DELETING" } },
    select: { id: true, domain: true },
  });
  if (!ad) return null;
  const d = siteDirs({ kind: "addon", domain: ad.domain });
  return { kind: "addon", id: ad.id, hostname: ad.domain, ...d };
}

/* ══ website thumbnails ═══════════════════════════════════════════════════ */

export type SiteThumbView = {
  siteKey: string;
  /** The hostname the picture was taken/uploaded FOR. */
  hostname: string;
  source: "CAPTURE" | "UPLOAD";
  status: "PENDING" | "READY" | "FAILED";
  /** True when the site's hostname has changed since — the picture is of a name
   *  this site no longer answers on, so the UI must not present it as current. */
  stale: boolean;
  error: string | null;
  capturedAt: string | null;
  /** Where to fetch the bytes, or null when there are none yet. */
  url: string | null;
};

/** Every stored picture on an account, keyed by site. Owner or admin. */
export async function listSiteThumbs(accountId: string): Promise<SiteThumbView[]> {
  const ctx = await ownedAccount(accountId);
  if ("error" in ctx) return [];
  const rows = await db.hostingSiteThumb.findMany({
    where: { accountId },
    select: {
      id: true, siteKey: true, hostname: true, source: true, status: true,
      error: true, capturedAt: true, updatedAt: true, sizeBytes: true,
    },
  });
  // Resolve each key's CURRENT hostname so a stale picture can be flagged rather
  // than shown as though it depicts the site as it is now.
  const current = new Map<string, string>();
  const [subs, addons] = await Promise.all([
    db.hostingSubdomain.findMany({ where: { accountId }, select: { id: true, fqdn: true } }),
    db.hostingAddonDomain.findMany({ where: { accountId }, select: { id: true, domain: true } }),
  ]);
  current.set("primary", ctx.a.primaryDomain);
  for (const s of subs) current.set(`subdomain:${s.id}`, s.fqdn);
  for (const d of addons) current.set(`addon:${d.id}`, d.domain);

  return rows.map((r) => ({
    siteKey: r.siteKey,
    hostname: r.hostname,
    source: r.source as "CAPTURE" | "UPLOAD",
    status: r.status as "PENDING" | "READY" | "FAILED",
    stale: (current.get(r.siteKey) ?? r.hostname) !== r.hostname,
    error: r.error,
    capturedAt: r.capturedAt?.toISOString() ?? null,
    // Cache-bust on updatedAt so a re-capture replaces the picture immediately.
    url: r.status === "READY" && r.sizeBytes > 0
      ? `/api/hosting/thumb?id=${r.id}&v=${r.updatedAt.getTime()}`
      : null,
  }));
}

/**
 * Queue a REAL screenshot of one site's homepage.
 *
 * The capture itself is a HostingTask (`CAPTURE_SITE_THUMB`) run by the worker
 * with headless Chromium against the site's public hostname — see
 * lib/hosting-thumb.ts. Nothing is drawn here; the row goes to PENDING and the
 * panel shows "capturing" until the worker writes bytes or an error.
 *
 * Refused for a site that isn't serving yet, because a capture of a domain that
 * does not resolve produces a picture of an error page, and an error page
 * presented as "your website" is worse than no picture.
 */
export async function captureSiteThumb(accountId: string, siteKey: string): Promise<SiteResult> {
  const ctx = await ownedAccount(accountId, { active: true });
  if ("error" in ctx) return { error: ctx.error };
  const site = await resolveSite(accountId, siteKey);
  if (!site) return { error: "That website isn’t part of this account." };

  const existing = await db.hostingSiteThumb.findUnique({
    where: { accountId_siteKey: { accountId, siteKey } },
    select: { id: true, status: true },
  });
  if (existing?.status === "PENDING") return { error: "A capture is already running for this site." };

  await db.hostingSiteThumb.upsert({
    where: { accountId_siteKey: { accountId, siteKey } },
    create: { accountId, siteKey, hostname: site.hostname, source: "CAPTURE", status: "PENDING" },
    update: { hostname: site.hostname, source: "CAPTURE", status: "PENDING", error: null },
  });
  await db.hostingTask.create({
    data: { accountId, kind: "CAPTURE_SITE_THUMB", payload: JSON.stringify({ siteKey, hostname: site.hostname }) },
  });
  revalidatePath(`/dashboard/hosting/${accountId}`);
  return { ok: true };
}

/** Remove a site's stored picture entirely — back to the placeholder plate. */
export async function clearSiteThumb(accountId: string, siteKey: string): Promise<SiteResult> {
  const ctx = await ownedAccount(accountId);
  if ("error" in ctx) return { error: ctx.error };
  if (!parseSiteKey(siteKey)) return { error: "Unknown website." };
  await db.hostingSiteThumb.deleteMany({ where: { accountId, siteKey } });
  revalidatePath(`/dashboard/hosting/${accountId}`);
  return { ok: true };
}

/* ══ scoped SFTP logins ═══════════════════════════════════════════════════ */

