export async function listFtpScopes(accountId: string): Promise<{ key: string; label: string; path: string }[]> {
  const ctx = await ownedAccount(accountId);
  if ("error" in ctx) return [];
  const [subs, addons] = await Promise.all([
    db.hostingSubdomain.findMany({ where: { accountId, status: { not: "DELETING" } }, select: { id: true, label: true, fqdn: true } }),
    db.hostingAddonDomain.findMany({ where: { accountId, status: { not: "DELETING" } }, select: { id: true, domain: true } }),
  ]);
