  for (const d of addons) out.push({ key: `addon:${d.id}`, label: d.domain, path: siteDirs({ kind: "addon", domain: d.domain }).container });
  return out;
}

export async function listFtpUsers(accountId: string): Promise<FtpUserView[]> {
  const ctx = await ownedAccount(accountId);
  if ("error" in ctx) return [];
  const rows = await db.hostingFtpUser.findMany({ where: { accountId }, orderBy: { createdAt: "asc" } });
  return rows.map((r) => ({
    id: r.id,
    username: r.username,
    label: r.label,
    scopeKey: r.scopeKey,
    chrootPath: r.chrootPath,
    scopeLabel: ftpScopeLabel(r.chrootPath),
    readOnly: r.readOnly,
    status: r.status,
    error: r.error,
    createdAt: r.createdAt.toISOString(),
  }));
}

/**
 * Mint an extra SFTP login confined to one folder.
 *
 * The confinement is a unix user plus an sshd `Match User … ChrootDirectory`
 * block written by the worker — the SAME mechanism that already confines the
 * account's own login, and validated with `sshd -t` before any reload. The panel
 * therefore never claims the scope is in force: the row is PENDING until the
 * node reports back, and the credentials list says so.
 *
 * The cap is counted inside a Serializable transaction for the same reason
 * createHostingDatabase counts inside one — two concurrent creates must not both
 * read a stale count.
 */
export async function createFtpUser(
  accountId: string,
  labelRaw: string,
  scopeKey: string,
  readOnly: boolean,
): Promise<{ ok?: boolean; error?: string; username?: string; password?: string }> {
  const ctx = await ownedAccount(accountId, { active: true });
  if ("error" in ctx) return { error: ctx.error };
  await assertNotImpersonating();

  const label = String(labelRaw ?? "").trim().toLowerCase();
  if (!isValidFtpLabel(label)) {
    return { error: "Use 1–16 lowercase letters, numbers or hyphens for the login name." };
  }
  if (!isValidUnixUsername(ctx.a.username)) return { error: "This account isn’t ready for extra logins yet." };

  // Resolve the scope to a real directory on THIS account. "account" is the home.
  let chrootPath = "";
  if (scopeKey !== FTP_SCOPE_ACCOUNT) {
    const site = await resolveSite(accountId, scopeKey);
    if (!site) return { error: "That website isn’t part of this account." };
    // The primary site's own container IS the account home, so scoping "primary"
    // to the home would silently be the whole plan. Confine it to public_html
    // instead — which is what the customer means by "just the main website".
    chrootPath = site.kind === "primary" ? site.docroot : site.container;
  }
  if (!isValidFtpChroot(chrootPath)) return { error: "That folder can’t be used for a scoped login." };

  const username = ftpUsernameFor(ctx.a.username, label);
  if (!isValidUnixUsername(username)) return { error: "That login name doesn’t make a valid system user." };

  const password = randomBytes(18).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 24);

  try {
    await db.$transaction(async (tx) => {
      const n = await tx.hostingFtpUser.count({ where: { accountId, status: { in: ["PENDING", "ACTIVE"] } } });
      if (n >= MAX_FTP_USERS) throw new Error("CAP");
      const row = await tx.hostingFtpUser.create({
        data: {
          accountId, username, label, scopeKey: scopeKey || FTP_SCOPE_ACCOUNT,
          chrootPath, readOnly: !!readOnly,
          passwordEnc: encryptSecret(password), status: "PENDING",
        },
      });
      await tx.hostingTask.create({
        data: { accountId, kind: "CREATE_FTP_USER", payload: JSON.stringify({ ftpUserId: row.id }) },
      });
    }, { isolationLevel: "Serializable" });
  } catch (e) {
    if ((e as Error)?.message === "CAP") {
      return { error: `You can have up to ${MAX_FTP_USERS} extra SFTP logins on one account.` };
    }
    if ((e as { code?: string })?.code === "P2002") {
      return { error: "A login with that name already exists — pick another." };
    }
    return { error: "Couldn’t create that login. Nothing was changed." };
  }

  await db.auditLog.create({
    data: { userId: ctx.user.id, action: "hosting.ftp.create", detail: `${username} → ${chrootPath || "(account home)"}` },
  }).catch(() => {});
  revalidatePath(`/dashboard/hosting/${accountId}`);
  return { ok: true, username, password };
}

/** Reveal a scoped login's password. Owner only; never while impersonating —
 *  same rule as the account's own SFTP credential. */
export async function revealFtpPassword(id: string): Promise<{ password?: string; error?: string }> {
  const user = await requireUser();
  await assertNotImpersonating();
  const row = await db.hostingFtpUser.findUnique({
    where: { id },
    select: { passwordEnc: true, account: { select: { userId: true } } },
  });
  if (!row) return { error: "Not found." };
  if (row.account.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  if (!row.passwordEnc) return { error: "No password on record — reset it to set a new one." };
  return { password: decryptSecret(row.passwordEnc) };
}

/** Rotate a scoped login's password. Returns the new one once, and queues the
 *  node-side `chpasswd` — the credential is not live until that task completes. */
export async function resetFtpPassword(id: string): Promise<{ password?: string; error?: string }> {
  const user = await requireUser();
  await assertNotImpersonating();
  const row = await db.hostingFtpUser.findUnique({
    where: { id },
    select: { id: true, accountId: true, username: true, account: { select: { userId: true, status: true } } },
  });
  if (!row) return { error: "Not found." };
  if (row.account.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  if (row.account.status !== "ACTIVE") return { error: "The account is still being set up." };

  const password = randomBytes(18).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, 24);
  await db.hostingFtpUser.update({ where: { id }, data: { passwordEnc: encryptSecret(password), error: null } });
  await db.hostingTask.create({
    data: { accountId: row.accountId, kind: "RESET_FTP_PASSWORD", payload: JSON.stringify({ ftpUserId: row.id }) },
  });
  revalidatePath(`/dashboard/hosting/${row.accountId}`);
  return { password };
}

/** Remove a scoped login: the row flips to DELETING and the worker drops the
 *  sshd block and the unix user. The row is deleted by the worker, not here, so
 *  the panel can show the removal in flight instead of pretending it is done. */
export async function deleteFtpUser(id: string): Promise<SiteResult> {
  const user = await requireUser();
  await assertNotImpersonating();
  const row = await db.hostingFtpUser.findUnique({
    where: { id },
    select: { id: true, accountId: true, username: true, account: { select: { userId: true } } },
  });
  if (!row) return { error: "Not found." };
  if (row.account.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  await db.hostingFtpUser.update({ where: { id }, data: { status: "DELETING" } });
  await db.hostingTask.create({
    data: { accountId: row.accountId, kind: "DELETE_FTP_USER", payload: JSON.stringify({ ftpUserId: row.id }) },
  });
  await db.auditLog.create({
    data: { userId: user.id, action: "hosting.ftp.delete", detail: row.username },
  }).catch(() => {});
  revalidatePath(`/dashboard/hosting/${row.accountId}`);
  return { ok: true };
}

/* ══ database ↔ website association ═══════════════════════════════════════ */

/**
 * Record which website a database belongs to.
 *
 * A LABEL, not a boundary — see the note on HostingDatabase.siteKey. Every
 * database on the account is reachable from every site on it, because they share
 * one unix user and one account-scoped MySQL grant. This exists so the per-site
 * dashboard can show the customer which database that site's app uses, which is
 * the actual question they are asking.
 */
export async function setDatabaseSite(dbId: string, siteKey: string | null): Promise<SiteResult> {
  const user = await requireUser();
  const row = await db.hostingDatabase.findUnique({
    where: { id: dbId },
    select: { id: true, accountId: true, account: { select: { userId: true } } },
  });
  if (!row) return { error: "Not found." };
  if (row.account.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  if (siteKey) {
    const site = await resolveSite(row.accountId, siteKey);
    if (!site) return { error: "That website isn’t part of this account." };
  }
  await db.hostingDatabase.update({ where: { id: dbId }, data: { siteKey: siteKey || null } });
  revalidatePath(`/dashboard/hosting/${row.accountId}`);
  return { ok: true };
}

/* ══ storage add-on ═══════════════════════════════════════════════════════ */

export type StorageQuote = {
  planDiskGB: number;
  extraDiskGB: number;
  effectiveGB: number;
  /** Largest single purchase still allowed under the effective-disk ceiling. */
  maxAddGB: number;
  stepGB: number;
  minGB: number;
  perGbCents: number;
  /** Whole months left on the paid term — what the one-off charge prorates over. */
  monthsRemaining: number;
  /** For the amount asked about: the monthly add and the charge due now. */
  addGB: number;
  monthlyCents: number;
  chargeNowCents: number;
  walletCents: number;
};

/**
 * Price extra storage for a hosting account, using the SAME helpers the VPS
 * add-storage path uses (lib/extra-disk.ts + lib/proration.ts) so the figure a
 * customer is shown is the figure the charge is computed from. Nothing here
 * spends anything.
 */
export async function quoteHostingStorage(accountId: string, addGBRaw: number): Promise<StorageQuote | Fail> {
  const ctx = await ownedAccount(accountId);
  if ("error" in ctx) return { error: ctx.error };
  const planDiskGB = ctx.a.plan.diskGB;
  const extra = ctx.a.extraDiskGB ?? 0;
  const perGbCents = await extraDiskPerGbCents();
  const months = remainingMonths(ctx.a.expiresAt, Date.now());
  const addGB = normalizeExtraDiskGB(addGBRaw);
  const monthlyCents = extraDiskCentsAt(addGB, perGbCents);
  return {
    planDiskGB,
    extraDiskGB: extra,
    effectiveGB: effectiveDiskGB(planDiskGB, extra),
    maxAddGB: maxAddableExtraDiskGB(planDiskGB, extra),
    stepGB: EXTRA_DISK_STEP_GB,
    minGB: EXTRA_DISK_MIN_GB,
    perGbCents,
    monthsRemaining: months,
    addGB,
    monthlyCents,
    chargeNowCents: extraDiskProrateCents(monthlyCents, months),
    walletCents: ctx.user.balanceCents,
  };
}

/**
 * Buy extra storage for a hosting account, post-deploy.
 *
 * Until now extra storage could only be bought AT ORDER TIME (the deploy
 * wizard's slider); a customer who filled up had nothing to click. This is the
 * same shape as upgradeHostingPlan: one wallet debit, in the same transaction
 * that raises the quota, then an APPLY_PLAN_LIMITS task so the node's `setquota`
 * actually grows. No card fallback — a customer without the balance is told to
 * top up, rather than being taken through a second payment surface this action
 * cannot supervise.
 *
 * GROWTH IS ONE-WAY, exactly like the VPS path: a live filesystem quota is only
 * ever raised. The control says so before the money moves.
 */
export async function expandHostingStorage(accountId: string, addGBRaw: number): Promise<SiteResult> {
  const ctx = await ownedAccount(accountId, { active: true });
  if ("error" in ctx) return { error: ctx.error };
  await assertNotImpersonating();

  const addGB = normalizeExtraDiskGB(addGBRaw);
  if (!isValidExtraDiskAddGB(addGB)) {
    return { error: `Storage is sold in ${EXTRA_DISK_STEP_GB} GB steps, from ${EXTRA_DISK_MIN_GB} GB.` };
  }
  const planDiskGB = ctx.a.plan.diskGB;
  const extra = ctx.a.extraDiskGB ?? 0;
  const maxAdd = maxAddableExtraDiskGB(planDiskGB, extra);
  if (addGB > maxAdd) {
    return maxAdd === 0
      ? { error: "This account is already at the maximum storage we can attach. Contact support about a larger plan." }
      : { error: `You can add at most ${maxAdd} GB to this account in one go.` };
  }

  const perGbCents = await extraDiskPerGbCents();
  const monthlyCents = extraDiskCentsAt(addGB, perGbCents);
  const chargeCents = extraDiskProrateCents(monthlyCents, remainingMonths(ctx.a.expiresAt, Date.now()));
  if (ctx.user.balanceCents < chargeCents) {
    return { error: "Insufficient balance. Top up your wallet first." };
  }

  const newExtra = extra + addGB;
  // diskQuotaMB is the account's effective quota and ALWAYS already includes the
  // add-on (see the schema note), so both move together or neither does.
  const newQuotaMB = effectiveDiskGB(planDiskGB, newExtra) * 1024;

  try {
    await db.$transaction(async (tx) => {
      if (chargeCents > 0) {
        await debitWallet(tx, ctx.user.id, chargeCents);
        await tx.walletTransaction.create({
          data: {
            userId: ctx.user.id,
            amountCents: -chargeCents,
            description: `Web Hosting extra storage: +${addGB} GB for ${ctx.a.primaryDomain}`,
          },
        });
      }
      await tx.hostingAccount.update({
        where: { id: ctx.a.id },
        data: { extraDiskGB: newExtra, diskQuotaMB: newQuotaMB },
      });
      await tx.hostingTask.create({ data: { accountId: ctx.a.id, kind: "APPLY_PLAN_LIMITS" } });
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance. Top up your wallet first." };
    return { error: "Couldn’t add the storage. Your wallet was not charged — try again." };
  }

  await db.auditLog.create({
    data: { userId: ctx.user.id, action: "hosting.storage.add", detail: `+${addGB} GB · ${ctx.a.primaryDomain}` },
  }).catch(() => {});
  revalidatePath(`/dashboard/hosting/${accountId}`);
  return { ok: true };
}

/* ══ storage breakdown ════════════════════════════════════════════════════ */

export type StorageBreakdown = {
  /** Measured total, MB. Null when no sweep has run against a real node. */
  usedMB: number | null;
  quotaMB: number;
  inodes: number | null;
  measuredAt: string | null;
  /** One entry per measured directory. Empty when unmeasured — never invented. */
  parts: { path: string; label: string; mb: number }[];
  /** Backups live on the node OUTSIDE the account's quota, so they are reported
   *  separately rather than folded into the bar. */
  backupCount: number;
  backupBytes: number;
  /** Why there is nothing to show, when there is nothing to show. */
  note: string | null;
};

const DIR_LABELS: Record<string, string> = {
  public_html: "Main website",
  subdomains: "Subdomains",
  domains: "Addon domains",
  tmp: "Temporary files",
  logs: "Logs",
  ".cache": "Caches",
};

function labelForDir(path: string): string {
  if (DIR_LABELS[path]) return DIR_LABELS[path];
  const sub = /^subdomains\/([^/]+)/.exec(path);
  if (sub) return sub[1];
  const dom = /^domains\/([^/]+)/.exec(path);
  if (dom) return dom[1];
  return path;
}

/**
 * Where an account's storage is actually going.
 *
 * `usageBreakdown` is written by hostingUsageSweep in the same pass that writes
 * `diskUsedMB`, one `du -sm` per directory, so the parts and the total are
 * measured together. When it is null there has been no sweep — this returns an
 * empty `parts` and a `note` saying why, and the card renders the reason instead
 * of a chart of zeroes.
 */
export async function hostingStorageBreakdown(accountId: string): Promise<StorageBreakdown | Fail> {
  const ctx = await ownedAccount(accountId);
  if ("error" in ctx) return { error: ctx.error };
  const a = await db.hostingAccount.findUnique({
    where: { id: accountId },
    select: { diskUsedMB: true, diskQuotaMB: true, inodesUsed: true, usageAt: true, usageBreakdown: true, status: true },
  });
  if (!a) return { error: "Account not found." };

  const backups = await db.hostingBackup.findMany({ where: { accountId }, select: { sizeBytes: true } });

  let parts: { path: string; label: string; mb: number }[] = [];
  let note: string | null = null;
  if (a.usageBreakdown) {
    try {
      const parsed = JSON.parse(a.usageBreakdown) as { dirs?: { path: string; mb: number }[] };
      parts = (parsed.dirs ?? [])
        .filter((d) => typeof d?.path === "string" && Number.isFinite(d?.mb))
        .map((d) => ({ path: d.path, label: labelForDir(d.path), mb: Math.max(0, Math.round(d.mb)) }))
        .sort((x, y) => y.mb - x.mb);
    } catch {
      note = "The last usage reading couldn’t be read back.";
    }
  } else {
    note = SANDBOX
      ? "No hosting node is attached in this environment, so nothing has been measured."
      : a.status === "ACTIVE"
        ? "We haven’t measured this account yet — the first reading lands within a few minutes of going live."
        : "Measurement starts once the account is live.";
  }

  return {
    usedMB: a.diskUsedMB,
    quotaMB: a.diskQuotaMB,
    inodes: a.inodesUsed,
    measuredAt: a.usageAt?.toISOString() ?? null,
    parts,
    backupCount: backups.length,
    backupBytes: backups.reduce((s, b) => s + b.sizeBytes, 0),
    note,
  };
}

/* ══ activity ═════════════════════════════════════════════════════════════ */

export type HostingActivityItem = {
  id: string;
  kind: string;
  label: string;
  detail: string | null;
  status: string;
  at: string;
};

const TASK_LABELS: Record<string, string> = {
  PHP_SWITCH: "PHP version changed",
  WORDPRESS_INSTALL: "WordPress installed",
  APP_INSTALL: "App installed",
  BACKUP: "Backup created",
  RESTORE: "Backup restored",
  SUSPEND: "Account suspended",
  UNSUSPEND: "Account resumed",
  TERMINATE: "Account terminated",
  CREATE_SUBDOMAIN: "Subdomain created",
  DELETE_SUBDOMAIN: "Subdomain removed",
  CREATE_ADDON_DOMAIN: "Domain added",
  DELETE_ADDON_DOMAIN: "Domain removed",
  CREATE_CRON: "Cron job added",
  DELETE_CRON: "Cron job removed",
  INSTALL_DBTOOL: "Database tool installed",
  ENSURE_DBMGR: "Database access prepared",
  APPLY_PLAN_LIMITS: "Plan limits applied",
  RESET_DB_PASSWORD: "Database password reset",
  SET_PRIMARY_DOMAIN: "Primary domain changed",
  CREATE_FTP_USER: "SFTP login created",
  DELETE_FTP_USER: "SFTP login removed",
  RESET_FTP_PASSWORD: "SFTP password reset",
  CAPTURE_SITE_THUMB: "Website preview captured",
};

/**
 * What has actually happened to this hosting plan, newest first.
 *
 * Every row is a real HostingTask — the queue every panel operation already goes
 * through. There is no synthetic "welcome" entry and no entry for anything the
 * platform did not run.
 */
export async function listHostingActivity(accountId: string, limit = 12): Promise<HostingActivityItem[]> {
  const ctx = await ownedAccount(accountId);
  if ("error" in ctx) return [];
  const rows = await db.hostingTask.findMany({
    where: { accountId },
    orderBy: { createdAt: "desc" },
    take: Math.min(50, Math.max(1, limit)),
    select: { id: true, kind: true, status: true, error: true, result: true, createdAt: true, updatedAt: true },
  });
  return rows.map((t) => {
    let detail: string | null = t.error;
    if (!detail && t.result) {
      try {
        const r = JSON.parse(t.result) as { app?: string; note?: string };
        detail = r.note ?? (r.app ? String(r.app) : null);
      } catch { /* a non-JSON result is not a detail */ }
    }
    return {
      id: t.id,
      kind: t.kind,
      label: TASK_LABELS[t.kind] ?? t.kind.toLowerCase().replace(/_/g, " "),
      detail,
      status: t.status,
      at: (t.updatedAt ?? t.createdAt).toISOString(),
    };
  });
}

