/**
 * Website preview capture — a REAL screenshot of a customer's own homepage.
 *
 * The hosting dashboard leads with a picture of the customer's website. There
 * are exactly three things that picture can be, and the panel always knows which:
 *
 *   1. a capture taken here — headless Chromium actually navigates to the site's
 *      public hostname and photographs what answers;
 *   2. an image the customer uploaded themselves;
 *   3. the product's own stock hosting plate, labelled as a placeholder.
 *
 * There is deliberately no fourth option. A stock photograph of *some* website
 * presented as *this* website is the exact shape this tree has already had to
 * delete once (hash-derived star ratings), so a capture that fails stores the
 * failure and the card falls back to the labelled plate.
 *
 * WHAT THIS WILL AND WILL NOT PHOTOGRAPH
 * - Only the hostname of a site on the account being captured, resolved from the
 *   database by the caller — never a URL from a request.
 * - Only over the public internet, from the panel host. It never reaches into a
 *   node, and it is not a way to make the panel fetch an arbitrary address: the
 *   hostname is validated here as well, and a resolved private/loopback address
 *   aborts the capture (SSRF guard — a customer can point their own domain's DNS
 *   at 127.0.0.1 and would otherwise have us photograph our own panel).
 *
 * Playwright is a devDependency used by this tree's own screenshot tooling, and
 * its Chromium is already installed on this box. It is `await import()`ed so a
 * host without it fails this one task with a legible error rather than failing to
 * boot; `next.config.ts` lists it under `serverExternalPackages` so the bundler
 * leaves its browser-path resolution alone.
 */

import { lookup } from "node:dns/promises";
import { isValidHostingDomain } from "./hosting";
import { THUMB_WIDTH, THUMB_HEIGHT, MAX_THUMB_BYTES } from "./hosting-sites";

export type CaptureResult =
  | { ok: true; bytes: Buffer; mime: string; width: number; height: number }
  | { ok: false; error: string };

/** Total wall-clock budget for one capture. A site that cannot paint something
 *  in this long is a site whose picture would be a spinner. */
const NAV_TIMEOUT_MS = 20_000;
const SETTLE_MS = 1_200;

function isPrivateAddress(ip: string): boolean {
  if (ip.includes(":")) {
    const v = ip.toLowerCase();
    // loopback, unspecified, link-local, unique-local
    return v === "::1" || v === "::" || v.startsWith("fe80") || v.startsWith("fc") || v.startsWith("fd");
  }
  const p = ip.split(".").map((n) => parseInt(n, 10));
  if (p.length !== 4 || p.some((n) => !Number.isFinite(n))) return true;
  const [a, b] = p;
  if (a === 10 || a === 127 || a === 0) return true;
  if (a === 172 && b >= 16 && b <= 31) return true;
  if (a === 192 && b === 168) return true;
  if (a === 169 && b === 254) return true;
  if (a === 100 && b >= 64 && b <= 127) return true; // CGNAT
  if (a >= 224) return true; // multicast / reserved
  return false;
}

/**
 * Photograph a hostname's homepage.
 *
 * Returns bytes on success and a customer-readable reason on failure — the
 * reason is stored on the row and shown, because "we tried and the site did not
 * answer" is information the customer wants and "no preview" is not.
 */
export async function captureHomepage(hostname: string): Promise<CaptureResult> {
  const host = String(hostname ?? "").trim().toLowerCase();
  if (!isValidHostingDomain(host)) return { ok: false, error: "That isn’t a hostname we can reach." };

  // Resolve first and refuse anything that points inside the network. A customer
  // controls their own DNS; without this they control what the panel fetches.
  try {
    const addrs = await lookup(host, { all: true });
    if (!addrs.length) return { ok: false, error: "The domain doesn’t resolve yet." };
    if (addrs.some((a) => isPrivateAddress(a.address))) {
      return { ok: false, error: "The domain resolves to a private address, so we can’t photograph it." };
    }
  } catch {
    return { ok: false, error: "The domain doesn’t resolve yet — point its DNS at us and try again." };
  }

  let pw: typeof import("playwright");
  try {
    pw = await import("playwright");
  } catch {
    return { ok: false, error: "The preview service isn’t available on this host." };
  }

  let browser: Awaited<ReturnType<typeof pw.chromium.launch>> | null = null;
  try {
    browser = await pw.chromium.launch({ args: ["--no-sandbox", "--disable-dev-shm-usage"] });
    const ctx = await browser.newContext({
      viewport: { width: THUMB_WIDTH, height: THUMB_HEIGHT },
      deviceScaleFactor: 1,
      ignoreHTTPSErrors: true, // a site mid-issuance still has a self-signed cert
      userAgent:
        "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0 Safari/537.36 NxeonPreview/1.0",
    });
    const page = await ctx.newPage();
    page.setDefaultTimeout(NAV_TIMEOUT_MS);

    // HTTPS first; fall back to HTTP for a site whose certificate has not issued.
    let reached = false;
    let lastErr = "";
    for (const scheme of ["https", "http"]) {
      try {
        const res = await page.goto(`${scheme}://${host}/`, { waitUntil: "domcontentloaded", timeout: NAV_TIMEOUT_MS });
        if (res && res.status() >= 500) { lastErr = `The site answered ${res.status()}.`; continue; }
        reached = true;
        break;
      } catch (e) {
        lastErr = (e as Error)?.message?.split("\n")[0] ?? "Navigation failed.";
      }
    }
    if (!reached) return { ok: false, error: lastErr || "The site didn’t answer." };

    // Give webfonts/hero images a moment — a screenshot taken at DOMContentLoaded
    // is usually an unstyled flash of the page, which looks like a broken site.
    await page.waitForTimeout(SETTLE_MS);
    await page.evaluate(() => window.scrollTo(0, 0)).catch(() => undefined);

    const bytes = await page.screenshot({ type: "jpeg", quality: 76, fullPage: false });
    if (bytes.length > MAX_THUMB_BYTES) {
      return { ok: false, error: "The captured image came back too large to store." };
    }
    return { ok: true, bytes: Buffer.from(bytes), mime: "image/jpeg", width: THUMB_WIDTH, height: THUMB_HEIGHT };
  } catch (e) {
    return { ok: false, error: (e as Error)?.message?.split("\n")[0] ?? "The capture failed." };
  } finally {
    try { await browser?.close(); } catch { /* the process is going away regardless */ }
  }
}

