import { NextRequest, NextResponse } from "next/server";
import { requireUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { validateImageBytes } from "@/lib/chat-attachment";
import { parseSiteKey, MAX_THUMB_BYTES } from "@/lib/hosting-sites";

/**
 * Website preview bytes.
 *
 * GET  — serve one stored preview (a capture or a customer upload). Owner or
 *        admin only: a preview is a photograph of the customer's site as it
 *        stands, which can include a staging page they have not published.
 * POST  — replace one site's preview with an image the customer supplies.
 * The bytes live on HostingSiteThumb in Postgres, the same convention
 * ChatAttachment and SignatureImage use.
 *
 * Upload validation goes through the platform's existing image validator, which
 * authenticates the bytes by SIGNATURE rather than the declared Content-Type and
 * refuses SVG outright. There is no second allow-list here for the two to drift
 * apart on.
 */

/** Owner-or-admin on the account that owns a thumb row. */
async function ownedThumb(id: string) {
  const user = await requireUser();
  const row = await db.hostingSiteThumb.findUnique({
    where: { id },
    select: { id: true, mime: true, data: true, status: true, account: { select: { userId: true } } },
  });
  if (!row) return null;
  if (row.account.userId !== user.id && user.role !== "ADMIN") return null;
  return row;
}

export async function GET(req: NextRequest) {
  const id = req.nextUrl.searchParams.get("id") ?? "";
  if (!id) return new NextResponse("Not found", { status: 404 });
  const row = await ownedThumb(id).catch(() => null);
  if (!row || row.status !== "READY" || !row.data || !row.mime) {
    return new NextResponse("Not found", { status: 404 });
  }
  return new NextResponse(new Uint8Array(row.data), {
    status: 200,
    headers: {
      "Content-Type": row.mime,
      // Private: this is the customer's own site, possibly unpublished. The URL
      // already carries an updatedAt cache-buster, so a long browser cache is
      // safe and a replacement is picked up immediately.
      "Cache-Control": "private, max-age=86400",
      "Content-Disposition": "inline",
    },
  });
}

export async function POST(req: NextRequest) {
  const user = await requireUser().catch(() => null);
  if (!user) return NextResponse.json({ error: "Forbidden" }, { status: 403 });

  const accountId = req.nextUrl.searchParams.get("accountId") ?? "";
  const siteKey = req.nextUrl.searchParams.get("siteKey") ?? "";
  if (!parseSiteKey(siteKey)) return NextResponse.json({ error: "Unknown website." }, { status: 400 });

  const account = await db.hostingAccount.findUnique({
    where: { id: accountId },
    select: { id: true, userId: true, primaryDomain: true },
  });
  if (!account) return NextResponse.json({ error: "Not found" }, { status: 404 });
  if (account.userId !== user.id && user.role !== "ADMIN") {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  }

  // Resolve the site key to the hostname this picture is FOR, so a later rename
  // can be detected and the picture flagged stale rather than shown as current.
  const parsed = parseSiteKey(siteKey)!;
  let hostname = account.primaryDomain;
  if (parsed.kind === "subdomain") {
    const s = await db.hostingSubdomain.findFirst({ where: { id: parsed.id, accountId }, select: { fqdn: true } });
    if (!s) return NextResponse.json({ error: "That website isn’t part of this account." }, { status: 404 });
    hostname = s.fqdn;
  } else if (parsed.kind === "addon") {
    const d = await db.hostingAddonDomain.findFirst({ where: { id: parsed.id, accountId }, select: { domain: true } });
    if (!d) return NextResponse.json({ error: "That website isn’t part of this account." }, { status: 404 });
    hostname = d.domain;
  }

  const form = await req.formData();
  const file = form.get("file");
  if (!(file instanceof File)) return NextResponse.json({ error: "No file" }, { status: 400 });
  if (file.size > MAX_THUMB_BYTES) {
    return NextResponse.json({ error: "Image is larger than 4 MB." }, { status: 413 });
  }

  const check = validateImageBytes(Buffer.from(await file.arrayBuffer()), file.type || null);
  if (!check.ok) return NextResponse.json({ error: check.error }, { status: 400 });

  await db.hostingSiteThumb.upsert({
    where: { accountId_siteKey: { accountId, siteKey } },
    create: {
      accountId, siteKey, hostname, source: "UPLOAD", status: "READY",
      mime: check.mime, sizeBytes: check.bytes.length, data: check.bytes,
      error: null, capturedAt: new Date(),
    },
    update: {
      hostname, source: "UPLOAD", status: "READY",
      mime: check.mime, sizeBytes: check.bytes.length, data: check.bytes,
      error: null, capturedAt: new Date(), width: null, height: null,
    },
  });

  return NextResponse.json({ ok: true });
}

