/* ── extra, folder-scoped SFTP logins ─────────────────────────────────────
   The account's own login is already chrooted to /home/<user> by an sshd include
   the provisioner writes (see applyIsolation step 6). These tasks add the second
   axis: more unix users, each chrooted to ONE directory inside the account, so a
   developer can be given /domains/shop.com and nothing else.

   TWO THINGS MAKE THIS WORK, AND BOTH ARE LOAD-BEARING:

   1. sshd refuses to chroot into any directory writable by a non-root user, and
      it checks EVERY component of the path. The account home is already
      root:root 0711 (hostingFsModes) — the same layout cPanel uses — so the home
      itself is a legal chroot. A per-SITE container (`domains/<d>`,
      `subdomains/<label>`) is created by taskCreateSubdomain/AddonDomain as
      <user>:www-data 2750, which sshd WILL reject, so this task re-owns that
      container to root:<user> 0750 before chrooting into it. The docroot INSIDE
      it keeps its own ownership untouched, which is what PHP writes to — so
      WordPress uploads keep working. Never re-own a docroot; that would break
      the site to add a login.

   2. Confinement is not the same as authorisation. Inside the chroot the login
      is still a POSIX user: it reads and writes by group membership. A writable
      login joins the account's group; a read-only one does not, so the kernel
      refuses its writes. The panel is never the thing enforcing this.

   The sshd write is `sshd -t` validated and discarded on failure, exactly like
   the account's own block — a bad include must never be able to lock a node out. */

/** The chroot target, validated again here. The payload only ever carries a row
 *  id; the path is re-read from the row and re-checked against the allow-list,
 *  so a shell never sees a string that did not pass twice. */
function ftpChrootAbs(accountUser: string, chrootPath: string): string {
  const home = accountPaths(accountUser).home;
  return chrootPath ? `${home}/${chrootPath}` : home;
}

async function taskCreateFtpUser(conn: Client, a: { id: string; username: string }, payload: string | null): Promise<void> {
  const id = String(JSON.parse(payload || "{}").ftpUserId ?? "");
  const row = await db.hostingFtpUser.findFirst({ where: { id, accountId: a.id } });
  if (!row) throw new Error("ftp login row missing");
  if (!isValidUnixUsername(a.username) || !isValidUnixUsername(row.username)) throw new Error("invalid username");
  if (!isValidFtpChroot(row.chrootPath)) throw new Error("invalid scope");
  const pw = row.passwordEnc ? decryptSecret(row.passwordEnc) : null;
  if (!pw || !/^[A-Za-z0-9]{8,64}$/.test(pw)) throw new Error("no usable password on record");

  const home = accountPaths(a.username).home;
  const chroot = ftpChrootAbs(a.username, row.chrootPath);

  // The container must exist and must be root-owned for sshd to accept it. The
  // account home already is; a per-site container is re-owned here. `-m 0750`
  // with group = the account keeps the customer's own login able to traverse it.
  if (row.chrootPath) {
    await run(conn, "prepare scope dir", `test -d ${chroot} && chown root:${a.username} ${chroot} && chmod 0750 ${chroot}`);
  }

  // No shell, no home of its own (it lands in the chroot), member of the
  // account's group ONLY when it is allowed to write.
  await run(
    conn,
    "create ftp user",
    `id -u ${row.username} >/dev/null 2>&1 || useradd -M -d / -s /usr/sbin/nologin ${row.username}`,
  );
  await run(
    conn,
    "scope ftp user",
    row.readOnly
      ? `gpasswd -d ${row.username} ${a.username} >/dev/null 2>&1; true`
      : `usermod -a -G ${a.username} ${row.username}`,
  );
  await run(conn, "set ftp password", `echo '${row.username}:${pw}' | chpasswd`);

  const sshdFile = `/etc/ssh/sshd_config.d/nxeon-ftp-${row.username}.conf`;
  const block = [
    `Match User ${row.username}`,
    `    ChrootDirectory ${chroot}`,
    `    ForceCommand internal-sftp`,
    `    AllowTcpForwarding no`,
    `    X11Forwarding no`,
    `    PermitTTY no`,
  ].join("\n");
  const out = await run(
    conn,
    "ftp chroot (guarded)",
    `mkdir -p /etc/ssh/sshd_config.d && cat > ${sshdFile}.new <<'SSHD'\n${block}\nSSHD\n` +
      `cp -f ${sshdFile}.new ${sshdFile} && if sshd -t 2>/dev/null; then systemctl reload ssh 2>/dev/null || systemctl reload sshd; ` +
      `else rm -f ${sshdFile}; echo 'SSHD_REJECTED'; fi; rm -f ${sshdFile}.new`,
  );
  if (String(out ?? "").includes("SSHD_REJECTED")) {
    // The box is untouched. Remove the half-made user and report the truth —
    // never leave a row saying ACTIVE for a login sshd refused to accept.
    await run(conn, "rollback ftp user", `userdel ${row.username} >/dev/null 2>&1; true`);
    throw new Error("the node's SSH service rejected the folder restriction, so the login was not created");
  }
  await db.hostingFtpUser.update({ where: { id: row.id }, data: { status: "ACTIVE", error: null } });
  void home;
}

async function taskDeleteFtpUser(conn: Client, a: { id: string; username: string }, payload: string | null): Promise<void> {
  const id = String(JSON.parse(payload || "{}").ftpUserId ?? "");
  const row = await db.hostingFtpUser.findFirst({ where: { id, accountId: a.id } });
  if (!row) return; // already gone — deleting twice is not an error
  if (!isValidUnixUsername(row.username)) throw new Error("invalid username");
  const sshdFile = `/etc/ssh/sshd_config.d/nxeon-ftp-${row.username}.conf`;
  await run(
    conn,
    "remove ftp chroot",
    `rm -f ${sshdFile}; if sshd -t 2>/dev/null; then systemctl reload ssh 2>/dev/null || systemctl reload sshd; fi; true`,
  );
  await run(conn, "remove ftp user", `userdel ${row.username} >/dev/null 2>&1; true`);
  await db.hostingFtpUser.delete({ where: { id: row.id } }).catch(() => undefined);
}

async function taskResetFtpPassword(conn: Client, a: { id: string; username: string }, payload: string | null): Promise<void> {
  const id = String(JSON.parse(payload || "{}").ftpUserId ?? "");
  const row = await db.hostingFtpUser.findFirst({ where: { id, accountId: a.id } });
  if (!row) throw new Error("ftp login row missing");
  if (!isValidUnixUsername(row.username)) throw new Error("invalid username");
  const pw = row.passwordEnc ? decryptSecret(row.passwordEnc) : null;
  if (!pw || !/^[A-Za-z0-9]{8,64}$/.test(pw)) throw new Error("no usable password on record");
  await run(conn, "reset ftp password", `echo '${row.username}:${pw}' | chpasswd`);
}

/**
 * Photograph one of the account's websites.
 *
 * The ONLY hosting task that never touches the node: the capture runs from the
 * panel host over the public internet against the site's own hostname, exactly
 * as a visitor would reach it (lib/hosting-thumb.ts). Handled before the SSH
 * connect in processHostingTask for that reason.
 */
async function taskCaptureSiteThumb(a: { id: string }, payload: string | null): Promise<string | null> {
  const p = (() => { try { return JSON.parse(payload || "{}"); } catch { return {}; } })() as { siteKey?: string; hostname?: string };
  const siteKey = String(p.siteKey ?? "");
  const hostname = String(p.hostname ?? "");
  if (!siteKey || !hostname) throw new Error("nothing to capture");

  const { captureHomepage } = await import("../lib/hosting-thumb");
  const shot = await captureHomepage(hostname);

  if (!shot.ok) {
    await db.hostingSiteThumb.updateMany({
      where: { accountId: a.id, siteKey },
      data: { status: "FAILED", error: shot.error.slice(0, 200), data: null, sizeBytes: 0 },
    });
    // The TASK succeeded — we asked, and got an answer. The answer is stored on
    // the row, where the card reads it. Failing the task too would put the same
    // message in two places and light up the activity feed red for a site that
    // simply is not published yet.
    return JSON.stringify({ note: `Preview not captured: ${shot.error}` });
  }

  await db.hostingSiteThumb.updateMany({
    where: { accountId: a.id, siteKey },
    data: {
      status: "READY", error: null, mime: shot.mime, data: shot.bytes,
      sizeBytes: shot.bytes.length, width: shot.width, height: shot.height,
      capturedAt: new Date(), hostname,
    },
  });
  return JSON.stringify({ note: `Captured ${hostname}` });
}

