import type { HostingAccountView, HostingWebsiteView } from "@/lib/actions-hosting";
import type { SiteThumbView, HostingActivityItem, StorageBreakdown } from "@/lib/actions-hosting-sites";

/**
 * Everything the hosting panel's shell renders, resolved ONCE on the server.
 *
 * The old panel re-fetched the same counts from four client components on four
 * different cadences, which is why its Overview could show "2 sites" beside a
 * list of three. One shape, fetched once, threaded down.
 *
 * Every optional/nullable field here means "we could not measure this", never
 * "zero" — see `bandwidth` and `mailboxes` in particular, which are ALLOWANCES
 * with no usage figure behind them because the platform does not meter either
 * one for shared hosting yet.
 */

export type HostingMetric = {
  key: string;
  label: string;
  icon: string;
  ink: string;
  tone: string;
  /** Measured usage. Null = not metered/not measured; the tile shows the
   *  allowance and the reason rather than a bar starting at zero. */
  used: number | null;
  /** The plan's ceiling. Null = unlimited on this plan. */
  limit: number | null;
  /** Renders `used`/`limit` — GB, counts, whatever the dimension is. */
  format: (n: number) => string;
  /** Shown in place of a bar when `used` is null. */
  unmeasured?: string;
};

export type HostingSiteCard = HostingWebsiteView & {
  thumb: SiteThumbView | null;
};

export type HostingPanelData = {
  account: HostingAccountView;
  /** Primary site first, then subdomains, then addon domains. */
  sites: HostingSiteCard[];
  /** SFTP host for the account's own login — the node's FQDN or public IP. */
  sftpHost: string | null;
  /** Whether a credential exists at all yet. The password itself is only ever
   *  fetched on demand, through the ownership-checked reveal action. */
  hasSftpPassword: boolean;
  /** Real mailbox count for the primary domain's subscription; null when the
   *  customer has not set up their included email yet (so there is nothing to
   *  count, as opposed to a count of zero). */
  mailboxesUsed: number | null;
  emailReady: boolean;
  /** Plan allowance. -1 = unlimited. */
  mailboxesIncluded: number;
  /** Plan allowance in TB. There is NO usage figure — nginx traffic is not
   *  attributed per account yet. */
  bandwidthTB: number;
  databasesUsed: number;
  backupCount: number;
  lastBackupAt: string | null;
  lastBackupBytes: number | null;
  storage: StorageBreakdown | null;
  activity: HostingActivityItem[];
  /** Per-cycle renewal charge in cents, and its unit label ("/ month"). */
  renewalCents: number;
  renewalTerm: string;
  /** Purchased extra storage, GB — the only add-on a hosting plan can carry. */
  extraDiskGB: number;
  /** Whether a bigger plan exists to move up to. */
  canUpgrade: boolean;
};

"use client";

import { useRef, useState, useTransition } from "react";
import { Icon } from "@/components/nx/Icon";
import { captureSiteThumb, clearSiteThumb, type SiteThumbView } from "@/lib/actions-hosting-sites";

/**
 * The picture of a customer's website.
 *
 * THE ONE RULE THIS COMPONENT EXISTS TO ENFORCE: the card always says which of
 * three things it is showing, and it never shows a fourth.
 *
 *   1. CAPTURE — a real screenshot of the live hostname, taken by the worker
 *      with headless Chromium (lib/hosting-thumb.ts). Badged "Live capture".
 *   2. UPLOAD  — an image the customer supplied. Badged "Your image".
 *   3. neither — the product's own hosting artwork, badged "Placeholder", with
 *      the reason no capture exists ("not captured yet" / the actual failure).
 *
 * A stock photograph of some other website passed off as this one is precisely
 * the shape this tree deleted once already. If a capture failed because the
 * domain does not resolve, the card says that — which is information the
 * customer needs and a prettier picture is not.
 *
 * `nx-dark-island`: the frame draws a photograph or the dark product plate under
 * its own overlays in BOTH themes. Without the island, light mode flips the
 * caption tokens to dark ink over a dark image. Same mechanism WhatsNewView's
 * GameCoverTile caption uses.
 */

const PLACEHOLDER = "/nx/preview/hosting.webp";

type Size = "hero" | "card" | "tile";

const FRAME: Record<Size, string> = {
  hero: "aspect-[16/10] rounded-[16px]",
  card: "aspect-[16/10] rounded-[12px]",
  tile: "aspect-[16/10] rounded-[10px]",
};

function badgeFor(thumb: SiteThumbView | null): { label: string; ink: string; icon: string } {
  if (!thumb || thumb.status !== "READY") return { label: "Placeholder", ink: "text-slate-300", icon: "cloud" };
  if (thumb.source === "UPLOAD") return { label: "Your image", ink: "text-violet-200", icon: "upload" };
  return { label: "Live capture", ink: "text-emerald-200", icon: "eye" };
}

export function SitePreview({
  accountId,
  siteKey,
  hostname,
  thumb,
  size = "card",
  canCapture,
  onChanged,
  /** Hide the capture/upload controls — used where the frame is decorative. */
  readOnly,
}: {
  accountId: string;
  siteKey: string;
  hostname: string;
  thumb: SiteThumbView | null;
  size?: Size;
  /** False while the site isn't serving yet: a capture would photograph an error
   *  page, so the control says why instead of producing one. */
  canCapture: boolean;
  onChanged?: () => void;
  readOnly?: boolean;
}) {
  const [busy, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);
  const fileRef = useRef<HTMLInputElement | null>(null);

  const ready = thumb?.status === "READY" && thumb.url;
  const pending = thumb?.status === "PENDING";
  const badge = badgeFor(thumb ?? null);

  function capture() {
    setError(null);
    start(async () => {
      const r = await captureSiteThumb(accountId, siteKey);
      if (r.error) setError(r.error);
      else onChanged?.();
    });
  }

  function clear() {
    setError(null);
    start(async () => {
      const r = await clearSiteThumb(accountId, siteKey);
      if (r.error) setError(r.error);
      else onChanged?.();
    });
  }

  async function upload(file: File) {
    setError(null);
    setUploading(true);
    try {
      const fd = new FormData();
      fd.set("file", file);
      const res = await fetch(
        `/api/hosting/thumb?accountId=${encodeURIComponent(accountId)}&siteKey=${encodeURIComponent(siteKey)}`,
        { method: "POST", body: fd },
      );
      if (!res.ok) {
        const j = (await res.json().catch(() => ({}))) as { error?: string };
        setError(j.error ?? "That image couldn’t be saved.");
        return;
      }
      onChanged?.();
    } catch {
      setError("The upload didn’t reach us.");
    } finally {
      setUploading(false);
    }
  }

  return (
    <div className="flex min-w-0 flex-col gap-2">
      <div className={`nx-dark-island relative overflow-hidden border border-rim-hi bg-[#04101f] ${FRAME[size]}`}>
        {/* eslint-disable-next-line @next/next/no-img-element -- a stored capture
            and a local plate, both outside the image optimizer */}
        <img
          src={ready ? thumb!.url! : PLACEHOLDER}
          alt={ready ? `Screenshot of ${thumb!.hostname}` : ""}
          className={
            "h-full w-full object-cover object-top transition-transform duration-500 " +
            (ready ? "" : "opacity-[0.55] object-center")
          }
        />

        {/* A floor so the caption strip always has something to sit on, whatever
            the picture's own bottom edge happens to be. */}
        <span
          aria-hidden
          className="pointer-events-none absolute inset-x-0 bottom-0 h-2/5"
          style={{ background: "linear-gradient(180deg, transparent, rgba(3,10,24,.92))" }}
        />

        {/* Which of the three sources this is. Always present. */}
        <span className="absolute left-2 top-2 inline-flex items-center gap-1.5 rounded-full border border-white/15 bg-black/55 px-2 py-0.5 text-[10px] font-bold backdrop-blur-sm">
          <Icon name={badge.icon} size={10} tone="inherit" className={badge.ink} />
          <span className={badge.ink}>{badge.label}</span>
        </span>

        {pending && (
          <span className="absolute right-2 top-2 inline-flex items-center gap-1.5 rounded-full border border-sky-400/40 bg-black/55 px-2 py-0.5 text-[10px] font-bold text-sky-200 backdrop-blur-sm">
            <Icon name="refresh2" size={10} tone="inherit" className="nx-spin" />
            Capturing
          </span>
        )}

        {thumb?.stale && ready && (
          <span className="absolute right-2 top-2 rounded-full border border-amber-400/40 bg-black/55 px-2 py-0.5 text-[10px] font-bold text-amber-200 backdrop-blur-sm">
            Taken of {thumb.hostname}
          </span>
        )}

        <div className="absolute inset-x-0 bottom-0 flex items-end justify-between gap-2 px-2.5 pb-2">
          <span className="min-w-0 truncate text-[11.5px] font-bold text-white drop-shadow">{hostname}</span>
          {!readOnly && (
            <span className="flex flex-none items-center gap-1">
              <button
                type="button"
                disabled={busy || uploading || !canCapture || pending}
                title={
                  canCapture
                    ? "Take a fresh screenshot of this site"
                    : "We can photograph this site once it’s answering on its domain"
                }
                onClick={capture}
                className="grid h-[26px] w-[26px] place-items-center rounded-[8px] border border-white/20 bg-black/50 text-white backdrop-blur-sm transition hover:border-[#8b5cff]/60 disabled:opacity-35"
              >
                <Icon name={pending ? "refresh2" : "eye"} size={12} tone="inherit" className={pending ? "nx-spin" : ""} />
              </button>
              <button
                type="button"
                disabled={busy || uploading}
                title="Upload your own image instead"
                onClick={() => fileRef.current?.click()}
                className="grid h-[26px] w-[26px] place-items-center rounded-[8px] border border-white/20 bg-black/50 text-white backdrop-blur-sm transition hover:border-[#8b5cff]/60 disabled:opacity-35"
              >
                <Icon name={uploading ? "refresh2" : "upload"} size={12} tone="inherit" className={uploading ? "nx-spin" : ""} />
              </button>
              {thumb && (
                <button
                  type="button"
                  disabled={busy || uploading}
                  title="Remove this picture and fall back to the placeholder"
                  onClick={clear}
                  className="grid h-[26px] w-[26px] place-items-center rounded-[8px] border border-white/20 bg-black/50 text-white backdrop-blur-sm transition hover:border-rose-400/60 disabled:opacity-35"
                >
                  <Icon name="trash" size={12} tone="inherit" />
                </button>
              )}
            </span>
          )}
        </div>
      </div>

      <input
        ref={fileRef}
        type="file"
        accept="image/png,image/jpeg,image/gif,image/webp"
        className="hidden"
        onChange={(e) => {
          const f = e.target.files?.[0];
          e.currentTarget.value = "";
          if (f) void upload(f);
        }}
      />

      {/* Why there is no real picture, when there is no real picture. */}
      {!readOnly && (
        <p className="text-[10.5px] leading-relaxed text-tx-faint">
          {error ? (
            <span className="text-rose-300">{error}</span>
          ) : thumb?.status === "FAILED" ? (
            <span className="text-amber-300">Preview not captured — {thumb.error}</span>
          ) : pending ? (
            "Taking a screenshot of your homepage…"
          ) : ready ? (
            thumb!.source === "UPLOAD"
              ? "Your own image. Re-capture any time to use a live screenshot instead."
              : `Captured ${thumb!.capturedAt ? new Date(thumb!.capturedAt).toLocaleString() : ""}.`
          ) : canCapture ? (
            "No screenshot yet — capture one, or upload your own image."
          ) : (
            "We’ll photograph your homepage once the site is answering on its domain."
          )}
        </p>
      )}
    </div>
  );
}

"use client";

import { Icon } from "@/components/nx/Icon";
import { StatusPill, CopyChip, type Tone } from "@/components/customer/vpspanel/v2/kit";
import { SitePreview } from "./SitePreview";
import type { HostingPanelData } from "./types";

/**
 * The hosting plan's identity band.
 *
 * Reads left to right as "this is your website / this is the plan it sits on /
 * here is what the plan has left". The picture leads because a hosting customer
 * identifies their account by what it *looks* like, not by a hostname — which is
 * why the old page, which opened with a bare `<h1>domain</h1>` and two grey
 * pills, felt like a settings screen for a domain rather than a dashboard for a
 * website.
 *
 * THE PLAN / WEBSITE DISTINCTION IS THE WHOLE LAYOUT. Everything in this band is
 * about the PLAN — its tier, its term, its ceilings. Individual websites live in
 * their own tab with their own cards. The old panel mixed the two (the account's
 * PHP version and its primary domain's SSL state sat in the same list as the
 * plan's database quota), which is why nobody could tell what a limit applied to.
 *
 * Nothing here is computed from anything but a database column. The two figures
 * that have no usage measurement behind them — bandwidth and mailbox count
 * before email is set up — say "included" and give the reason, rather than
 * drawing a bar from an invented zero.
 */

const STATUS: Record<string, { tone: Tone; label: string; live: boolean }> = {
  ACTIVE: { tone: "ok", label: "Online", live: true },
  PENDING: { tone: "busy", label: "Setting up", live: true },
  PROVISIONING: { tone: "busy", label: "Setting up", live: true },
  SUSPENDED: { tone: "warn", label: "Suspended", live: false },
  FAILED: { tone: "bad", label: "Setup failed", live: false },
  DELETING: { tone: "idle", label: "Cancelling", live: true },
};

function fmtGB(mb: number): string {
  const gb = mb / 1024;
  if (gb >= 1024) return `${(gb / 1024).toFixed(gb % 1024 === 0 ? 0 : 1)} TB`;
  return `${gb.toFixed(gb < 10 && gb % 1 !== 0 ? 1 : 0)} GB`;
}

/**
 * One plan ceiling and what is against it.
 *
 * `used === null` is the "not measured" case and is drawn differently on
 * purpose: the allowance alone, greyed, with the reason underneath. It must
 * never render as `0 / 10`, which reads as a measurement of nothing used.
 */
function UsageChip({
  icon, ink, bar, label, used, limit, format, unmeasured,
}: {
  icon: string;
  ink: string;
  bar: string;
  label: string;
  used: number | null;
  limit: number | null;
  format?: (n: number) => string;
  unmeasured?: string;
}) {
  const f = format ?? ((n: number) => String(n));
  const unlimited = limit === null;
  const known = used !== null && !unlimited;
  const pct = known && limit ? Math.min(100, Math.max(0, (used! / limit) * 100)) : 0;
  const tight = pct >= 90;

  return (
    <div className="flex min-w-[104px] flex-1 flex-col gap-1.5" title={used === null ? unmeasured : undefined}>
      <span className="flex items-center gap-1.5">
        <Icon name={icon} size={12} tone="inherit" className={`flex-none ${ink}`} />
        <span className="text-[9.5px] font-bold uppercase tracking-[0.12em] text-tx-faint">{label}</span>
      </span>
      <span className={"num text-[15px] font-extrabold leading-none " + (known ? "text-tx" : "text-tx-dim")}>
        {unlimited ? (
          "Unlimited"
        ) : known ? (
          <>
            {f(used!)}
            <span className="text-tx-faint"> / {f(limit!)}</span>
          </>
        ) : (
          <>
            {f(limit ?? 0)}
            <span className="ml-1 text-[10px] font-bold uppercase tracking-wide text-tx-faint">incl.</span>
          </>
        )}
      </span>
      {known ? (
        <span className="h-[4px] w-full overflow-hidden rounded-full bg-white/12">
          <span
            className="block h-full rounded-full transition-[width] duration-700 ease-out"
            style={{ width: `${Math.max(2, pct)}%`, background: tight ? "linear-gradient(90deg,#fb923c,#f43f5e)" : bar }}
          />
        </span>
      ) : (
        <span className="h-[4px] w-full rounded-full bg-white/[0.07]" />
      )}
    </div>
  );
}

export function HostingHero({
  data,
  onUpgrade,
  onRefresh,
}: {
  data: HostingPanelData;
  onUpgrade: () => void;
  onRefresh: () => void;
}) {
  const a = data.account;
  const st = STATUS[a.status] ?? STATUS.PENDING;
  const primary = data.sites.find((s) => s.kind === "primary") ?? null;

  // The primary domain is always one live website; the plan's `maxSites` budget
  // is the ADDITIONAL sites on top of it, which is the convention the rest of the
  // product already uses. Total websites is therefore 1 + maxSites.
  const sitesUsed = data.sites.length;
  const sitesLimit = a.maxSites + 1;

  const diskTotalMB = a.diskQuotaMB;
  const url = `${a.sslActive ? "https" : "http"}://${a.primaryDomain}`;

  return (
    <header
      className="card card-glass relative overflow-hidden p-0"
      style={{ "--tone": "#3fbcd8" } as React.CSSProperties}
    >
      <span
        aria-hidden
        className="pointer-events-none absolute inset-0 z-0 opacity-[0.55]"
        style={{
          background:
            "radial-gradient(ellipse 60% 120% at 8% 0%, rgba(63,188,216,.16), transparent 70%)," +
            "radial-gradient(ellipse 50% 120% at 92% 10%, rgba(123,63,239,.14), transparent 70%)",
        }}
      />

      <div className="relative z-[1] flex flex-col gap-4 p-4 lg:flex-row lg:items-stretch lg:gap-5 lg:p-5">
        {/* ── the website itself ───────────────────────────────────────── */}
        <div className="w-full flex-none lg:w-[300px] xl:w-[340px]">
          {primary ? (
            <SitePreview
              accountId={a.id}
              siteKey={primary.key}
              hostname={primary.hostname}
              thumb={primary.thumb}
              size="hero"
              canCapture={a.status === "ACTIVE" && (a.serveHttpOk === true || a.serveHttpsOk === true)}
              onChanged={onRefresh}
            />
          ) : (
            <div className="nx-dark-island aspect-[16/10] overflow-hidden rounded-[16px] border border-rim-hi bg-[#04101f]">
              {/* eslint-disable-next-line @next/next/no-img-element -- local plate */}
              <img src="/nx/preview/hosting.webp" alt="" className="h-full w-full object-cover opacity-[0.55]" />
            </div>
          )}
        </div>

        {/* ── plan identity + ceilings ─────────────────────────────────── */}
        <div className="flex min-w-0 flex-1 flex-col">
          <div className="flex flex-wrap items-start justify-between gap-3">
            <div className="min-w-0">
              <div className="flex flex-wrap items-center gap-2.5">
                <h1 className="truncate text-[24px] font-extrabold leading-[1.05] tracking-[-0.03em] text-tx sm:text-[28px]">
                  {a.primaryDomain}
                </h1>
                <StatusPill tone={st.tone} label={st.label} live={st.live} />
                {a.sslActive && (
                  <span className="inline-flex items-center gap-1.5 rounded-full border border-emerald-400/40 bg-emerald-500/12 px-2.5 py-1 text-[11.5px] font-bold text-emerald-300">
                    <Icon name="lock" size={11} tone="inherit" /> HTTPS
                  </span>
                )}
              </div>

              {/* The plan, spelled out: tier name, its slug tag, the term it was
                  sold on, and the runtime the sites actually execute under. */}
              <div className="mt-2.5 flex flex-wrap items-center gap-x-2 gap-y-2">
                <span className="inline-flex items-center gap-2 rounded-[9px] border border-[#8b5cff]/40 bg-[linear-gradient(120deg,rgba(80,40,190,.3),rgba(30,44,130,.22))] px-2.5 py-1">
                  <Icon name="cloud" size={13} tone="inherit" className="text-[#b79bff]" />
                  <span className="text-[12.5px] font-extrabold text-tx">{a.planName}</span>
                  {a.planSlug && (
                    <span className="mono rounded-[5px] border border-rim-hi bg-well px-1.5 py-px text-[9.5px] font-bold uppercase tracking-wide text-tx-dim">
                      {a.planSlug}
                    </span>
                  )}
                </span>
                <span className="inline-flex items-center gap-1.5 rounded-[9px] border border-rim-hi bg-well px-2.5 py-1 text-[11.5px] font-semibold text-tx-body">
                  <Icon name="cube" size={12} tone="inherit" className="text-[#7fb0ff]" />
                  PHP <span className="mono">{a.phpVersion}</span>
                </span>
                <span className="inline-flex items-center gap-1.5 rounded-[9px] border border-rim-hi bg-well px-2.5 py-1 text-[11.5px] font-semibold text-tx-body">
                  <Icon name="card" size={12} tone="inherit" className="text-emerald-300" />
                  <span className="num">${(data.renewalCents / 100).toFixed(2)}</span>
                  <span className="text-tx-faint">{data.renewalTerm}</span>
                </span>
                {a.isFreeSubdomain && (
                  <span className="rounded-[9px] border border-rim-hi bg-well px-2.5 py-1 text-[11.5px] font-semibold text-tx-dim">
                    Free Nxeon subdomain
                  </span>
                )}
              </div>
            </div>

            {/* ── actions ──────────────────────────────────────────────── */}
            <div className="flex flex-none flex-wrap items-center gap-2">
              <a
                href={url}
                target="_blank"
                rel="noreferrer"
                className="inline-flex items-center gap-1.5 rounded-[10px] border border-rim-hi bg-[color-mix(in_srgb,var(--fg)_5%,transparent)] px-3 py-2 text-[12.5px] font-semibold text-tx-body transition hover:border-[#8b5cff]/50 hover:text-tx"
              >
                <Icon name="external" size={13} tone="inherit" /> Visit site
              </a>
              <button
                type="button"
                onClick={onUpgrade}
                className="nx-cta inline-flex items-center gap-1.5 px-3.5 py-2 text-[12.5px]"
              >
                <Icon name="bolt" size={13} tone="inherit" />
                {data.canUpgrade ? "Upgrade plan" : "Manage plan"}
              </button>
            </div>
          </div>

          {/* ── the ceilings ─────────────────────────────────────────────
              One row, five dimensions, each showing usage AGAINST the plan.
              This is the answer to "what am I actually paying for", and it is
              the thing a shared-hosting customer checks most often. */}
          <div className="mt-4 flex flex-wrap items-start gap-x-5 gap-y-4 border-t border-rim-soft pt-4">
            <UsageChip
              icon="globe3" ink="text-violet-300" bar="linear-gradient(90deg,#a78bfa,#e879f9)"
              label="Websites" used={sitesUsed} limit={sitesLimit}
            />
            <UsageChip
              icon="database" ink="text-cyan-300" bar="linear-gradient(90deg,#22d3ee,#67e8f9)"
              label="Storage" used={a.diskUsedMB} limit={diskTotalMB} format={fmtGB}
              unmeasured="Measured once the account is live on a node"
            />
            <UsageChip
              icon="transfer" ink="text-pink-300" bar="linear-gradient(90deg,#f472b6,#fb7185)"
              label="Bandwidth" used={null} limit={data.bandwidthTB * 1024 * 1024} format={fmtGB}
              unmeasured="Traffic isn’t metered per account on shared hosting — the allowance is shown"
            />
            <UsageChip
              icon="envelope" ink="text-amber-300" bar="linear-gradient(90deg,#f59e0b,#fbbf24)"
              label="Email" used={data.mailboxesUsed} limit={data.mailboxesIncluded < 0 ? null : data.mailboxesIncluded}
              unmeasured="Set up your included email to start using these"
            />
            <UsageChip
              icon="dbstack" ink="text-emerald-300" bar="linear-gradient(90deg,#34d399,#6ee7b7)"
              label="Databases" used={data.databasesUsed} limit={a.maxDatabases}
            />
          </div>

          {/* Where the files live — one line, because it is the single thing a
              customer needs from the account itself rather than from a site. */}
          {data.sftpHost && a.status === "ACTIVE" && (
            <div className="mt-3 flex flex-wrap items-center gap-2">
              <CopyChip label="SFTP host" value={data.sftpHost} />
              <CopyChip label="Username" value={a.username} />
            </div>
          )}
        </div>
      </div>
    </header>
  );
}

export function HostingStateBanner({ data }: { data: HostingPanelData }) {
  const a = data.account;
  if (a.status === "SUSPENDED") {
    return (
      <div className="card card-glass flex flex-wrap items-center gap-3 border-orange-500/40 bg-orange-950/30 px-4 py-3 text-[13px] text-orange-200">
        <Icon name="warntriangle" size={16} tone="inherit" />
        <span className="min-w-0 flex-1">
          <span className="font-bold">This hosting plan is suspended.</span> Its websites are offline until it is
          reinstated.
        </span>
        <a href="/dashboard/support" className="font-semibold underline underline-offset-2">Open a ticket</a>
      </div>
    );
  }
  if (a.status === "FAILED") {
    return (
      <div className="card card-glass flex items-center gap-3 border-red-500/40 bg-red-950/30 px-4 py-3 text-[13px] text-red-200">
        <Icon name="warntriangle" size={16} tone="inherit" />
        <span>
          <span className="font-bold">Setup failed.</span> {a.error || "Our team has been notified."}
        </span>
      </div>
    );
  }
  if (a.status === "PENDING" || a.status === "PROVISIONING") {
    return (
      <div className="card card-glass flex items-center gap-3 border-sky-500/35 bg-sky-950/25 px-4 py-3 text-[13px] text-sky-200">
        <Icon name="refresh2" size={15} tone="inherit" className="nx-spin" />
        Your hosting is being set up — usually under a minute. This page refreshes itself.
      </div>
    );
  }
  if (a.status === "DELETING") {
    return (
      <div className="card card-glass flex items-center gap-3 border-rose-500/35 bg-rose-950/25 px-4 py-3 text-[13px] text-rose-200">
        <Icon name="refresh2" size={15} tone="inherit" className="nx-spin" />
        This hosting plan is being cancelled and removed.
      </div>
    );
  }
  return null;
}

"use client";

import { useCallback, useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { Icon } from "@/components/nx/Icon";
import { HostingHero, HostingStateBanner } from "./HostingHero";
import { HostingOverviewPanel } from "./HostingOverviewPanel";
import { HostingWebsitesPanel } from "./HostingWebsitesPanel";
import { HostingFilesPanel } from "./HostingFilesPanel";
import { HostingDatabasesPanel } from "./HostingDatabasesPanel";
import { HostingBackupsPanel } from "./HostingBackupsPanel";
import { HostingActivityPanel } from "./HostingActivityPanel";
import { HostingSettingsShell } from "./HostingSettingsShell";
import { HostingEmailPanel } from "./HostingEmailPanel";
import { HostingAppsPanel } from "./HostingAppsPanel";
import { HostingCronPanel } from "./HostingCronPanel";
import type { HostingPanelData } from "./types";

/**
 * The shared-hosting panel's shell.
 *
 * WHAT THIS REPLACED, and why the shape changed rather than the colours:
 *
 * The old panel's Overview rendered — unconditionally, all at once, for an
 * account that had finished provisioning hours ago — an SFTP credential strip,
 * an "App credentials / WordPress admin login" card, a "Your account is ready —
 * here's how to go live" checklist whose first step was an *Install WordPress*
 * button, and a task feed whose top row read "WordPress installed — log in at
 * …". Four surfaces, two of them contradicting each other, and the one the
 * customer wanted (their site) was not among them. That is fixed structurally:
 *
 *   • Setup guidance is STATE-DRIVEN. The "get your site online" card only
 *     exists while something is genuinely outstanding, and each step disappears
 *     as its real signal flips (see SetupCard in HostingOverviewPanel).
 *   • App credentials appear ONCE, on the website that app was installed on.
 *   • The task feed became Activity — its own tab, chronological, with no
 *     credential in it.
 *   • Credentials live in Settings → Access, which is the place a customer
 *     looks for them, and is where the new folder-scoped SFTP logins are too.
 *
 * TABS. The ten the brief asked for. They are ordered by how a website is
 * actually worked on — what it is, then its files, data, mail, apps and
 * schedules — with the two retrospective tabs and then Settings at the end.
 * That is a deliberate reordering of the brief's enumeration: putting Settings
 * in the middle of the rail (between Activity and Email) would break the "daily
 * work first, configuration last" arrangement every other panel in this product
 * already uses. Domains is gone as a top-level tab — a domain is a property of a
 * website, and it now lives inside that website's own view.
 */

type TabKey =
  | "overview" | "websites" | "files" | "databases" | "email"
  | "apps" | "cron" | "backups" | "activity" | "settings";

const TABS: { key: TabKey; label: string; icon: string }[] = [
  { key: "overview",  label: "Overview",  icon: "donut" },
  { key: "websites",  label: "Websites",  icon: "globe3" },
  { key: "files",     label: "Files",     icon: "folder" },
  { key: "databases", label: "Databases", icon: "dbstack" },
  { key: "email",     label: "Email",     icon: "envelope" },
  { key: "apps",      label: "Apps",      icon: "cube" },
  { key: "cron",      label: "Cron",      icon: "clock" },
  { key: "backups",   label: "Backups",   icon: "archive" },
  { key: "activity",  label: "Activity",  icon: "activity" },
  { key: "settings",  label: "Settings",  icon: "gear" },
];

/** Retired keys that bookmarks, worker notifications and the old panel's own
 *  links still use. `domains` folded into Websites; `subdomains` with it. */
const ALIASES: Record<string, TabKey> = {
  domains: "websites",
  subdomains: "websites",
  addon: "websites",
  sites: "websites",
  db: "databases",
  access: "settings",
  sftp: "settings",
  ftp: "settings",
  upgrade: "settings",
  plan: "settings",
  php: "settings",
  storage: "settings",
  tasks: "activity",
};

function resolveTab(raw: string | undefined): TabKey {
  const k = (raw ?? "").toLowerCase().trim();
  if (TABS.some((t) => t.key === k)) return k as TabKey;
  return ALIASES[k] ?? "overview";
}

export function HostingPanelShell({
  data: initial,
  initialTab,
  initialSite,
  initialPath,
  initialSection,
}: {
  data: HostingPanelData;
  initialTab?: string;
  initialSite?: string;
  initialPath?: string;
  initialSection?: string;
}) {
  const router = useRouter();
  const [data, setData] = useState(initial);
  const [tab, setTab] = useState<TabKey>(() => resolveTab(initialTab));
  const [site, setSite] = useState<string | null>(initialSite ?? null);
  const [section, setSection] = useState<string | undefined>(initialSection);

  // The server re-renders this page on every revalidatePath; keep the client copy
  // in step so an action taken in one tab is visible in another without a reload.
  useEffect(() => { setData(initial); }, [initial]);

  useEffect(() => {
    const onPop = () => {
      const q = new URLSearchParams(window.location.search);
      setTab(resolveTab(q.get("tab") ?? undefined));
      setSite(q.get("site"));
    };
    window.addEventListener("popstate", onPop);
    return () => window.removeEventListener("popstate", onPop);
  }, []);

  const go = useCallback((t: TabKey, opts: { site?: string | null; section?: string } = {}) => {
    setTab(t);
    if (opts.site !== undefined) setSite(opts.site);
    if (opts.section !== undefined) setSection(opts.section);
    const url = new URL(window.location.href);
    url.searchParams.set("tab", t);
    if (opts.site) url.searchParams.set("site", opts.site);
    else if (opts.site === null) url.searchParams.delete("site");
    window.history.pushState(null, "", url);
    window.scrollTo({ top: 0, behavior: "smooth" });
  }, []);

  /** Pull fresh server data after any action that changed something. */
  const refresh = useCallback(() => { router.refresh(); }, [router]);

  const active = data.account.status === "ACTIVE";

  return (
    <div className="mx-auto flex w-full max-w-[1480px] flex-col gap-4">
      <HostingStateBanner data={data} />

      <div className="sticky top-0 z-20 -mx-1 flex flex-col gap-2 bg-[color-mix(in_srgb,var(--color-bg)_82%,transparent)] px-1 pb-2 pt-1 backdrop-blur-xl">
        <HostingHero
          data={data}
          onUpgrade={() => go("settings", { section: "plan" })}
          onRefresh={refresh}
        />

        <nav className="flex gap-1 overflow-x-auto rounded-[14px] border border-rim-hi bg-surface p-1.5">
          {TABS.map((t) => {
            const on = tab === t.key;
            return (
              <button
                key={t.key}
                type="button"
                onClick={() => go(t.key, { site: null })}
                aria-current={on ? "page" : undefined}
                className={
                  "inline-flex flex-none items-center gap-2 whitespace-nowrap rounded-[10px] px-3.5 py-2 text-[13px] font-semibold transition " +
                  (on
                    ? "bg-[linear-gradient(120deg,rgba(80,40,190,.55),rgba(30,44,130,.42))] text-[#fff] shadow-[inset_0_0_0_1px_rgba(139,92,255,.5)]"
                    : "text-tx-dim hover:bg-[color-mix(in_srgb,var(--fg)_5%,transparent)] hover:text-tx")
                }
              >
                <Icon name={t.icon} size={14} tone="inherit" className={on ? "text-[#fff]" : "text-tx-dim"} />
                {t.label}
              </button>
            );
          })}
        </nav>
      </div>

      <div className="min-w-0">
        {tab === "overview" && (
          <HostingOverviewPanel
            data={data}
            onOpenSite={(key) => go("websites", { site: key })}
            onGo={(t, s) => go(t as TabKey, { section: s })}
            onRefresh={refresh}
          />
        )}

        {tab === "websites" && (
          <HostingWebsitesPanel
            data={data}
            selected={site}
            onSelect={(key) => go("websites", { site: key })}
            onRefresh={refresh}
          />
        )}

        {tab === "files" && (
          active
            ? <HostingFilesPanel data={data} initialPath={initialPath} />
            : <NotReady what="The file manager" />
        )}

        {tab === "databases" && (
          active
            ? <HostingDatabasesPanel data={data} onRefresh={refresh} />
            : <NotReady what="Databases" />
        )}

        {tab === "email" && <HostingEmailPanel data={data} />}

        {tab === "apps" && (
          active ? <HostingAppsPanel data={data} onRefresh={refresh} /> : <NotReady what="One-click apps" />
        )}

        {tab === "cron" && (
          active ? <HostingCronPanel data={data} /> : <NotReady what="Scheduled tasks" />
        )}

        {tab === "backups" && (
          active ? <HostingBackupsPanel data={data} onRefresh={refresh} /> : <NotReady what="Backups" />
        )}

        {tab === "activity" && <HostingActivityPanel data={data} onRefresh={refresh} />}

        {tab === "settings" && (
          <HostingSettingsShell data={data} initial={section} onRefresh={refresh} />
        )}
      </div>
    </div>
  );
}

/** One wording for every tab that needs a live account, so a customer mid-setup
 *  gets the same answer everywhere instead of four different empty states. */
function NotReady({ what }: { what: string }) {
  return (
    <div className="card card-glass flex flex-col items-center px-6 py-14 text-center">
      <span className="grid h-[44px] w-[44px] place-items-center rounded-[13px] border border-rim-hi bg-well">
        <Icon name="refresh2" size={19} className="nx-spin" />
      </span>
      <p className="mt-3.5 text-[14.5px] font-extrabold text-tx">{what} isn’t ready yet</p>
      <p className="mx-auto mt-1.5 max-w-[46ch] text-[12.5px] leading-relaxed text-tx-dim">
        Your hosting is still being set up. This section opens the moment the account goes live — the page refreshes
        itself, so there’s nothing to do but wait.
      </p>
    </div>
  );
}

