"use client";

import type { HostingAppMenuItem } from "@/lib/hosting-app-menu";

/**
 * The brand mark of an application installed on a website.
 *
 * The paths come from `simple-icons`, resolved server-side in
 * lib/hosting-app-menu.ts — the same source the deploy wizard's app picker uses,
 * so an app can never be drawn here with a mark the installer does not offer.
 *
 * An app the catalogue has no mark for gets an initial tile rather than a
 * generic "app" glyph, because a generic glyph on six different apps tells the
 * customer nothing. An app the platform does not recognise at all gets the same
 * tile — it is still a real installed app, we just have no artwork for it.
 */

/** The installed-app LABEL a site carries ("WordPress") → its catalogue entry. */
export function findApp(menu: HostingAppMenuItem[], label: string | null): HostingAppMenuItem | null {
  if (!label) return null;
  const l = label.trim().toLowerCase();
  return menu.find((m) => m.name.toLowerCase() === l || m.slug === l) ?? null;
}

export function AppMark({
  label,
  app,
  size = 18,
}: {
  label: string;
  app: HostingAppMenuItem | null;
  size?: number;
}) {
  const box = { width: size, height: size, minWidth: size };
  if (app?.logoPath) {
    return (
      <span
        title={label}
        className="grid flex-none place-items-center rounded-[6px] border border-white/12 bg-white/90 p-[3px]"
        style={box}
      >
        <svg viewBox="0 0 24 24" className="h-full w-full" fill={app.logoHex ? `#${app.logoHex}` : "#0b1220"} aria-hidden>
          <path d={app.logoPath} />
        </svg>
      </span>
    );
  }
  return (
    <span
      title={label}
      className="grid flex-none place-items-center rounded-[6px] border border-rim-hi bg-well text-[9px] font-extrabold text-tx-dim"
      style={box}
    >
      {label.charAt(0).toUpperCase()}
    </span>
  );
}

"use client";

import { Icon } from "@/components/nx/Icon";
import { StatusPill, type Tone } from "@/components/customer/vpspanel/v2/kit";
import { SitePreview } from "./SitePreview";
import { AppMark, findApp } from "./AppMark";
import type { HostingAppMenuItem } from "@/lib/hosting-app-menu";
import type { HostingSiteCard } from "./types";

/**
 * One website on the plan, as a card.
 *
 * Every card carries the four things that identify a website to its owner: what
 * it looks like, what it is called, whether it is up, and what is running on it.
 * The old panel's website list carried none of the first and buried the last in
 * a line of grey text reading `App: None`.
 *
 * "No app installed" is a real state and is drawn as one — an outlined slot that
 * invites an install — rather than as an absence.
 */

const SITE_STATUS: Record<string, { tone: Tone; label: string; live: boolean }> = {
  ACTIVE: { tone: "ok", label: "Live", live: true },
  PENDING: { tone: "busy", label: "Setting up", live: true },
  PROVISIONING: { tone: "busy", label: "Setting up", live: true },
  DELETING: { tone: "idle", label: "Removing", live: true },
  FAILED: { tone: "bad", label: "Failed", live: false },
  SUSPENDED: { tone: "warn", label: "Suspended", live: false },
};

const KIND_LABEL: Record<HostingSiteCard["kind"], string> = {
  primary: "Main website",
  subdomain: "Subdomain",
  addon: "Addon domain",
};

export function WebsiteCard({
  accountId,
  site,
  appMenu,
  accountActive,
  onOpen,
  onRefresh,
}: {
  accountId: string;
  site: HostingSiteCard;
  appMenu: HostingAppMenuItem[];
  accountActive: boolean;
  onOpen: () => void;
  onRefresh: () => void;
}) {
  const st = SITE_STATUS[site.status] ?? SITE_STATUS.PENDING;
  const app = findApp(appMenu, site.installedApp);
  const serving = site.status === "ACTIVE";

  return (
    <div className="card card-glass card-i flex min-w-0 flex-col gap-3 p-3" style={{ "--tone": "#4f7cff" } as React.CSSProperties}>
      <SitePreview
        accountId={accountId}
        siteKey={site.key}
        hostname={site.hostname}
        thumb={site.thumb}
        size="card"
        canCapture={accountActive && serving}
        onChanged={onRefresh}
        readOnly
      />

      <div className="flex min-w-0 flex-col gap-2">
        <div className="flex min-w-0 items-start justify-between gap-2">
          <div className="min-w-0">
            <a
              href={`${site.sslActive ? "https" : "http"}://${site.hostname}`}
              target="_blank"
              rel="noreferrer"
              onClick={(e) => e.stopPropagation()}
              className="block truncate text-[13.5px] font-extrabold text-tx hover:text-brand-300"
              title={site.hostname}
            >
              {site.hostname}
            </a>
            <span className="mt-0.5 flex flex-wrap items-center gap-1.5 text-[10px] font-bold uppercase tracking-[0.1em] text-tx-faint">
              {KIND_LABEL[site.kind]}
              {site.isFreeSubdomain && <span className="text-[#b79bff]">· free</span>}
            </span>
          </div>
          <StatusPill tone={st.tone} label={st.label} live={st.live} />
        </div>

        <div className="flex flex-wrap items-center gap-2">
          {/* HTTPS is per-website: a plan can have one site on a trusted cert and
              another still issuing, and the card says which this one is. */}
          <span
            className={
              "inline-flex items-center gap-1 rounded-[6px] border px-1.5 py-0.5 text-[10px] font-bold " +
              (site.sslActive
                ? "border-emerald-400/40 bg-emerald-500/12 text-emerald-300"
                : "border-amber-400/40 bg-amber-500/12 text-amber-300")
            }
          >
            <Icon name={site.sslActive ? "lock" : "unlock"} size={9} tone="inherit" />
            {site.sslActive ? "HTTPS" : "HTTP"}
          </span>

          {/* What is running on it. */}
          {site.installedApp ? (
            <span className="inline-flex items-center gap-1.5 rounded-[6px] border border-rim-hi bg-well px-1.5 py-0.5">
              <AppMark label={site.installedApp} app={app} size={14} />
              <span className="text-[10.5px] font-bold text-tx-body">{site.installedApp}</span>
            </span>
          ) : (
            <span className="inline-flex items-center gap-1.5 rounded-[6px] border border-dashed border-rim-hi px-1.5 py-0.5 text-[10.5px] font-semibold text-tx-faint">
              <Icon name="plussq" size={11} tone="inherit" /> No app installed
            </span>
          )}
        </div>

        <button
          type="button"
          onClick={onOpen}
          className="mt-0.5 inline-flex items-center justify-center gap-1.5 rounded-[10px] border border-rim-hi bg-[color-mix(in_srgb,var(--fg)_4%,transparent)] px-3 py-1.5 text-[12px] font-bold text-tx-body transition hover:border-[#8b5cff]/50 hover:text-tx"
        >
          View more <Icon name="external" size={11} tone="inherit" />
        </button>
      </div>
    </div>
  );
}

