"use client";

import { useEffect, useState, useTransition } from "react";
import { Icon } from "@/components/nx/Icon";
import { Panel, CopyChip } from "@/components/customer/vpspanel/v2/kit";
import { recheckHostingHealth } from "@/lib/actions-hosting";
import type { HostingPanelData } from "./types";

/**
 * "Is my website actually reachable, and is it secure?"
 *
 * THE TWO SHAPES. A connected, verified domain does NOT want to look at a setup
 * wizard forever, and a domain that has never resolved does not want a green
 * tick. So this card has two states and switches between them on a real signal:
 *
 *   • VERIFIED — collapses to one line: the certificate is trusted, here is when
 *     we last checked. The progression is gone, because it is finished.
 *   • NOT YET  — the three-step progression, with the DNS record to create
 *     spelled out, and a button to re-check right now.
 *
 * Every step is driven by a MEASUREMENT the worker recorded from the node
 * (`serveHttpOk` / `serveHttpsOk` / `sslActive`, written by hostingHealthSweep),
 * never by elapsed time. It therefore cannot say "live" while HTTPS refuses —
 * which is the failure this whole mechanism exists to prevent.
 *
 * A free Nxeon subdomain has no DNS step to do: wildcard DNS already points at
 * us, so step one is complete on arrival and the copy says so rather than asking
 * the customer to configure something that is configured.
 */

type Phase = "verified" | "issuing" | "waiting" | "unchecked";

function phaseOf(a: HostingPanelData["account"]): Phase {
  if (a.sslActive && a.serveHttpsOk !== false) return "verified";
  if (a.serveHttpOk === true || a.serveHttpsOk === true) return "issuing";
  if (a.healthCheckedAt != null || a.serveHttpOk != null) return "waiting";
  return "unchecked";
}

export function HttpsCard({ data, onRefresh }: { data: HostingPanelData; onRefresh: () => void }) {
  const a = data.account;
  const phase = phaseOf(a);
  const [busy, start] = useTransition();
  const [note, setNote] = useState<string | null>(null);

  // While a certificate is still coming, poll — the sweep runs on its own and a
  // customer should not have to reload to watch it land.
  useEffect(() => {
    if (phase === "verified" || a.status !== "ACTIVE") return;
    const t = setInterval(onRefresh, 20_000);
    return () => clearInterval(t);
  }, [phase, a.status, onRefresh]);

  function recheck() {
    setNote(null);
    start(async () => {
      const r = await recheckHostingHealth(a.id);
      if (r.error) setNote(r.error);
      else {
        setNote("Checking now — this takes a few seconds.");
        setTimeout(onRefresh, 6000);
      }
    });
  }

  /* ── the finished state ───────────────────────────────────────────────── */
  if (phase === "verified") {
    return (
      <Panel title="HTTPS" accent="#34d399" icon="shieldcheck" ink="text-emerald-300">
        <div className="flex items-start gap-3">
          <span className="grid h-[38px] w-[38px] flex-none place-items-center rounded-[11px] border border-emerald-400/35 bg-emerald-950/40">
            <Icon name="lock" size={17} tone="inherit" className="text-emerald-300" />
          </span>
          <div className="min-w-0 flex-1">
            <p className="text-[13.5px] font-extrabold text-tx">Verified and secure</p>
            <p className="mt-0.5 text-[11.5px] leading-relaxed text-tx-dim">
              <span className="mono text-tx-body">{a.primaryDomain}</span> is serving over HTTPS with a trusted
              certificate. It renews itself — there is nothing to do.
            </p>
            <div className="mt-2 flex flex-wrap items-center gap-x-3 gap-y-1 text-[11px] text-tx-faint">
              {a.healthCheckedAt && <span>Last checked {new Date(a.healthCheckedAt).toLocaleString()}</span>}
              <button
                type="button"
                onClick={recheck}
                disabled={busy}
                className="font-semibold text-brand-300 hover:text-tx disabled:opacity-50"
              >
                {busy ? "Checking…" : "Check again"}
              </button>
            </div>
            {note && <p className="mt-1 text-[11px] text-tx-dim">{note}</p>}
          </div>
        </div>
      </Panel>
    );
  }

  /* ── the setup progression ────────────────────────────────────────────── */
  const free = a.isFreeSubdomain;
  const steps = [
    {
      label: "DNS ready",
      done: free || phase === "issuing" || phase === "waiting" ? free || phase === "issuing" : false,
      busy: !free && phase === "waiting",
      hint: free ? "Handled for you" : phase === "issuing" ? "Pointing at us" : "Waiting for your A record",
    },
    {
      label: "SSL issuing",
      done: false,
      busy: phase === "issuing",
      hint: phase === "issuing" ? "Requesting a certificate" : "Starts once DNS resolves",
    },
    {
      label: "HTTPS verified",
      done: false,
      busy: false,
      hint: "Automatic — usually a minute after DNS",
    },
  ];

  return (
    <Panel
      title="Getting your site secure"
      accent="#f59e0b"
      icon="shieldcheck"
      ink="text-amber-300"
      action={
        a.status === "ACTIVE" ? (
          <button
            type="button"
            onClick={recheck}
            disabled={busy}
            className="inline-flex items-center gap-1.5 rounded-[9px] border border-rim-hi bg-[color-mix(in_srgb,var(--fg)_5%,transparent)] px-2.5 py-1 text-[11.5px] font-bold text-tx-body transition hover:border-[#8b5cff]/55 hover:text-tx disabled:opacity-50"
          >
            <Icon name="refresh2" size={11} tone="inherit" className={busy ? "nx-spin" : ""} />
            {busy ? "Checking" : free ? "Refresh" : "Go live"}
          </button>
        ) : undefined
      }
    >
      <ol className="flex flex-col gap-0">
        {steps.map((s, i) => {
          const state = s.done ? "done" : s.busy ? "busy" : "todo";
          return (
            <li key={s.label} className="flex gap-3">
              <span className="flex flex-none flex-col items-center">
                <span
                  className={
                    "grid h-[22px] w-[22px] place-items-center rounded-full border text-[10px] font-extrabold " +
                    (state === "done"
                      ? "border-emerald-400/45 bg-emerald-500/15 text-emerald-300"
                      : state === "busy"
                        ? "border-sky-400/45 bg-sky-500/15 text-sky-300"
                        : "border-rim-hi bg-well text-tx-faint")
                  }
                >
                  {state === "done" ? (
                    <Icon name="checkcircle" size={11} tone="inherit" />
                  ) : state === "busy" ? (
                    <Icon name="refresh2" size={10} tone="inherit" className="nx-spin" />
                  ) : (
                    i + 1
                  )}
                </span>
                {i < steps.length - 1 && (
                  <span className={"my-0.5 w-px flex-1 " + (steps[i + 1].done ? "bg-emerald-400/40" : "bg-rim-hi")} />
                )}
              </span>
              <span className="flex min-w-0 flex-1 flex-col pb-3">
                <span className={"text-[12.5px] font-bold " + (state === "todo" ? "text-tx-dim" : "text-tx")}>
                  {s.label}
                </span>
                <span className="text-[11px] text-tx-faint">{s.hint}</span>
              </span>
            </li>
          );
        })}
      </ol>

      {!free && (
        <div className="mt-1 rounded-[11px] border border-rim-soft bg-well p-3">
          <p className="text-[11px] font-bold uppercase tracking-[0.1em] text-tx-faint">Point your domain here</p>
          <p className="mt-1.5 text-[11.5px] leading-relaxed text-tx-dim">
            At your registrar, create an <span className="mono text-tx-body">A</span> record for{" "}
            <span className="mono text-tx-body">{a.primaryDomain}</span>:
          </p>
          <div className="mt-2 flex flex-wrap gap-2">
            <CopyChip label="A record" value={a.pointToA} />
            {a.pointToCname && <CopyChip label="or CNAME" value={a.pointToCname} />}
          </div>
        </div>
      )}

      <p className="mt-2.5 text-[11px] leading-relaxed text-tx-faint">
        {a.healthNote ? (
          <>
            <span className="font-semibold text-tx-dim">{a.healthNote}</span>
            {a.healthCheckedAt && <> · checked {new Date(a.healthCheckedAt).toLocaleTimeString()}</>}
          </>
        ) : (
          "We haven’t been able to check this domain yet."
        )}
      </p>
      {note && <p className="mt-1 text-[11px] text-tx-dim">{note}</p>}
    </Panel>
  );
}

"use client";

import { Icon } from "@/components/nx/Icon";
import { Panel, Empty } from "@/components/customer/vpspanel/v2/kit";
import type { HostingPanelData } from "./types";

/**
 * The small cards down the Overview rail: storage, subscription, activity.
 *
 * All three exist because the old Overview answered none of their questions.
 * The storage card in particular replaces a single bar labelled "Storage" that
 * could tell a customer they were at 94% and nothing at all about what to
 * delete.
 */

function fmtMB(mb: number): string {
  if (mb >= 1024 * 1024) return `${(mb / 1024 / 1024).toFixed(1)} TB`;
  if (mb >= 1024) return `${(mb / 1024).toFixed(mb < 10240 ? 1 : 0)} GB`;
  return `${Math.round(mb)} MB`;
}

function fmtBytesShort(b: number): string {
  if (b >= 1024 ** 3) return `${(b / 1024 ** 3).toFixed(1)} GB`;
  if (b >= 1024 ** 2) return `${(b / 1024 ** 2).toFixed(0)} MB`;
  return `${(b / 1024).toFixed(0)} KB`;
}

/* A fixed ramp so the same directory keeps the same colour between readings. */
const RAMP = ["#7b3fef", "#4f7cff", "#3fbcd8", "#34d399", "#f59e0b", "#f472b6", "#94a3b8"];

/**
 * WHERE the storage went.
 *
 * The parts come from `usageBreakdown`, one `du -sm` per directory written by
 * the SAME sweep pass that writes the total — so the segments and the bar can
 * never be read from two different moments. With no reading at all, the card
 * says why rather than drawing an empty chart, which would read as "nothing
 * stored" instead of "not measured".
 */
export function StorageCard({ data, onManage }: { data: HostingPanelData; onManage: () => void }) {
  const s = data.storage;
  const quotaMB = s?.quotaMB ?? data.account.diskQuotaMB;
  const usedMB = s?.usedMB ?? null;
  const pct = usedMB !== null && quotaMB > 0 ? Math.min(100, (usedMB / quotaMB) * 100) : null;
  const parts = s?.parts ?? [];
  const accounted = parts.reduce((n, p) => n + p.mb, 0);
  // Anything measured on the account but not inside a directory we named.
  const other = usedMB !== null && accounted > 0 ? Math.max(0, usedMB - accounted) : 0;

  return (
    <Panel
      title="Storage"
      accent="#22d3ee"
      icon="database"
      ink="text-cyan-300"
      action={
        <button
          type="button"
          onClick={onManage}
          className="inline-flex items-center gap-1.5 rounded-[9px] border border-rim-hi bg-[color-mix(in_srgb,var(--fg)_5%,transparent)] px-2.5 py-1 text-[11.5px] font-bold text-tx-body transition hover:border-[#8b5cff]/55 hover:text-tx"
        >
          Add storage <Icon name="plus" size={11} tone="inherit" />
        </button>
      }
    >
      <div className="flex items-baseline justify-between gap-2">
        <span className="num text-[19px] font-extrabold leading-none text-tx">
          {usedMB !== null ? fmtMB(usedMB) : "—"}
          <span className="text-[13px] font-bold text-tx-faint"> / {fmtMB(quotaMB)}</span>
        </span>
        {pct !== null && (
          <span className={"num text-[12px] font-bold " + (pct >= 90 ? "text-rose-300" : pct >= 75 ? "text-amber-300" : "text-tx-dim")}>
            {pct.toFixed(0)}%
          </span>
        )}
      </div>

      {/* The stacked bar IS the breakdown — one bar, segmented, rather than a
          bar plus a separate pie saying the same thing twice. */}
      <div className="mt-2.5 flex h-[10px] w-full overflow-hidden rounded-full bg-white/10">
        {parts.length > 0 && quotaMB > 0 ? (
          <>
            {parts.map((p, i) => (
              <span
                key={p.path}
                title={`${p.label} — ${fmtMB(p.mb)}`}
                style={{ width: `${(p.mb / quotaMB) * 100}%`, background: RAMP[i % RAMP.length] }}
                className="block h-full first:rounded-l-full"
              />
            ))}
            {other > 0 && (
              <span
                title={`Other files — ${fmtMB(other)}`}
                style={{ width: `${(other / quotaMB) * 100}%`, background: RAMP[RAMP.length - 1] }}
                className="block h-full"
              />
            )}
          </>
        ) : pct !== null ? (
          <span
            className="block h-full rounded-full"
            style={{ width: `${Math.max(2, pct)}%`, background: "linear-gradient(90deg,#22d3ee,#67e8f9)" }}
          />
        ) : null}
      </div>

      {parts.length > 0 ? (
        <ul className="mt-3 flex flex-col gap-1.5">
          {parts.slice(0, 5).map((p, i) => (
            <li key={p.path} className="flex items-center gap-2">
              <span className="h-2 w-2 flex-none rounded-full" style={{ background: RAMP[i % RAMP.length] }} />
              <span className="min-w-0 flex-1 truncate text-[11.5px] font-semibold text-tx-body" title={p.path}>
                {p.label}
              </span>
              <span className="num flex-none text-[11.5px] text-tx-dim">{fmtMB(p.mb)}</span>
            </li>
          ))}
          {other > 0 && (
            <li className="flex items-center gap-2">
              <span className="h-2 w-2 flex-none rounded-full" style={{ background: RAMP[RAMP.length - 1] }} />
              <span className="min-w-0 flex-1 truncate text-[11.5px] font-semibold text-tx-body">Other files</span>
              <span className="num flex-none text-[11.5px] text-tx-dim">{fmtMB(other)}</span>
            </li>
          )}
        </ul>
      ) : (
        <p className="mt-3 text-[11.5px] leading-relaxed text-tx-faint">
          {s?.note ?? "No per-folder reading yet."}
        </p>
      )}

      <dl className="mt-3 flex flex-wrap gap-x-5 gap-y-1.5 border-t border-rim-soft pt-2.5 text-[11px]">
        <div className="flex items-baseline gap-1.5">
          <dt className="text-tx-faint">Files &amp; folders</dt>
          <dd className="num font-bold text-tx-body">{s?.inodes != null ? s.inodes.toLocaleString() : "—"}</dd>
        </div>
        <div className="flex items-baseline gap-1.5">
          <dt className="text-tx-faint">Backups on the node</dt>
          <dd className="num font-bold text-tx-body">
            {s ? `${s.backupCount}${s.backupBytes ? ` · ${fmtBytesShort(s.backupBytes)}` : ""}` : "—"}
          </dd>
        </div>
      </dl>
      <p className="mt-1.5 text-[10.5px] leading-relaxed text-tx-faint">
        Backups are stored outside your account’s quota, so they don’t use the space above.
      </p>
    </Panel>
  );
}

/**
 * What is being paid, when, and what is attached to it.
 *
 * Kept to one screen-third on purpose: the brief asked for compact, and a
 * subscription card that lists every line item is a billing page, not a summary.
 * The renewal figure is `termPriceCents` over the term this account was SOLD on
 * — the same formula the renewal sweep bills — not `plan.priceCents`.
 */
export function SubscriptionCard({ data, onManage, onUpgrade }: {
  data: HostingPanelData;
  onManage: () => void;
  onUpgrade: () => void;
}) {
  const a = data.account;
  const renewsOn = a.expiresAt ? new Date(a.expiresAt) : null;
  const daysLeft = renewsOn ? Math.ceil((renewsOn.getTime() - Date.now()) / 86_400_000) : null;

  return (
    <Panel title="Subscription" accent="#34d399" icon="card" ink="text-emerald-300">
      <div className="flex items-center gap-3">
        <span className="grid h-[38px] w-[38px] flex-none place-items-center overflow-hidden rounded-[11px] border border-rim-hi bg-well">
          {/* eslint-disable-next-line @next/next/no-img-element -- local product mark */}
          <img src="/nx/svc/hosting.webp" alt="" className="h-full w-full object-cover" />
        </span>
        <span className="flex min-w-0 flex-col leading-tight">
          <span className="truncate text-[13.5px] font-extrabold text-tx">{a.planName}</span>
          <span className="num text-[12px] text-tx-dim">
            ${(data.renewalCents / 100).toFixed(2)} {data.renewalTerm}
          </span>
        </span>
      </div>

      {/* Add-ons. Extra storage is the only one a hosting plan can carry today —
          and when there is none, the card says so rather than hiding the row,
          because "no add-ons" is the answer to the question being asked. */}
      <div className="mt-3 border-t border-rim-soft pt-2.5">
        <p className="text-[10px] font-bold uppercase tracking-[0.12em] text-tx-faint">Add-ons</p>
        {data.extraDiskGB > 0 ? (
          <div className="mt-1.5 flex items-center gap-2">
            <Icon name="database" size={13} tone="inherit" className="flex-none text-cyan-300" />
            <span className="min-w-0 flex-1 truncate text-[12px] font-semibold text-tx-body">
              +{data.extraDiskGB} GB extra storage
            </span>
            <span className="flex-none text-[10.5px] text-tx-faint">billed each renewal</span>
          </div>
        ) : (
          <p className="mt-1 text-[11.5px] text-tx-faint">None on this plan.</p>
        )}
      </div>

      <dl className="mt-3 flex flex-col gap-1.5 border-t border-rim-soft pt-2.5">
        <div className="flex items-baseline justify-between gap-3">
          <dt className="text-[11.5px] text-tx-dim">Next renewal</dt>
          <dd className="num text-[12px] font-bold text-tx">
            {renewsOn ? renewsOn.toLocaleDateString(undefined, { day: "numeric", month: "short", year: "numeric" }) : "—"}
            {daysLeft !== null && daysLeft >= 0 && <span className="ml-1.5 font-normal text-tx-faint">({daysLeft}d)</span>}
          </dd>
        </div>
        <div className="flex items-center justify-between gap-3">
          <dt className="text-[11.5px] text-tx-dim">Auto-renew</dt>
          <dd>
            {/* Hosting renewals are swept automatically from the wallet — there is
                no per-account opt-out column, so this states the mechanism rather
                than drawing a toggle that would control nothing. */}
            <span className="inline-flex items-center gap-1.5 rounded-full border border-emerald-400/40 bg-emerald-500/12 px-2 py-0.5 text-[10.5px] font-bold text-emerald-300">
              <span className="h-1.5 w-1.5 rounded-full bg-emerald-400" /> On · from wallet
            </span>
          </dd>
        </div>
      </dl>

      <div className="mt-3 flex gap-2">
        <button type="button" onClick={onUpgrade} className="nx-cta flex flex-1 justify-center py-1.5 text-[12px]">
          <Icon name="bolt" size={12} tone="inherit" /> Upgrade plan
        </button>
        <button
          type="button"
          onClick={onManage}
          className="flex-none rounded-[10px] border border-rim-hi bg-[color-mix(in_srgb,var(--fg)_5%,transparent)] px-3 py-1.5 text-[12px] font-semibold text-tx-body transition hover:border-[#8b5cff]/50 hover:text-tx"
        >
          Manage
        </button>
      </div>
    </Panel>
  );
}

const ACTIVITY_INK: Record<string, { icon: string; ink: string }> = {
  DONE: { icon: "checkcircle", ink: "text-emerald-300" },
  RUNNING: { icon: "refresh2", ink: "text-sky-300" },
  PENDING: { icon: "clock", ink: "text-amber-300" },
  FAILED: { icon: "warncircle", ink: "text-rose-300" },
};

function ago(iso: string): string {
  const s = Math.max(0, (Date.now() - new Date(iso).getTime()) / 1000);
  if (s < 60) return "just now";
  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
  if (s < 86_400) return `${Math.floor(s / 3600)}h ago`;
  return `${Math.floor(s / 86_400)}d ago`;
}

/** Everything the platform has run for this plan. Real HostingTask rows only —
 *  no synthetic "account created" entry, and no credential in the feed. */
export function ActivityCard({ data, onViewAll, compact = true }: {
  data: HostingPanelData;
  onViewAll?: () => void;
  compact?: boolean;
}) {
  const items = compact ? data.activity.slice(0, 5) : data.activity;
  return (
    <Panel
      title="Recent activity"
      accent="#a78bfa"
      icon="activity"
      ink="text-violet-300"
      action={
        onViewAll ? (
          <button type="button" onClick={onViewAll} className="text-[11.5px] font-semibold text-brand-300 hover:text-tx">
            View all →
          </button>
        ) : undefined
      }
    >
      {items.length === 0 ? (
        <p className="text-[12px] text-tx-faint">Nothing has run on this plan yet.</p>
      ) : (
        <ul className="flex flex-col gap-2">
          {items.map((e) => {
            const k = ACTIVITY_INK[e.status] ?? ACTIVITY_INK.PENDING;
            return (
              <li key={e.id} className="flex items-start gap-2.5">
                <Icon
                  name={k.icon}
                  size={13}
                  tone="inherit"
                  className={`mt-0.5 flex-none ${k.ink} ${e.status === "RUNNING" ? "nx-spin" : ""}`}
                />
                <span className="flex min-w-0 flex-1 flex-col leading-tight">
                  <span className="truncate text-[12px] font-semibold text-tx-body">{e.label}</span>
                  {e.detail && <span className="truncate text-[10.5px] text-tx-faint" title={e.detail}>{e.detail}</span>}
                </span>
                <span className="flex-none text-[10.5px] text-tx-faint">{ago(e.at)}</span>
              </li>
            );
          })}
        </ul>
      )}
    </Panel>
  );
}

