"use client";

import { useState, useTransition } from "react";
import { Icon } from "@/components/nx/Icon";
import { Panel } from "@/components/customer/vpspanel/v2/kit";
import { installWordPress, createHostingBackup } from "@/lib/actions-hosting";
import { WebsiteCard, AddWebsiteCard } from "./WebsiteCard";
import { HttpsCard } from "./HttpsCard";
import { StorageCard, SubscriptionCard, ActivityCard } from "./OverviewCards";
import type { HostingPanelData } from "./types";

/**
 * Overview — the whole plan on one screen, with nothing said twice.
 *
 * The old Overview is worth describing, because this layout is a direct answer
 * to it. It rendered, at the same time, for a healthy account: a two-column
 * "Overview / Point your domain" pair, four quota tiles, an SFTP credential
 * strip, an App-credentials card, a "Your account is ready — here's how to go
 * live" checklist with an *Install WordPress* button as step one, and a task
 * feed whose first line said "WordPress installed". The customer's actual
 * websites appeared nowhere.
 *
 * So: websites first and largest. Then the three questions a shared-hosting
 * customer asks between visits — is it secure, how full is it, what am I paying
 * — and then what the platform has been doing. Credentials moved to Settings →
 * Access. The setup checklist survives only as a card that can genuinely finish,
 * because every one of its steps is a measured fact that stops being true.
 */

/* ── setup ────────────────────────────────────────────────────────────────
   ONLY measured, genuinely-outstanding things. Each row disappears the moment
   its signal flips, and the card disappears when the last one does — which is
   what the old GettingStarted panel never did. HTTPS is deliberately NOT here:
   it has its own card, and saying it twice is how the old page got confusing. */

type SetupStep = {
  key: string;
  label: string;
  body: string;
  icon: string;
  cta: string;
  run: () => Promise<{ error?: string } | void>;
};

function SetupCard({ data, onGo, onRefresh }: {
  data: HostingPanelData;
  onGo: (tab: string) => void;
  onRefresh: () => void;
}) {
  const [busy, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const a = data.account;

  const anyApp = data.sites.some((s) => s.installedApp);
  const steps: SetupStep[] = [];

  if (!anyApp) {
    steps.push({
      key: "app",
      label: "Put something on your site",
      // Carefully worded: we know what we INSTALLED, not what is on the disk. A
      // customer who uploaded their own files by SFTP has a finished website and
      // must not be told it is empty.
      body: "We haven’t installed an app on this plan. Install WordPress in one click — or ignore this if you’ve uploaded your own files.",
      icon: "cube",
      cta: "Install WordPress",
      run: () => installWordPress(a.id),
    });
  }
  if (!data.emailReady && data.mailboxesIncluded !== 0) {
    steps.push({
      key: "email",
      label: "Claim your included email",
      body:
        data.mailboxesIncluded < 0
          ? "Your plan includes unlimited mailboxes on your domain. They’re not switched on yet."
          : `Your plan includes ${data.mailboxesIncluded} mailbox${data.mailboxesIncluded === 1 ? "" : "es"} on your domain. They’re not switched on yet.`,
      icon: "envelope",
      cta: "Set up email",
      run: async () => { onGo("email"); },
    });
  }
  if (data.backupCount === 0) {
    steps.push({
      key: "backup",
      label: "Take your first backup",
      body: "Nothing has been backed up yet. Run one now — it takes a moment, and it’s what you’ll want before your first big change.",
      icon: "archive",
      cta: "Back up now",
      run: () => createHostingBackup(a.id),
    });
  }

  if (!steps.length || a.status !== "ACTIVE") return null;

  return (
    <Panel title="Finish setting up" accent="#8b5cff" icon="sparkles" ink="text-violet-300" fill={false}>
      <div className="grid gap-2.5 md:grid-cols-3">
        {steps.map((s) => (
          <div key={s.key} className="flex min-w-0 flex-col gap-2 rounded-[12px] border border-rim-soft bg-well p-3">
            <span className="flex items-center gap-2">
              <Icon name={s.icon} size={14} tone="inherit" className="flex-none text-[#b79bff]" />
              <span className="text-[12.5px] font-extrabold text-tx">{s.label}</span>
            </span>
            <p className="flex-1 text-[11.5px] leading-relaxed text-tx-dim">{s.body}</p>
            <button
              type="button"
              disabled={busy}
              onClick={() => {
                setError(null);
                start(async () => {
                  const r = await s.run();
                  if (r && "error" in r && r.error) setError(r.error);
                  else onRefresh();
                });
              }}
              className="inline-flex items-center justify-center gap-1.5 rounded-[9px] border border-[#8b5cff]/45 bg-[linear-gradient(120deg,rgba(80,40,190,.35),rgba(30,44,130,.25))] px-3 py-1.5 text-[11.5px] font-bold text-tx transition hover:border-[#8b5cff]/70 disabled:opacity-50"
            >
              {busy ? "Working…" : s.cta}
            </button>
          </div>
        ))}
      </div>
      {error && <p className="mt-2 text-[11.5px] text-rose-300">{error}</p>}
    </Panel>
  );
}

/* ── websites ─────────────────────────────────────────────────────────── */

function WebsitesCard({ data, onOpenSite, onViewAll, onAdd, onRefresh }: {
  data: HostingPanelData;
  onOpenSite: (key: string) => void;
  onViewAll: () => void;
  onAdd: () => void;
  onRefresh: () => void;
}) {
  const limit = data.account.maxSites + 1;
