      accent="#4f7cff"
      icon="globe3"
      ink="text-[#8fb6ff]"
      fill={false}
      action={
        <span className="flex items-center gap-3">
          <span className="num text-[11.5px] font-bold text-tx-dim">
            {data.sites.length} <span className="text-tx-faint">/ {limit}</span>
          </span>
          <button type="button" onClick={onViewAll} className="text-[11.5px] font-semibold text-brand-300 hover:text-tx">
            View more →
          </button>
        </span>
      }
    >
      <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">
        {data.sites.map((s) => (
          <WebsiteCard
            key={s.key}
            accountId={data.account.id}
            site={s}
            appMenu={data.appMenu}
            accountActive={data.account.status === "ACTIVE"}
