/**
 * ONE website, on its own.
 *
 * The brief's central point: the PLAN owns the limits, a WEBSITE owns an
 * environment. This view is that environment — the site's address and
 * certificate, its own filesystem rooted at its own docroot, the database it
 * uses, and the app running on it. Nothing on this screen is plan-wide.
 *
 * WHAT IS GENUINELY SEPARATE, AND WHAT IS NOT — because the panel is required to
 * say so rather than imply more isolation than the backend provides:
 *
 *   • FILES really are separate. Every site has its own docroot under the
 *     account home (`public_html`, `subdomains/<label>/public_html`,
 *     `domains/<domain>/public_html`), created by the provisioner, served by its
 *     own nginx vhost. The file browser below is rooted there and cannot see a
 *     sibling site — and an extra SFTP login can be confined to exactly this
 *     folder (Settings → Access).
 *   • DATABASES are NOT. Every database on the plan is granted to one
 *     account-level MySQL user, and all the sites run in one PHP-FPM pool as one
 *     unix user — so any site's code can reach any of them. The Database section
 *     says this in as many words, and what it offers is an ASSIGNMENT (which
 *     database this site's app uses) rather than a private database.
 */

const SITE_STATUS: Record<string, { tone: Tone; label: string; live: boolean }> = {
  ACTIVE: { tone: "ok", label: "Live", live: true },
  PENDING: { tone: "busy", label: "Setting up", live: true },
  DELETING: { tone: "idle", label: "Removing", live: true },
  FAILED: { tone: "bad", label: "Failed", live: false },
};

const KIND_LABEL: Record<HostingSiteCard["kind"], string> = {
  primary: "Main website",
  subdomain: "Subdomain",
  addon: "Addon domain",
};

type Section = "overview" | "files" | "database" | "apps" | "settings";

const SECTIONS: { key: Section; label: string; icon: string }[] = [
  { key: "overview",  label: "Overview",  icon: "donut" },
  { key: "files",     label: "Files",     icon: "folder" },
  { key: "database",  label: "Database",  icon: "dbstack" },
  { key: "apps",      label: "Apps",      icon: "cube" },
  { key: "settings",  label: "Settings",  icon: "gear" },
];

function targetOf(site: HostingSiteCard): SiteTarget {
  if (site.kind === "subdomain" && site.id) return { kind: "subdomain", id: site.id };
  if (site.kind === "addon" && site.id) return { kind: "addon", id: site.id };
  return { kind: "primary" };
}

