function Row({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div className="flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1 border-b border-rim-soft pb-2.5 last:border-0 last:pb-0">
      <dt className="text-[11.5px] font-semibold text-tx-faint">{label}</dt>
      <dd className="min-w-0 text-right">{children}</dd>
    </div>
  );
}

/* ── files ────────────────────────────────────────────────────────────── */

function SiteFiles({ data, site }: { data: HostingPanelData; site: HostingSiteCard }) {
  // Rooted at THIS site's docroot — the browser cannot reach a sibling site from
  // here, which is the whole point of giving a website its own view.
  const api = useMemo(
    () => hostingFileApi(data.account.id, site.fileManagerPath),
    [data.account.id, site.fileManagerPath],
  );
  return (
    <div className="flex flex-col gap-2">
      <p className="text-[11.5px] text-tx-faint">
        These are <span className="font-semibold text-tx-dim">{site.hostname}</span>’s own files, at{" "}
        <span className="mono text-tx-dim">{site.fileManagerPath}</span>. Other websites on this plan live in their own
        folders and aren’t reachable from here.
      </p>
      <FileBrowser key={api.key} api={api} />
    </div>
  );
}

/* ── database ─────────────────────────────────────────────────────────── */

function SiteDatabase({ data, site, onRefresh }: {
  data: HostingPanelData;
  site: HostingSiteCard;
  onRefresh: () => void;
}) {
  const [busy, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const mine = data.databases.filter((d) => d.siteKey === site.key);
  const unassigned = data.databases.filter((d) => !d.siteKey);

  function assign(dbId: string, key: string | null) {
    setError(null);
    start(async () => {
      const r = await setDatabaseSite(dbId, key);
      if (r.error) setError(r.error);
      else onRefresh();
    });
  }

  return (
    <Panel title="Database" accent="#34d399" icon="dbstack" ink="text-emerald-300" fill={false}>
      {/* The honesty note. It is first, not a footnote, because the brief asked
          for per-website isolation and this is the one dimension where the
          platform does not provide it. */}
      <div className="mb-3 flex items-start gap-2.5 rounded-[11px] border border-amber-400/30 bg-amber-500/[0.07] p-2.5">
        <Icon name="warncircle" size={14} tone="inherit" className="mt-0.5 flex-none text-amber-300" />
        <p className="text-[11.5px] leading-relaxed text-tx-dim">
          Databases belong to the <span className="font-semibold text-tx-body">plan</span>, not to one website. Every site
          on this plan runs as the same system user with the same database grant, so any of them can reach any database
          here. Assigning one below records which website uses it — it doesn’t fence it off.
        </p>
      </div>

      {mine.length === 0 ? (
        <p className="text-[12px] text-tx-faint">No database is assigned to this website yet.</p>
      ) : (
        <ul className="flex flex-col gap-2">
          {mine.map((d) => (
            <li key={d.id} className="flex flex-wrap items-center gap-2 rounded-[11px] border border-rim-soft bg-well px-3 py-2">
              <Icon name="dbstack" size={14} tone="inherit" className="flex-none text-emerald-300" />
              <span className="mono min-w-0 flex-1 truncate text-[12.5px] text-tx-body">{d.name}</span>
              <span className="text-[11px] text-tx-faint">user {d.dbUser}</span>
              <button
                type="button"
                disabled={busy}
                onClick={() => assign(d.id, null)}
                className="text-[11px] font-semibold text-tx-faint hover:text-tx disabled:opacity-50"
              >
                Unassign
              </button>
            </li>
          ))}
        </ul>
      )}

      {unassigned.length > 0 && (
        <div className="mt-3 border-t border-rim-soft pt-3">
          <p className="mb-2 text-[10.5px] font-bold uppercase tracking-[0.12em] text-tx-faint">
            Unassigned databases on this plan
          </p>
          <ul className="flex flex-col gap-1.5">
            {unassigned.map((d) => (
              <li key={d.id} className="flex flex-wrap items-center gap-2">
                <span className="mono min-w-0 flex-1 truncate text-[12px] text-tx-dim">{d.name}</span>
                <button
                  type="button"
                  disabled={busy}
                  onClick={() => assign(d.id, site.key)}
                  className="rounded-[8px] border border-rim-hi px-2 py-1 text-[11px] font-semibold text-tx-body transition hover:border-[#8b5cff]/50 hover:text-tx disabled:opacity-50"
                >
                  Use for this website
                </button>
              </li>
            ))}
          </ul>
        </div>
      )}

      {error && <p className="mt-2 text-[11.5px] text-rose-300">{error}</p>}
    </Panel>
  );
}

/* ── apps ─────────────────────────────────────────────────────────────── */

function SiteApps({ data, site, onRefresh }: {
  data: HostingPanelData;
  site: HostingSiteCard;
  onRefresh: () => void;
}) {
  const [busy, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [pending, setPending] = useState<string | null>(null);

  function install(slug: string) {
    setError(null);
    setPending(slug);
    start(async () => {
      const r = slug === "wordpress"
        ? await installWordPress(data.account.id, targetOf(site))
        : await installApp(data.account.id, slug, targetOf(site));
      setPending(null);
      if (r.error) setError(r.error);
      else onRefresh();
    });
  }

  return (
    <Panel title="Install an app" accent="#8b5cff" icon="cube" ink="text-violet-300" fill={false}>
      {site.installedApp && (
        <div className="mb-3 flex items-center gap-2.5 rounded-[11px] border border-emerald-400/30 bg-emerald-500/[0.07] p-2.5">
          <AppMark label={site.installedApp} app={findApp(data.appMenu, site.installedApp)} size={18} />
          <p className="text-[11.5px] leading-relaxed text-tx-dim">
            <span className="font-semibold text-tx-body">{site.installedApp}</span> is already installed here. Installing
            another app writes into the same folder and can break the first one.
          </p>
        </div>
      )}

      <div className="grid gap-2 sm:grid-cols-2 xl:grid-cols-3">
        {data.appMenu.map((app) => (
          <button
            key={app.slug}
            type="button"
            disabled={busy || site.status !== "ACTIVE"}
            onClick={() => install(app.slug)}
            className="flex min-w-0 items-start gap-2.5 rounded-[12px] border border-rim-soft bg-well p-3 text-left transition hover:border-[#8b5cff]/55 disabled:opacity-50"
          >
            <AppMark label={app.name} app={app} size={26} />
            <span className="flex min-w-0 flex-1 flex-col">
              <span className="flex items-center gap-1.5">
                <span className="truncate text-[12.5px] font-extrabold text-tx">{app.name}</span>
                {pending === app.slug && <Icon name="refresh2" size={11} tone="inherit" className="nx-spin text-sky-300" />}
              </span>
              <span className="mt-0.5 line-clamp-2 text-[11px] leading-relaxed text-tx-faint">{app.blurb}</span>
              {app.needsDb && (
                <span className="mt-1 text-[10px] font-bold uppercase tracking-wide text-tx-faint">Uses a database</span>
              )}
            </span>
          </button>
        ))}
      </div>

      {error && <p className="mt-2 text-[11.5px] text-rose-300">{error}</p>}
      <p className="mt-3 text-[11px] leading-relaxed text-tx-faint">
        WordPress installs and configures itself and hands you a login. The rest are downloaded and unpacked into this
        website’s folder — you finish their own web installer in the browser, with the database details we create.
      </p>
    </Panel>
  );
}

/* ── settings ─────────────────────────────────────────────────────────── */

function SiteSettings({ data, site, onRefresh, onBack }: {
  data: HostingPanelData;
  site: HostingSiteCard;
  onRefresh: () => void;
  onBack: () => void;
}) {
  const [busy, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [confirmPromote, setConfirmPromote] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(false);

  const removable = site.kind === "subdomain" || site.kind === "addon";

  return (
    <div className="flex flex-col gap-3">
      {site.canSetPrimary && (
        <Panel title="Make this the main website" accent="#4f7cff" icon="crown" ink="text-[#8fb6ff]" fill={false}>
          <p className="max-w-[72ch] text-[12px] leading-relaxed text-tx-dim">
            Your plan’s main website — the one served from <span className="mono text-tx-body">public_html</span> — will
            answer on <span className="mono text-tx-body">{site.hostname}</span> instead. Your current address keeps
            working as an alias, and if anything goes wrong the old one keeps serving.
          </p>
          <button
            type="button"
            disabled={busy}
            onClick={() => setConfirmPromote(true)}
            className="mt-3 inline-flex items-center gap-1.5 rounded-[10px] border border-rim-hi bg-[color-mix(in_srgb,var(--fg)_5%,transparent)] px-3 py-1.5 text-[12px] font-semibold text-tx-body transition hover:border-[#8b5cff]/50 hover:text-tx disabled:opacity-50"
          >
            <Icon name="crown" size={12} tone="inherit" /> Set as main website
          </button>
        </Panel>
      )}

      {removable ? (
        <Panel title="Remove this website" accent="#f43f5e" icon="trash" ink="text-rose-300" fill={false}>
          <p className="max-w-[72ch] text-[12px] leading-relaxed text-tx-dim">
            Deletes <span className="mono text-tx-body">{site.hostname}</span> and everything in its folder. Databases on
            the plan are not touched. This frees a slot against your plan’s website allowance.
          </p>
          <button
            type="button"
            disabled={busy}
            onClick={() => setConfirmDelete(true)}
            className="mt-3 inline-flex items-center gap-1.5 rounded-[10px] border border-rose-400/40 px-3 py-1.5 text-[12px] font-semibold text-rose-300 transition hover:bg-rose-500/10 disabled:opacity-50"
          >
            <Icon name="trash" size={12} tone="inherit" /> Delete website
          </button>
        </Panel>
      ) : (
        <Panel title="Removing this website" accent="#64748b" icon="warncircle" ink="text-slate-300" fill={false}>
          <p className="max-w-[72ch] text-[12px] leading-relaxed text-tx-dim">
            This is the plan’s main website, so it can’t be deleted on its own — cancelling the hosting plan is what
            removes it. To move your main site to a different domain, add that domain as a website and promote it here.
          </p>
        </Panel>
      )}

      {error && <p className="text-[12px] text-rose-300">{error}</p>}

      <Confirm
        open={confirmPromote}
        title="Change your main website?"
        body={
          <>
            <span className="mono text-tx">{site.hostname}</span> becomes the address your main site answers on.{" "}
            <span className="mono text-tx">{data.account.primaryDomain}</span> keeps working as an alias. If you run
            WordPress, its site URL is rewritten for you.
          </>
        }
        confirmLabel="Make it the main website"
        onClose={() => setConfirmPromote(false)}
        onConfirm={() => {
          if (!site.id) return;
          setError(null);
          start(async () => {
            const r = await setPrimaryHostingDomain(data.account.id, site.id!);
            if (r.error) setError(r.error);
            else onRefresh();
          });
        }}
      />

      <Confirm
        open={confirmDelete}
        danger
        typeToConfirm={site.hostname}
        title="Delete this website?"
        body={<>Its folder and everything in it is removed from the node. This can’t be undone.</>}
        confirmLabel="Delete website"
        onClose={() => setConfirmDelete(false)}
        onConfirm={() => {
          if (!site.id) return;
          setError(null);
          start(async () => {
            const r = site.kind === "subdomain"
              ? await deleteSubdomain(site.id!)
              : await deleteAddonDomain(site.id!);
            if (r.error) setError(r.error);
            else { onRefresh(); onBack(); }
          });
        }}
      />
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { Icon } from "@/components/nx/Icon";
import { Panel, Segmented } from "@/components/customer/vpspanel/v2/kit";
import { createSubdomain, createAddonDomain } from "@/lib/actions-hosting";
import { WebsiteCard, AddWebsiteCard } from "./WebsiteCard";
import { WebsiteDetail } from "./WebsiteDetail";
import type { HostingPanelData } from "./types";

/**
 * Every website on the plan, and the way into any one of them.
 *
 * Two screens in one tab: the grid, and — once a site is picked — that site's
 * own dashboard (WebsiteDetail). The old panel had a flat list of rows with an
 * "Install app…" dropdown on each and no way to go *into* a website at all,
 * which is why a customer with three sites had to work out for themselves which
 * folder in the plan-wide file manager belonged to which domain.
 *
 * The plan/website split is enforced by what each screen may say: this one talks
 * about the ALLOWANCE (how many websites of how many), the detail screen talks
 * about ONE website and never about a limit.
 */

export function HostingWebsitesPanel({ data, selected, onSelect, onRefresh }: {
  data: HostingPanelData;
  selected: string | null;
  onSelect: (key: string | null) => void;
  onRefresh: () => void;
}) {
  const site = selected ? data.sites.find((s) => s.key === selected) ?? null : null;

  if (site) {
    return <WebsiteDetail data={data} site={site} onBack={() => onSelect(null)} onRefresh={onRefresh} />;
  }

  const limit = data.account.maxSites + 1;
  const full = data.sites.length >= limit;

  return (
    <div className="flex flex-col gap-3">
      <Panel
        title="Websites on this plan"
        accent="#4f7cff"
        icon="globe3"
        ink="text-[#8fb6ff]"
        fill={false}
        action={
          <span className="num text-[11.5px] font-bold text-tx-dim">
            {data.sites.length} <span className="text-tx-faint">/ {limit}</span>
          </span>
        }
      >
        <p className="mb-3 max-w-[80ch] text-[11.5px] leading-relaxed text-tx-faint">
          Each website has its own address, its own certificate and its own folder on the server. Storage, bandwidth,
          databases and the number of websites are limits on the <span className="font-semibold text-tx-dim">plan</span>,
          shared across all of them.
        </p>
        <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">
          {data.sites.map((s) => (
            <WebsiteCard
              key={s.key}
              accountId={data.account.id}
              site={s}
              appMenu={data.appMenu}
              accountActive={data.account.status === "ACTIVE"}
              onOpen={() => onSelect(s.key)}
              onRefresh={onRefresh}
            />
          ))}
          <AddWebsiteCard
            onAdd={() => document.getElementById("nx-add-website")?.scrollIntoView({ behavior: "smooth", block: "center" })}
            full={full}
            limit={limit}
          />
        </div>
      </Panel>

      <div id="nx-add-website">
        <AddWebsite data={data} full={full} limit={limit} onRefresh={onRefresh} />
      </div>
    </div>
  );
}

/* ── adding one ───────────────────────────────────────────────────────── */

function AddWebsite({ data, full, limit, onRefresh }: {
  data: HostingPanelData;
  full: boolean;
  limit: number;
  onRefresh: () => void;
}) {
  const a = data.account;
  const [mode, setMode] = useState<"subdomain" | "domain">("subdomain");
  const [label, setLabel] = useState("");
  const [domain, setDomain] = useState("");
  const [busy, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [done, setDone] = useState<string | null>(null);

  const cleanLabel = label.trim().toLowerCase().replace(/[^a-z0-9-]/g, "");

  function submit() {
    setError(null);
    setDone(null);
    start(async () => {
      const r = mode === "subdomain"
        ? await createSubdomain(a.id, cleanLabel)
        : await createAddonDomain(a.id, domain.trim().toLowerCase());
      if (r.error) { setError(r.error); return; }
      setDone(mode === "subdomain" ? `${cleanLabel}.${a.primaryDomain}` : domain.trim().toLowerCase());
      setLabel("");
      setDomain("");
      onRefresh();
    });
  }

  if (full) {
    return (
      <Panel title="Add a website" accent="#f59e0b" icon="warncircle" ink="text-amber-300" fill={false}>
        <p className="max-w-[72ch] text-[12px] leading-relaxed text-tx-dim">
          This plan covers {limit} website{limit === 1 ? "" : "s"} and all of them are in use. Upgrade the plan to add
          more, or remove one you no longer need.
        </p>
      </Panel>
    );
  }

  return (
    <Panel title="Add a website" accent="#8b5cff" icon="plussq" ink="text-violet-300" fill={false}>
      <Segmented
        value={mode}
        onChange={setMode}
        items={[
          { key: "subdomain", label: "Subdomain", icon: "globe3" },
          { key: "domain", label: "A domain I own", icon: "globe2" },
        ]}
      />

      {mode === "subdomain" ? (
        <div className="mt-3">
          <p className="mb-2 max-w-[72ch] text-[11.5px] leading-relaxed text-tx-faint">
            A subdomain of your plan’s main address. It gets its own folder and its own certificate, and there is no DNS
            to configure — it resolves as soon as it is created.
          </p>
          <div className="flex flex-wrap items-center gap-2">
            <input
              value={label}
              onChange={(e) => setLabel(e.target.value)}
              placeholder="shop"
              spellCheck={false}
              maxLength={32}
              className="input mono w-[160px]"
            />
            <span className="mono text-[12.5px] text-tx-dim">.{a.primaryDomain}</span>
            <button
              type="button"
              disabled={busy || cleanLabel.length < 1}
              onClick={submit}
              className="nx-cta px-3.5 py-2 text-[12.5px] disabled:opacity-40"
            >
              {busy ? "Creating…" : "Create website"}
            </button>
          </div>
        </div>
      ) : (
        <div className="mt-3">
          <p className="mb-2 max-w-[72ch] text-[11.5px] leading-relaxed text-tx-faint">
            A domain you already own. After it’s added, point its{" "}
            <span className="mono text-tx-dim">A</span> record at{" "}
            <span className="mono text-tx-dim">{a.pointToA}</span> — a certificate is issued automatically once it
            resolves to us.
          </p>
          <div className="flex flex-wrap items-center gap-2">
            <input
              value={domain}
              onChange={(e) => setDomain(e.target.value)}
              placeholder="example.com"
              spellCheck={false}
              maxLength={190}
              className="input mono w-[260px]"
            />
            <button
              type="button"
              disabled={busy || domain.trim().length < 4}
              onClick={submit}
              className="nx-cta px-3.5 py-2 text-[12.5px] disabled:opacity-40"
            >
              {busy ? "Adding…" : "Add website"}
            </button>
          </div>
        </div>
      )}

      {error && <p className="mt-2.5 text-[12px] text-rose-300">{error}</p>}
      {done && (
        <p className="mt-2.5 flex items-center gap-1.5 text-[12px] text-emerald-300">
          <Icon name="checkcircle" size={12} tone="inherit" />
          <span className="mono">{done}</span> is being created — it appears above in a moment.
        </p>
      )}
    </Panel>
  );
}

"use client";

import { useMemo, useState } from "react";
import { Icon } from "@/components/nx/Icon";
import { FileBrowser } from "@/components/customer/files/FileBrowser";
import { hostingFileApi } from "@/lib/files-adapters";
import type { HostingPanelData } from "./types";

/**
 * Files — the SAME file manager the VPS and game-server panels use.
 *
 * Not a second implementation of one. `components/customer/files/FileBrowser`
 * is now driven by a `FileApi` adapter, so the three-pane browser, the lazy
 * folder tree, search, sorting, multi-select, the inline editor and the XHR
 * upload queue with real byte progress are literally the same component here as
 * on a VPS — only the backend behind the adapter differs (SFTP into the hosting
 * account instead of SSH into a VM). The old hosting FileManager was a separate
 * 326-line flat list with none of that.
 *
 * The scope picker is the hosting-specific part: a plan holds several websites,
 * each with its own docroot, so the browser can be rooted at the whole account
 * or at one website's folder. Rooting it at a website is what makes "this site's
 * files" a real, navigable thing rather than a path a customer has to know.
 */

export function HostingFilesPanel({ data, initialPath }: { data: HostingPanelData; initialPath?: string }) {
  // If we were deep-linked to a path, open the scope that contains it — a link
  // from a website card should land in that website, not at the account root.
  const initialScope = useMemo(() => {
    if (!initialPath) return "";
    const match = data.sites.find((s) => initialPath.startsWith(s.fileManagerPath));
    return match ? match.fileManagerPath : "";
  }, [initialPath, data.sites]);

  const [root, setRoot] = useState<string>(initialScope);
  const api = useMemo(() => hostingFileApi(data.account.id, root), [data.account.id, root]);

  return (
    <div className="flex flex-col gap-3">
      <div className="card card-glass flex flex-wrap items-center gap-2 px-3.5 py-2.5">
        <Icon name="folder" size={14} tone="inherit" className="flex-none text-[#7fb0ff]" />
        <span className="text-[11.5px] font-bold uppercase tracking-[0.12em] text-tx-faint">Browsing</span>
        <select
          value={root}
          onChange={(e) => setRoot(e.target.value)}
          className="input py-1 text-[12px]"
          aria-label="Which folder to browse"
        >
          <option value="">Whole account</option>
          {data.sites.map((s) => (
            <option key={s.key} value={s.fileManagerPath}>
              {s.hostname}
            </option>
          ))}
        </select>
        <span className="mono text-[11.5px] text-tx-faint">
          {root ? `/${root}` : "/ (account home)"}
        </span>
      </div>

      <FileBrowser key={api.key} api={api} />
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { Icon } from "@/components/nx/Icon";
import { Panel } from "@/components/customer/vpspanel/v2/kit";
import {
  createHostingDatabase, revealHostingDbPassword, resetHostingDbPassword,
} from "@/lib/actions-hosting";
import { setDatabaseSite } from "@/lib/actions-hosting-sites";
import { DbManager } from "../DbManager";
import type { HostingPanelData } from "./types";

/**
 * Databases — the plan's databases, and Nxeon DB Studio over them.
 *
 * DB Studio itself is unchanged and mounted as-is: it is a large, audited
 * surface with its own security model (every statement runs server-side as the
 * account's scoped MySQL user, over a fresh tunnel), and re-skinning it was not
 * this pass's job. What changed around it is the list: it is now a proper card
 * that says what a database is FOR — which website uses it — instead of a run of
 * grey text with three inline links.
 *
 * The cap is the PLAN's. That is stated once, here, where the create control is.
 */

export function HostingDatabasesPanel({ data, onRefresh }: {
  data: HostingPanelData;
  onRefresh: () => void;
}) {
  const a = data.account;

  if (a.maxDatabases <= 0) {
    return (
      <Panel title="Databases" accent="#34d399" icon="dbstack" ink="text-emerald-300" fill={false}>
        <p className="max-w-[72ch] text-[12.5px] leading-relaxed text-tx-dim">
          Your plan doesn’t include any databases. A larger plan adds them — a database is what WordPress, Joomla and
          most other apps store their content in.
        </p>
      </Panel>
    );
  }

  return (
    <div className="flex flex-col gap-3">
      <DatabaseList data={data} onRefresh={onRefresh} />
      {/* Nxeon DB Studio — the in-portal browser/query tool. */}
      <DbManager accountId={a.id} />
    </div>
  );
}

function DatabaseList({ data, onRefresh }: { data: HostingPanelData; onRefresh: () => void }) {
  const a = data.account;
  const [label, setLabel] = useState("");
  const [busy, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [created, setCreated] = useState<{ name: string; password: string } | null>(null);

  const used = data.databases.length;
  const full = used >= a.maxDatabases;

  function create() {
    if (!label.trim()) return;
    setError(null);
    start(async () => {
      const r = await createHostingDatabase(a.id, label.trim());
      if (r.error) { setError(r.error); return; }
      const slug = label.trim().toLowerCase().replace(/[^a-z0-9]/g, "").slice(0, 12) || "db";
      setCreated({ name: `${a.username}_${slug}`, password: r.password ?? "" });
      setLabel("");
      onRefresh();
    });
  }

  return (
    <Panel
      title="Databases on this plan"
      accent="#34d399"
      icon="dbstack"
      ink="text-emerald-300"
      fill={false}
      action={
        <span className="num text-[11.5px] font-bold text-tx-dim">
          {used} <span className="text-tx-faint">/ {a.maxDatabases}</span>
        </span>
      }
    >
      {data.databases.length === 0 ? (
        <p className="text-[12px] text-tx-faint">
          No databases yet. Most apps need one — installing WordPress from the Apps tab creates it for you.
        </p>
      ) : (
        <ul className="flex flex-col gap-2">
          {data.databases.map((d) => (
            <DbRow key={d.id} data={data} db={d} onRefresh={onRefresh} />
          ))}
        </ul>
      )}

      {created && (
        <div className="mt-3 rounded-[11px] border border-emerald-400/35 bg-emerald-500/[0.08] p-3">
          <p className="text-[11.5px] font-bold text-emerald-300">Created — copy this password now</p>
          <p className="mt-1 text-[11.5px] text-tx-dim">
            <span className="mono text-tx-body">{created.name}</span> · password{" "}
            <span className="mono text-tx-body">{created.password}</span>
          </p>
        </div>
      )}

      <div className="mt-3 border-t border-rim-soft pt-3">
        {full ? (
          <p className="text-[11.5px] text-tx-faint">
            You’ve used every database on this plan. Upgrade to add more.
          </p>
        ) : (
          <div className="flex flex-wrap items-center gap-2">
            <span className="mono text-[12px] text-tx-faint">{a.username}_</span>
            <input
              value={label}
              onChange={(e) => setLabel(e.target.value)}
              placeholder="shop"
              maxLength={12}
              spellCheck={false}
              className="input mono w-[150px]"
            />
            <button
              type="button"
              disabled={busy || !label.trim()}
              onClick={create}
              className="nx-cta px-3.5 py-2 text-[12.5px] disabled:opacity-40"
            >
              {busy ? "Creating…" : "Create database"}
            </button>
          </div>
        )}
        {error && <p className="mt-2 text-[11.5px] text-rose-300">{error}</p>}
      </div>
    </Panel>
  );
}

function DbRow({ data, db, onRefresh }: {
  data: HostingPanelData;
  db: HostingPanelData["databases"][number];
  onRefresh: () => void;
}) {
  const [pw, setPw] = useState<string | null>(null);
  const [note, setNote] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, start] = useTransition();

  const site = db.siteKey ? data.sites.find((s) => s.key === db.siteKey) ?? null : null;
  const live = db.status === "ACTIVE";

  return (
    <li className="flex flex-col gap-2 rounded-[12px] border border-rim-soft bg-well px-3 py-2.5">
      <div className="flex flex-wrap items-center gap-2">
        <Icon name="dbstack" size={14} tone="inherit" className={"flex-none " + (live ? "text-emerald-300" : "text-amber-300")} />
        <span className="mono min-w-0 flex-1 truncate text-[12.5px] font-semibold text-tx-body">{db.name}</span>
        <span className="text-[11px] text-tx-faint">user <span className="mono">{db.dbUser}</span></span>
        {!live && (
          <span className="rounded-[6px] border border-amber-400/40 bg-amber-500/12 px-1.5 py-0.5 text-[10px] font-bold uppercase text-amber-300">
            {db.status.toLowerCase()}
          </span>
        )}
      </div>

      <div className="flex flex-wrap items-center gap-x-3 gap-y-2">
        {/* Which website uses it. Stated as a customer-set assignment, never as
            an isolation boundary — every site on the plan can reach every one of
            these. See the note on the per-site Database section. */}
        <label className="flex items-center gap-1.5 text-[11px] text-tx-faint">
          Used by
          <select
            value={db.siteKey ?? ""}
            disabled={busy}
            onChange={(e) => {
              setError(null);
              const v = e.target.value || null;
              start(async () => {
                const r = await setDatabaseSite(db.id, v);
                if (r.error) setError(r.error);
                else onRefresh();
              });
            }}
            className="input py-0.5 text-[11.5px]"
          >
            <option value="">Not assigned</option>
            {data.sites.map((s) => (
              <option key={s.key} value={s.key}>{s.hostname}</option>
            ))}
          </select>
        </label>

        {pw ? (
          <span className="mono text-[11.5px] text-[#b79bff]">{pw}</span>
        ) : (
          <button
            type="button"
            disabled={busy}
            className="text-[11px] font-semibold text-brand-300 hover:text-tx disabled:opacity-50"
            onClick={() => {
              setError(null);
              start(async () => {
                const r = await revealHostingDbPassword(db.id);
                if (r.error) setError(r.error);
                else setPw(r.password ?? "");
              });
            }}
          >
            Show password
          </button>
        )}
        <button
          type="button"
          disabled={busy}
          className="text-[11px] font-semibold text-tx-faint hover:text-tx disabled:opacity-50"
          onClick={() => {
            setError(null);
            start(async () => {
              const r = await resetHostingDbPassword(db.id);
              if (r.error) setError(r.error);
              else { setPw(r.password ?? ""); setNote("New password set — active in a moment."); }
            });
          }}
        >
          Reset password
        </button>
        {site && <span className="text-[10.5px] text-tx-faint">· {site.hostname}</span>}
      </div>

      {note && <p className="text-[10.5px] text-emerald-300">{note}</p>}
      {error && <p className="text-[10.5px] text-rose-300">{error}</p>}
    </li>
  );
}

"use client";

import { useEffect, useState, useTransition } from "react";
import { Icon } from "@/components/nx/Icon";
import { Panel, Confirm, Empty } from "@/components/customer/vpspanel/v2/kit";
import { createHostingBackup, listHostingBackups, restoreHostingBackup } from "@/lib/actions-hosting";
import type { HostingPanelData } from "./types";

/**
 * Backups of the whole plan — files and every database, in one archive.
 *
 * DELIBERATELY ABSENT: a download button and a storage meter.
 *   • The archive is written root-owned into a directory on the node
 *     (worker/hosting.ts taskBackup); nothing in the product streams it to the
 *     customer, so a Download button would be a button that cannot work.
 *   • There is no backup quota column anywhere, so there is no ceiling to draw.
 * Both are real gaps and the card says so, rather than papering over them —
 * same rule the game panel's backups tab follows.
 */

function fmtSize(b: number): string {
  if (b >= 1024 ** 3) return `${(b / 1024 ** 3).toFixed(2)} GB`;
  if (b >= 1024 ** 2) return `${(b / 1024 ** 2).toFixed(1)} MB`;
  return `${(b / 1024).toFixed(0)} KB`;
}

export function HostingBackupsPanel({ data, onRefresh }: { data: HostingPanelData; onRefresh: () => void }) {
  const [rows, setRows] = useState<{ id: string; sizeBytes: number; createdAt: string }[] | null>(null);
  const [busy, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [note, setNote] = useState<string | null>(null);
  const [restoring, setRestoring] = useState<string | null>(null);

  const load = () => listHostingBackups(data.account.id).then(setRows).catch(() => setRows([]));
  useEffect(() => { void load(); /* eslint-disable-next-line react-hooks/exhaustive-deps */ }, [data.account.id]);

  return (
    <div className="flex flex-col gap-3">
      <Panel
        title="Backups"
        accent="#f59e0b"
        icon="archive"
        ink="text-amber-300"
        fill={false}
        action={
          <button
            type="button"
            disabled={busy}
            onClick={() => {
              setError(null); setNote(null);
              start(async () => {
                const r = await createHostingBackup(data.account.id);
                if (r.error) { setError(r.error); return; }
                setNote("Backup queued — it appears here when the archive finishes.");
                setTimeout(() => { void load(); onRefresh(); }, 2500);
              });
            }}
            className="nx-cta inline-flex items-center gap-1.5 px-3 py-1.5 text-[12px] disabled:opacity-50"
          >
            <Icon name="plus" size={12} tone="inherit" /> Back up now
          </button>
        }
      >
        <p className="mb-3 max-w-[80ch] text-[11.5px] leading-relaxed text-tx-faint">
          One archive per run, covering every website’s files and every database on the plan. Run one before a big
          change — a theme update, a PHP switch, a migration. Backups are stored on the node outside your account’s
          storage quota, so they don’t count against it.
        </p>

        {rows === null ? (
          <p className="text-[12px] text-tx-faint">Loading…</p>
        ) : rows.length === 0 ? (
          <Empty
            icon="archive"
            title="No backups yet"
            body="Nothing has been archived for this plan. The first run takes a moment and covers everything."
          />
        ) : (
          <ul className="flex flex-col gap-2">
            {rows.map((b) => (
              <li key={b.id} className="flex flex-wrap items-center gap-3 rounded-[12px] border border-rim-soft bg-well px-3 py-2.5">
                <Icon name="archive" size={14} tone="inherit" className="flex-none text-amber-300" />
                <span className="flex min-w-0 flex-1 flex-col leading-tight">
                  <span className="truncate text-[12.5px] font-semibold text-tx-body">
                    {new Date(b.createdAt).toLocaleString()}
                  </span>
                  <span className="num text-[10.5px] text-tx-faint">{fmtSize(b.sizeBytes)}</span>
                </span>
                <button
                  type="button"
                  disabled={busy}
                  onClick={() => setRestoring(b.id)}
                  className="flex-none rounded-[9px] border border-rim-hi px-2.5 py-1 text-[11.5px] font-semibold text-tx-body transition hover:border-[#8b5cff]/50 hover:text-tx disabled:opacity-50"
                >
                  Restore
                </button>
              </li>
            ))}
          </ul>
        )}

        {error && <p className="mt-2 text-[12px] text-rose-300">{error}</p>}
        {note && <p className="mt-2 text-[12px] text-emerald-300">{note}</p>}

        <p className="mt-3 border-t border-rim-soft pt-2.5 text-[11px] leading-relaxed text-tx-faint">
          Archives live on the hosting node and can’t be downloaded from the panel yet — there’s no route that streams
          one out. If you need a copy off the server, open a ticket and we’ll get it to you.
        </p>
      </Panel>

      <Confirm
        open={restoring !== null}
        danger
        title="Restore this backup?"
        body={
          <>
            Every website’s files and every database on this plan are replaced with what was in the archive. Anything
            changed since is lost. This cannot be undone.
          </>
        }
        confirmLabel="Restore"
        onClose={() => setRestoring(null)}
        onConfirm={() => {
          const id = restoring;
          if (!id) return;
          setError(null); setNote(null);
          start(async () => {
            const r = await restoreHostingBackup(data.account.id, id);
            if (r.error) setError(r.error);
            else { setNote("Restore queued — watch Activity for it to finish."); onRefresh(); }
          });
        }}
      />
    </div>
  );
}

"use client";

import { useEffect } from "react";
import { ActivityCard } from "./OverviewCards";
import type { HostingPanelData } from "./types";

/**
 * Activity — the full record of what the platform has run for this plan.
 *
 * This is what the old Overview's "task feed" became. The feed was a run of
 * coloured one-liners beneath the quota tiles that also, on a completed
 * WordPress install, printed the admin username and password inline — a
 * credential in a scrolling event log, duplicated from the App-credentials card
 * three inches above it. The credential now lives on the website it belongs to,
 * and this is purely a history.
 *
 * Polls only while something is actually in flight; a finished plan's history
 * does not change on its own.
 */
export function HostingActivityPanel({ data, onRefresh }: {
  data: HostingPanelData;
  onRefresh: () => void;
}) {
  const inFlight = data.activity.some((t) => t.status === "PENDING" || t.status === "RUNNING");

  useEffect(() => {
    if (!inFlight) return;
    const t = setInterval(onRefresh, 5000);
    return () => clearInterval(t);
  }, [inFlight, onRefresh]);

  return (
    <div className="flex flex-col gap-3">
      <ActivityCard data={data} compact={false} />
      <p className="px-1 text-[11px] leading-relaxed text-tx-faint">
        Everything we run on your behalf goes through one queue — app installs, PHP switches, new websites, backups,
        plan changes. This is that queue, newest first. Sign-in records aren’t here: shared hosting has no per-account
        SSH session log to read.
      </p>
    </div>
  );
}

"use client";

import { useEffect, useState, useTransition } from "react";
import Link from "next/link";
import { Icon } from "@/components/nx/Icon";
import { Panel } from "@/components/customer/vpspanel/v2/kit";
import { getHostingEmailStatus, setupHostingEmail } from "@/lib/hosting-email";
import type { HostingPanelData } from "./types";

/**
 * Email — the mailboxes bundled with the plan.
 *
 * This tab has exactly one job and does not pretend otherwise: switch on the
 * complimentary subscription that the plan already pays for, then hand over to
 * /dashboard/email, which is the audited surface that actually creates
 * mailboxes and verifies DNS. Re-implementing mailbox management here would be a
 * second place for the plan quota to be enforced, and quotas enforced twice are
 * quotas enforced wrong.
 *
 * Three states, one at a time — never the "set up" pitch beside a "manage your
 * mailboxes" link, which is the pattern this redesign is removing everywhere.
 */

type Status = {
  planName?: string;
  primaryDomain?: string;
  includedMailboxes?: number;
  hasSubscription?: boolean;
  verified?: boolean;
  error?: string;
};

export function HostingEmailPanel({ data }: { data: HostingPanelData }) {
  const [status, setStatus] = useState<Status | null>(null);
  const [busy, start] = useTransition();
  const [error, setError] = useState<string | null>(null);

  const load = () =>
    getHostingEmailStatus(data.account.id)
      .then(setStatus)
      .catch(() => setStatus({ error: "Couldn’t load your email status." }));

  useEffect(() => { void load(); /* eslint-disable-next-line react-hooks/exhaustive-deps */ }, [data.account.id]);

  if (!status) {
    return (
      <Panel title="Email" accent="#f59e0b" icon="envelope" ink="text-amber-300" fill={false}>
        <p className="text-[12px] text-tx-faint">Loading…</p>
      </Panel>
    );
  }
  if (status.error) {
    return (
      <Panel title="Email" accent="#f43f5e" icon="envelope" ink="text-rose-300" fill={false}>
        <p className="text-[12px] text-rose-300">{status.error}</p>
      </Panel>
    );
  }

  const count = status.includedMailboxes ?? 0;
  const word = count === 1 ? "mailbox" : "mailboxes";
  const unlimited = count < 0;

  return (
    <Panel
      title="Email on your domain"
      accent="#f59e0b"
      icon="envelope"
      ink="text-amber-300"
      fill={false}
      action={
        status.hasSubscription ? (
          <span
            className={
              "inline-flex items-center gap-1.5 rounded-full border px-2 py-0.5 text-[10.5px] font-bold " +
              (status.verified
                ? "border-emerald-400/40 bg-emerald-500/12 text-emerald-300"
                : "border-amber-400/40 bg-amber-500/12 text-amber-300")
            }
          >
            <span className={"h-1.5 w-1.5 rounded-full " + (status.verified ? "bg-emerald-400" : "bg-amber-400")} />
            {status.verified ? "Verified" : "Verify DNS"}
          </span>
        ) : undefined
      }
    >
      <div className="flex items-start gap-3">
        <span className="grid h-[42px] w-[42px] flex-none place-items-center overflow-hidden rounded-[12px] border border-rim-hi bg-well">
          {/* eslint-disable-next-line @next/next/no-img-element -- local product mark */}
          <img src="/nx/svc/email.webp" alt="" className="h-full w-full object-cover" />
        </span>
        <div className="min-w-0 flex-1">
          <p className="text-[13px] leading-relaxed text-tx-body">
            Your <span className="font-extrabold text-tx">{status.planName ?? data.account.planName}</span> plan includes{" "}
            <span className="font-extrabold text-tx">{unlimited ? "unlimited mailboxes" : `${count} ${word}`}</span> on{" "}
            <span className="mono text-tx">{status.primaryDomain ?? data.account.primaryDomain}</span>, at no extra cost.
          </p>

          {!status.hasSubscription ? (
            <>
              <p className="mt-2 max-w-[72ch] text-[12px] leading-relaxed text-tx-dim">
                They aren’t switched on yet. Turning them on creates the subscription; you then add addresses and publish
                the DNS records that route mail to us.
              </p>
              {error && <p className="mt-2 text-[12px] text-rose-300">{error}</p>}
              <button
                type="button"
                disabled={busy}
                onClick={() => {
                  setError(null);
                  start(async () => {
                    const r = await setupHostingEmail(data.account.id);
                    if (r.error) setError(r.error);
                    else void load();
                  });
                }}
                className="nx-cta mt-3 inline-flex items-center gap-1.5 px-3.5 py-2 text-[12.5px] disabled:opacity-50"
              >
                <Icon name="envelope" size={13} tone="inherit" />
                {busy ? "Setting up…" : "Switch on my email"}
              </button>
            </>
          ) : (
            <>
              <p className="mt-2 max-w-[72ch] text-[12px] leading-relaxed text-tx-dim">
                {status.verified
                  ? "Your domain is verified and mail is routing to us. Addresses, forwarders and signatures are all managed on the email dashboard."
                  : "Almost there — add your addresses and publish the DNS records shown on the email dashboard, and mail starts arriving."}
              </p>
              <Link
                href="/dashboard/email"
                className="nx-cta mt-3 inline-flex items-center gap-1.5 px-3.5 py-2 text-[12.5px]"
              >
                Manage mailboxes <Icon name="external" size={12} tone="inherit" />
              </Link>
            </>
          )}
        </div>
      </div>
    </Panel>
  );
}

"use client";

import { useState, useTransition } from "react";
import { Icon } from "@/components/nx/Icon";
import { Panel } from "@/components/customer/vpspanel/v2/kit";
import { installWordPress, installApp, type SiteTarget } from "@/lib/actions-hosting";
import { AppMark, findApp } from "./AppMark";
import type { HostingPanelData, HostingSiteCard } from "./types";

/**
 * One-click apps, across the plan.
 *
 * THE CHANGE THAT MATTERS: an install is aimed at a WEBSITE, and the website is
 * chosen before the app. The old Apps tab installed onto "the account", with the
 * target hidden inside a per-row dropdown on a different tab — so a customer with
 * three sites had no way to see which of them had what, and the Overview's
 * "Install WordPress" button silently always meant the primary site.
 *
 * Each website's current app is shown on its tile, so re-installing over a live
 * site is a visible decision rather than an accident.
 */

function targetOf(site: HostingSiteCard): SiteTarget {
  if (site.kind === "subdomain" && site.id) return { kind: "subdomain", id: site.id };
  if (site.kind === "addon" && site.id) return { kind: "addon", id: site.id };
  return { kind: "primary" };
}

export function HostingAppsPanel({ data, onRefresh }: { data: HostingPanelData; onRefresh: () => void }) {
  const [siteKey, setSiteKey] = useState(data.sites[0]?.key ?? "primary");
  const [busy, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [note, setNote] = useState<string | null>(null);
  const [pending, setPending] = useState<string | null>(null);

  const site = data.sites.find((s) => s.key === siteKey) ?? data.sites[0] ?? null;

  function install(slug: string, name: string) {
    if (!site) return;
    setError(null); setNote(null); setPending(slug);
    start(async () => {
      const r = slug === "wordpress"
        ? await installWordPress(data.account.id, targetOf(site))
        : await installApp(data.account.id, slug, targetOf(site));
      setPending(null);
      if (r.error) setError(r.error);
      else {
        setNote(`${name} is installing onto ${site.hostname}. Watch Activity for it to finish.`);
        onRefresh();
      }
    });
  }

  return (
    <div className="flex flex-col gap-3">
      {/* 1. Where. */}
      <Panel title="Install onto which website?" accent="#4f7cff" icon="globe3" ink="text-[#8fb6ff]" fill={false}>
        <div className="grid gap-2 sm:grid-cols-2 xl:grid-cols-3">
          {data.sites.map((s) => {
            const on = s.key === siteKey;
            return (
              <button
                key={s.key}
                type="button"
                onClick={() => setSiteKey(s.key)}
                disabled={s.status !== "ACTIVE"}
                className={
                  "flex min-w-0 items-center gap-2.5 rounded-[12px] border px-3 py-2.5 text-left transition disabled:opacity-45 " +
                  (on
                    ? "border-[#8b5cff]/70 bg-[linear-gradient(120deg,rgba(80,40,190,.34),rgba(30,44,130,.26))]"
                    : "border-rim-soft bg-well hover:border-[#8b5cff]/40")
                }
              >
                <Icon name="globe3" size={15} tone="inherit" className={"flex-none " + (on ? "text-[#fff]" : "text-tx-dim")} />
                <span className="flex min-w-0 flex-1 flex-col leading-tight">
                  <span className={"truncate text-[12.5px] font-extrabold " + (on ? "text-[#fff]" : "text-tx")}>
                    {s.hostname}
                  </span>
                  <span className="truncate text-[10.5px] text-tx-faint">
                    {s.installedApp ? `${s.installedApp} installed` : "Nothing installed"}
                  </span>
                </span>
                {s.installedApp && (
                  <AppMark label={s.installedApp} app={findApp(data.appMenu, s.installedApp)} size={18} />
                )}
              </button>
            );
          })}
        </div>
      </Panel>

      {/* 2. What. */}
      <Panel title="Choose an app" accent="#8b5cff" icon="cube" ink="text-violet-300" fill={false}>
        {site?.installedApp && (
          <div className="mb-3 flex items-start gap-2.5 rounded-[11px] border border-amber-400/30 bg-amber-500/[0.07] p-2.5">
            <Icon name="warncircle" size={14} tone="inherit" className="mt-0.5 flex-none text-amber-300" />
            <p className="text-[11.5px] leading-relaxed text-tx-dim">
              <span className="mono text-tx-body">{site.hostname}</span> already runs{" "}
              <span className="font-semibold text-tx-body">{site.installedApp}</span>. Installing another app unpacks it
              into the same folder, which usually breaks the first one.
            </p>
          </div>
        )}

        <div className="grid gap-2 sm:grid-cols-2 xl:grid-cols-3">
          {data.appMenu.map((app) => (
            <button
              key={app.slug}
              type="button"
              disabled={busy || !site || site.status !== "ACTIVE"}
              onClick={() => install(app.slug, app.name)}
              className="flex min-w-0 items-start gap-2.5 rounded-[12px] border border-rim-soft bg-well p-3 text-left transition hover:border-[#8b5cff]/55 disabled:opacity-50"
            >
              <AppMark label={app.name} app={app} size={28} />
              <span className="flex min-w-0 flex-1 flex-col">
                <span className="flex items-center gap-1.5">
                  <span className="truncate text-[12.5px] font-extrabold text-tx">{app.name}</span>
                  {pending === app.slug && <Icon name="refresh2" size={11} tone="inherit" className="nx-spin text-sky-300" />}
                </span>
                <span className="mt-0.5 line-clamp-2 text-[11px] leading-relaxed text-tx-faint">{app.blurb}</span>
                {app.needsDb && (
                  <span className="mt-1 text-[10px] font-bold uppercase tracking-wide text-tx-faint">
                    Uses one of your databases
                  </span>
                )}
              </span>
            </button>
          ))}
        </div>

        {error && <p className="mt-2.5 text-[12px] text-rose-300">{error}</p>}
        {note && <p className="mt-2.5 text-[12px] text-emerald-300">{note}</p>}

        <p className="mt-3 border-t border-rim-soft pt-2.5 text-[11px] leading-relaxed text-tx-faint">
          WordPress is fully automated — it installs, creates its database and hands you an admin login, which then
          appears on that website’s own page. The rest are downloaded and unpacked into the website’s folder with a
          database ready; you finish their own installer in the browser.
        </p>
      </Panel>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useState, useTransition } from "react";
import { Icon } from "@/components/nx/Icon";
import { Panel, StatusPill, Confirm, Empty, type Tone } from "@/components/customer/vpspanel/v2/kit";
import { listHostingCrons, createCron, deleteCron, type HostingCronView } from "@/lib/actions-hosting";
import type { HostingPanelData } from "./types";

/**
 * Scheduled commands, run as the plan's own system user.
 *
 * Functionally the same feature as before — same three actions, same validation
 * — rebuilt on the panel kit so it stops being the one screen with a bare HTML
 * table in it. The presets are kept because a five-field cron expression is the
 * single most common thing a shared-hosting customer gets wrong.
 */

const PRESETS: { label: string; value: string }[] = [
  { label: "Every 5 minutes", value: "*/5 * * * *" },
  { label: "Every hour", value: "0 * * * *" },
  { label: "Every day at 03:00", value: "0 3 * * *" },
  { label: "Every Monday at 06:00", value: "0 6 * * 1" },
  { label: "First of the month", value: "0 0 1 * *" },
];

const CRON_STATUS: Record<string, { tone: Tone; label: string; live: boolean }> = {
  ACTIVE: { tone: "ok", label: "Scheduled", live: false },
  PENDING: { tone: "busy", label: "Applying", live: true },
  DELETING: { tone: "idle", label: "Removing", live: true },
  FAILED: { tone: "bad", label: "Failed", live: false },
};

export function HostingCronPanel({ data }: { data: HostingPanelData }) {
  const a = data.account;
  const [rows, setRows] = useState<HostingCronView[] | null>(null);
  const [schedule, setSchedule] = useState("0 3 * * *");
  const [command, setCommand] = useState("");
  const [busy, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [removing, setRemoving] = useState<string | null>(null);

  const refresh = useCallback(() => {
    listHostingCrons(a.id).then(setRows).catch(() => setRows([]));
  }, [a.id]);

  useEffect(() => { refresh(); }, [refresh]);
  useEffect(() => {
    if (!rows?.some((r) => r.status === "PENDING" || r.status === "DELETING")) return;
    const t = setInterval(refresh, 4000);
    return () => clearInterval(t);
  }, [rows, refresh]);

  return (
    <div className="flex flex-col gap-3">
      <Panel title="Scheduled tasks" accent="#3fbcd8" icon="clock" ink="text-cyan-300" fill={false}>
        <p className="mb-3 max-w-[80ch] text-[11.5px] leading-relaxed text-tx-faint">
          Commands run on a schedule as <span className="mono text-tx-dim">{a.username}</span> — your plan’s own system
          user — so they can only touch your own files. WordPress sites usually want{" "}
          <span className="mono text-tx-dim">wp-cron.php</span> on a five-minute schedule.
        </p>

        {rows === null ? (
          <p className="text-[12px] text-tx-faint">Loading…</p>
        ) : rows.length === 0 ? (
          <Empty
            icon="clock"
            title="Nothing scheduled"
            body="No commands run on a schedule for this plan yet. Add one below — backups, cache warmers, cleanup jobs."
          />
        ) : (
          <ul className="flex flex-col gap-2">
            {rows.map((r) => {
              const st = CRON_STATUS[r.status] ?? CRON_STATUS.PENDING;
              return (
                <li key={r.id} className="flex flex-wrap items-center gap-3 rounded-[12px] border border-rim-soft bg-well px-3 py-2.5">
                  <span className="mono flex-none rounded-[7px] border border-rim-hi bg-[color-mix(in_srgb,var(--fg)_4%,transparent)] px-2 py-1 text-[11.5px] text-tx-body">
                    {r.schedule}
                  </span>
                  <span className="mono min-w-0 flex-1 truncate text-[12px] text-tx-dim" title={r.command}>
                    {r.command}
                  </span>
                  <StatusPill tone={st.tone} label={st.label} live={st.live} />
                  <button
                    type="button"
                    disabled={busy || r.status !== "ACTIVE"}
                    onClick={() => setRemoving(r.id)}
                    className="flex-none rounded-[9px] border border-rose-400/35 px-2.5 py-1 text-[11.5px] font-semibold text-rose-300 transition hover:bg-rose-500/10 disabled:opacity-40"
                  >
                    Remove
                  </button>
                </li>
              );
            })}
          </ul>
        )}
      </Panel>

      <Panel title="Add a scheduled task" accent="#8b5cff" icon="calplus" ink="text-violet-300" fill={false}>
        <div className="flex flex-col gap-3">
          <div className="flex flex-wrap items-end gap-3">
            <label className="flex flex-col gap-1">
              <span className="text-[10.5px] font-bold uppercase tracking-[0.12em] text-tx-faint">Schedule</span>
              <input
                value={schedule}
                onChange={(e) => setSchedule(e.target.value)}
                spellCheck={false}
                className="input mono w-[160px]"
              />
            </label>
            <label className="flex flex-col gap-1">
              <span className="text-[10.5px] font-bold uppercase tracking-[0.12em] text-tx-faint">Or pick one</span>
              <select
                value=""
                onChange={(e) => e.target.value && setSchedule(e.target.value)}
                className="input w-[240px] text-[12.5px]"
              >
                <option value="">Choose…</option>
                {PRESETS.map((p) => (
                  <option key={p.value} value={p.value}>{p.label}</option>
                ))}
              </select>
            </label>
          </div>
          <label className="flex flex-col gap-1">
            <span className="text-[10.5px] font-bold uppercase tracking-[0.12em] text-tx-faint">Command</span>
            <input
              value={command}
              onChange={(e) => setCommand(e.target.value)}
              placeholder={`php /home/${a.username}/public_html/wp-cron.php`}
              maxLength={500}
              spellCheck={false}
              className="input mono"
            />
          </label>
          <div className="flex items-center gap-3">
            <button
              type="button"
              disabled={busy || command.trim().length < 2}
              onClick={() => {
                setError(null);
                start(async () => {
                  const r = await createCron(a.id, schedule.trim(), command.trim());
                  if (r.error) setError(r.error);
                  else { setCommand(""); refresh(); }
                });
              }}
              className="nx-cta inline-flex items-center gap-1.5 px-3.5 py-2 text-[12.5px] disabled:opacity-40"
            >
              <Icon name="plus" size={13} tone="inherit" /> {busy ? "Adding…" : "Add task"}
            </button>
            {error && <p className="text-[12px] text-rose-300">{error}</p>}
          </div>
        </div>
      </Panel>

      <Confirm
        open={removing !== null}
        danger
        title="Remove this scheduled task?"
        body={<>It stops running immediately. Nothing it has already done is undone.</>}
        confirmLabel="Remove"
        onClose={() => setRemoving(null)}
        onConfirm={() => {
          const id = removing;
          if (!id) return;
          setError(null);
          start(async () => {
            const r = await deleteCron(id);
            if (r.error) setError(r.error);
            else refresh();
          });
        }}
      />
    </div>
  );
}

