/** SFTP host + port for the account's own login. Taken from the node's real
 *  `sshHost`/`sshPort` — the SAME values lib/hosting-fs.ts connects with, so
 *  what the panel tells a customer to put in FileZilla is what actually works.
 *  A node's public A-record target can differ from its SSH address on NAT. */
sftpHost: string | null;
sftpPort: number;

input.content:
"use client";

import { useEffect, useState, useTransition } from "react";
import { Icon } from "@/components/nx/Icon";
import { Panel, CopyChip, StatusPill, Confirm, type Tone } from "@/components/customer/vpspanel/v2/kit";
import { revealHostingSftpPassword } from "@/lib/actions-hosting";
import {
  listFtpScopes, createFtpUser, deleteFtpUser, resetFtpPassword, revealFtpPassword,
} from "@/lib/actions-hosting-sites";
import { MAX_FTP_USERS } from "@/lib/hosting-sites";
import type { HostingPanelData } from "./types";

/**
 * FTP / SFTP access — one place, and the only place.
 *
 * WHAT THIS FIXES. Before, the account's file-transfer credential was a single
 * grey strip halfway down the Overview tab reading `SFTP  you@1.2.3.4  show
 * password` — no port, no protocol, no client instructions, wedged between a
 * quota grid and a WordPress banner. Customers could not find it, and when they
 * did, it was one credential for the entire plan: handing a developer access to
 * one site meant handing them every site, every database dump and every backup.
 *
 * So there are now two things here, and the distinction is the point:
 *
 *   • THE ACCOUNT LOGIN — full access to everything on the plan. One per
 *     account, created at provision, chrooted to the account home.
 *   • SCOPED LOGINS — as many as eight more, each confined to ONE folder. A
 *     designer gets `/domains/shop.example.com` and cannot see, list or reach
 *     anything else on the plan.
 *
 * THE CONFINEMENT IS REAL AND IS NOT THIS PANEL'S DOING. Each scoped login is a
 * unix user with an sshd `Match User … ChrootDirectory` block on the node
 * (worker/hosting.ts taskCreateFtpUser); read-only ones are simply left out of
 * the account's group, so the kernel refuses their writes. A login shows as
 * "Setting up" until the node confirms it, and FAILED with the node's own reason
 * if sshd refused — this panel never shows a credential as usable before the
 * restriction is actually in force.
 *
 * The protocol is SFTP, over SSH, on the node's SSH port. It is called that here
 * rather than "FTP", because plain FTP is not open on these boxes and telling a
 * customer otherwise sends them to a client that will fail to connect.
 */

const ROW_STATUS: Record<string, { tone: Tone; label: string; live: boolean }> = {
  ACTIVE: { tone: "ok", label: "Ready", live: false },
  PENDING: { tone: "busy", label: "Setting up", live: true },
  DELETING: { tone: "idle", label: "Removing", live: true },
  FAILED: { tone: "bad", label: "Failed", live: false },
};

export function HostingAccessPanel({ data, onRefresh }: {
  data: HostingPanelData;
  onRefresh: () => void;
}) {
  const a = data.account;
  const host = data.sftpHost;
  const port = data.sftpPort;

  return (
    <div className="flex flex-col gap-3">
      <AccountLogin data={data} />
      <ScopedLogins data={data} onRefresh={onRefresh} />

      <Panel title="Connecting" accent="#64748b" icon="terminal" ink="text-slate-300" fill={false}>
        <p className="max-w-[80ch] text-[11.5px] leading-relaxed text-tx-dim">
          Point any SFTP client — FileZilla, WinSCP, Cyberduck, Transmit — at the host and port above, with{" "}
          <span className="font-semibold text-tx-body">SFTP (SSH File Transfer)</span> as the protocol. Plain FTP and
          FTPS are not open on these servers, so a client set to “FTP” will fail to connect. From a terminal:
        </p>
        <div className="mt-2.5 flex flex-wrap gap-2">
          <CopyChip
            label="Command"
            value={host ? `sftp -P ${port} ${a.username}@${host}` : "sftp …"}
          />
        </div>
      </Panel>
    </div>
  );
}

/* ── the account's own credential ─────────────────────────────────────── */

function AccountLogin({ data }: { data: HostingPanelData }) {
  const a = data.account;
  const [pw, setPw] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, start] = useTransition();

  return (
    <Panel title="Your account login" accent="#4f7cff" icon="key" ink="text-[#8fb6ff]" fill={false}>
      <p className="mb-3 max-w-[80ch] text-[11.5px] leading-relaxed text-tx-faint">
        Full access to every website, every folder and every file on this plan. Use it yourself; give a contractor a
        scoped login below instead.
      </p>

      <div className="grid gap-2 sm:grid-cols-2 xl:grid-cols-4">
        <Field label="Protocol" value="SFTP (SSH)" />
        <Field label="Host" value={data.sftpHost ?? "—"} copy={!!data.sftpHost} />
        <Field label="Port" value={String(data.sftpPort)} copy />
        <Field label="Username" value={a.username} copy />
      </div>

      <div className="mt-3 flex flex-wrap items-center gap-3 border-t border-rim-soft pt-3">
        <span className="text-[10.5px] font-bold uppercase tracking-[0.12em] text-tx-faint">Password</span>
        {pw ? (
          <span className="mono select-all rounded-[8px] border border-rim-hi bg-well px-2.5 py-1 text-[12px] text-tx-body">
            {pw}
          </span>
        ) : (
          <button
            type="button"
            disabled={busy || !data.hasSftpPassword}
            onClick={() => {
              setError(null);
              start(async () => {
                const r = await revealHostingSftpPassword(a.id);
                if (r.error) setError(r.error);
                else setPw(r.password ?? "");
              });
            }}
            className="inline-flex items-center gap-1.5 rounded-[9px] border border-rim-hi bg-[color-mix(in_srgb,var(--fg)_5%,transparent)] px-2.5 py-1 text-[11.5px] font-bold text-tx-body transition hover:border-[#8b5cff]/55 hover:text-tx disabled:opacity-50"
          >
            <Icon name="eye" size={11} tone="inherit" /> {busy ? "…" : "Reveal password"}
          </button>
        )}
        {!data.hasSftpPassword && (
          <span className="text-[11px] text-tx-faint">No password on record yet — the account is still being set up.</span>
        )}
        {error && <span className="text-[11px] text-rose-300">{error}</span>}
      </div>
    </Panel>
  );
}

function Field({ label, value, copy }: { label: string; value: string; copy?: boolean }) {
  return (
    <div className="flex min-w-0 flex-col gap-1 rounded-[11px] border border-rim-soft bg-well px-3 py-2">
      <span className="text-[9.5px] font-bold uppercase tracking-[0.13em] text-tx-faint">{label}</span>
      {copy ? (
        <CopyChip label={label} value={value} />
      ) : (
        <span className="mono truncate text-[12px] text-tx-body">{value}</span>
      )}
    </div>
  );
}

/* ── scoped logins ────────────────────────────────────────────────────── */

function ScopedLogins({ data, onRefresh }: { data: HostingPanelData; onRefresh: () => void }) {
  const a = data.account;
  const [scopes, setScopes] = useState<{ key: string; label: string; path: string }[]>([]);
  const [label, setLabel] = useState("");
  const [scope, setScope] = useState("account");
  const [readOnly, setReadOnly] = useState(false);
  const [busy, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [created, setCreated] = useState<{ username: string; password: string } | null>(null);
  const [removing, setRemoving] = useState<string | null>(null);

  useEffect(() => {
    listFtpScopes(a.id).then(setScopes).catch(() => setScopes([]));
  }, [a.id]);

  const users = data.ftpUsers;
  const full = users.filter((u) => u.status !== "DELETING").length >= MAX_FTP_USERS;
  const cleanLabel = label.trim().toLowerCase().replace(/[^a-z0-9-]/g, "").slice(0, 16);

  return (
    <Panel
      title="Extra logins"
      accent="#8b5cff"
      icon="usergear"
      ink="text-violet-300"
      fill={false}
      action={
        <span className="num text-[11.5px] font-bold text-tx-dim">
          {users.length} <span className="text-tx-faint">/ {MAX_FTP_USERS}</span>
        </span>
      }
    >
      <p className="mb-3 max-w-[80ch] text-[11.5px] leading-relaxed text-tx-faint">
        Give someone access to one website’s folder instead of your whole plan. Each login gets its own username and
        password, and the restriction is enforced by the server — a scoped login cannot list, read or write anything
        outside its folder, whatever client it uses.
      </p>

      {users.length === 0 ? (
        <p className="text-[12px] text-tx-faint">No extra logins yet.</p>
      ) : (
        <ul className="flex flex-col gap-2">
          {users.map((u) => (
            <LoginRow key={u.id} user={u} onRemove={() => setRemoving(u.id)} onRefresh={onRefresh} />
          ))}
        </ul>
      )}

      {created && (
        <div className="mt-3 rounded-[11px] border border-emerald-400/35 bg-emerald-500/[0.08] p-3">
          <p className="text-[11.5px] font-bold text-emerald-300">Login created — copy the password now</p>
          <p className="mt-1 text-[11.5px] text-tx-dim">
            Username <span className="mono text-tx-body">{created.username}</span> · password{" "}
            <span className="mono select-all text-tx-body">{created.password}</span>
          </p>
          <p className="mt-1 text-[10.5px] text-tx-faint">
            You can look this password up again later — it stays on record, encrypted, because an SFTP login has no
            other recovery path.
          </p>
        </div>
      )}

      {/* ── create ──────────────────────────────────────────────────── */}
      <div className="mt-3 border-t border-rim-soft pt-3">
        {full ? (
          <p className="text-[11.5px] text-tx-faint">
            You have the maximum of {MAX_FTP_USERS} extra logins on this plan. Remove one to add another.
          </p>
        ) : (
          <div className="flex flex-col gap-3">
            <div className="flex flex-wrap items-end gap-3">
              <label className="flex flex-col gap-1">
                <span className="text-[10.5px] font-bold uppercase tracking-[0.12em] text-tx-faint">Login name</span>
                <span className="flex items-center gap-1">
                  <span className="mono text-[12px] text-tx-faint">{a.username}_</span>
                  <input
                    value={label}
                    onChange={(e) => setLabel(e.target.value)}
                    placeholder="designer"
                    maxLength={16}
                    spellCheck={false}
                    className="input mono w-[150px]"
                  />
                </span>
              </label>

              <label className="flex flex-col gap-1">
                <span className="text-[10.5px] font-bold uppercase tracking-[0.12em] text-tx-faint">Can access</span>
                <select value={scope} onChange={(e) => setScope(e.target.value)} className="input w-[280px] text-[12.5px]">
                  {scopes.map((s) => (
                    <option key={s.key} value={s.key}>{s.label}</option>
                  ))}
                </select>
              </label>

              <label className="flex items-center gap-2 pb-2 text-[12px] text-tx-body">
                <input
                  type="checkbox"
                  checked={readOnly}
                  onChange={(e) => setReadOnly(e.target.checked)}
                  className="h-3.5 w-3.5 accent-[#8b5cff]"
                />
                Read-only
              </label>

              <button
                type="button"
                disabled={busy || cleanLabel.length < 1}
                onClick={() => {
                  setError(null);
                  setCreated(null);
                  start(async () => {
                    const r = await createFtpUser(a.id, cleanLabel, scope, readOnly);
                    if (r.error) { setError(r.error); return; }
                    setCreated({ username: r.username ?? "", password: r.password ?? "" });
                    setLabel("");
                    onRefresh();
                  });
                }}
                className="nx-cta mb-0.5 px-3.5 py-2 text-[12.5px] disabled:opacity-40"
              >
                {busy ? "Creating…" : "Create login"}
              </button>
            </div>

            <p className="max-w-[80ch] text-[11px] leading-relaxed text-tx-faint">
              {scope === "account"
                ? "This login will reach every website on the plan — the same as your own account login."
                : `This login lands in ${scopes.find((s) => s.key === scope)?.path || "the account home"} and cannot go above it.`}
              {readOnly && " It will be able to download files but not change them."}
            </p>
          </div>
        )}
        {error && <p className="mt-2 text-[12px] text-rose-300">{error}</p>}
      </div>

      <Confirm
        open={removing !== null}
        danger
        title="Remove this login?"
        body={<>The system user is deleted on the server and the password stops working immediately. Files are untouched.</>}
        confirmLabel="Remove login"
        onClose={() => setRemoving(null)}
        onConfirm={() => {
          const id = removing;
          if (!id) return;
          setError(null);
          start(async () => {
            const r = await deleteFtpUser(id);
            if (r.error) setError(r.error);
            else onRefresh();
          });
        }}
      />
    </Panel>
  );
}

function LoginRow({ user, onRemove, onRefresh }: {
  user: HostingPanelData["ftpUsers"][number];
  onRemove: () => void;
  onRefresh: () => void;
}) {
  const [pw, setPw] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [note, setNote] = useState<string | null>(null);
  const [busy, start] = useTransition();
  const st = ROW_STATUS[user.status] ?? ROW_STATUS.PENDING;
  const usable = user.status === "ACTIVE";

  return (
    <li className="flex flex-col gap-2 rounded-[12px] border border-rim-soft bg-well px-3 py-2.5">
      <div className="flex flex-wrap items-center gap-2.5">
        <Icon name="user" size={14} tone="inherit" className="flex-none text-[#b79bff]" />
        <span className="mono min-w-0 flex-1 truncate text-[12.5px] font-semibold text-tx-body">{user.username}</span>
        <span className="rounded-[6px] border border-rim-hi bg-[color-mix(in_srgb,var(--fg)_4%,transparent)] px-1.5 py-0.5 text-[10px] font-bold text-tx-dim">
          {user.scopeLabel}
        </span>
        {user.readOnly && (
          <span className="rounded-[6px] border border-sky-400/40 bg-sky-500/12 px-1.5 py-0.5 text-[10px] font-bold uppercase text-sky-300">
            Read-only
          </span>
        )}
        <StatusPill tone={st.tone} label={st.label} live={st.live} />
      </div>

      <div className="flex flex-wrap items-center gap-x-3 gap-y-1.5">
        <span className="mono text-[10.5px] text-tx-faint">
          {user.chrootPath ? `/${user.chrootPath}` : "/ (whole account)"}
        </span>
        {pw ? (
          <span className="mono select-all text-[11.5px] text-[#b79bff]">{pw}</span>
        ) : (
          <button
            type="button"
            disabled={busy}
            className="text-[11px] font-semibold text-brand-300 hover:text-tx disabled:opacity-50"
            onClick={() => {
              setError(null);
              start(async () => {
                const r = await revealFtpPassword(user.id);
                if (r.error) setError(r.error);
                else setPw(r.password ?? "");
              });
            }}
          >
            Show password
          </button>
        )}
        <button
          type="button"
          disabled={busy || !usable}
          className="text-[11px] font-semibold text-tx-faint hover:text-tx disabled:opacity-40"
          onClick={() => {
            setError(null);
            start(async () => {
              const r = await resetFtpPassword(user.id);
              if (r.error) setError(r.error);
              else { setPw(r.password ?? ""); setNote("New password set — live in a moment."); onRefresh(); }
            });
          }}
        >
          Reset password
        </button>
        <button
          type="button"
          disabled={busy || user.status === "DELETING"}
          onClick={onRemove}
          className="text-[11px] font-semibold text-rose-300 hover:text-rose-200 disabled:opacity-40"
        >
          Remove
        </button>
      </div>

      {user.status === "FAILED" && user.error && (
        <p className="text-[10.5px] text-rose-300">The server refused this login: {user.error}</p>
      )}
      {user.status === "PENDING" && (
        <p className="text-[10.5px] text-tx-faint">
          The folder restriction is being applied on the server. The password won’t work until this finishes.
        </p>
      )}
      {note && <p className="text-[10.5px] text-emerald-300">{note}</p>}
      {error && <p className="text-[10.5px] text-rose-300">{error}</p>}
    </li>
  );
}

