input.content:
"use client";

import { useEffect, useState, useTransition } from "react";
import { Icon } from "@/components/nx/Icon";
import { Panel, Confirm } from "@/components/customer/vpspanel/v2/kit";
import { SubNav, type SubSection } from "@/components/customer/vpspanel/v2/ui";
import { VpsStorageMeter } from "@/components/customer/vpspanel/v2/VpsStorageMeter";
import { fmtMoney } from "@/components/ui/primitives";
import {
  setHostingPhpVersion, listHostingUpgradePlans, upgradeHostingPlan,
  cancelHostingAccount, type UpgradePlanView,
} from "@/lib/actions-hosting";
import { quoteHostingStorage, expandHostingStorage, type StorageQuote } from "@/lib/actions-hosting-sites";
import { HostingAccessPanel } from "./HostingAccessPanel";
import type { HostingPanelData } from "./types";

/**
 * Settings — five separate things, in a rail, instead of one scroll.
 *
 * The brief asked for "organized/separated rather than one cluttered page", and
 * the old Settings tab was three stacked cards with the PHP dropdown, the plan's
 * limits, an upgrade list and a Cancel button all in the same column — with the
 * destructive action reachable by scrolling past a `<select>`.
 *
 * This is the arrangement GameSettingsShell established and VpsSettingsShell
 * follows: a 252px rail of named sections, the resource-growing ones first, the
 * irreversible one fenced at the end and coloured as such.
 *
 * ACCESS is in here, and that is the answer to "where are my FTP details". They
 * are a property of the plan, not of a website, and a customer looking for a
 * credential looks in settings — not halfway down an overview page, which is
 * where they used to be.
 */

type Section = "plan" | "storage" | "php" | "access" | "danger";

const SECTIONS: SubSection<Section>[] = [
  { key: "plan",    label: "Plan",        sub: "Move to a bigger plan",     icon: "bolt" },
  { key: "storage", label: "Storage",     sub: "Add space to this plan",    icon: "database" },
  { key: "php",     label: "PHP version", sub: "The runtime your sites use", icon: "cube" },
  { key: "access",  label: "Access",      sub: "SFTP logins and folders",   icon: "key" },
  { key: "danger",  label: "Cancel",      sub: "End this hosting plan",     icon: "trash", tone: "danger" },
];

export function HostingSettingsShell({ data, initial, onRefresh }: {
  data: HostingPanelData;
  initial?: string;
  onRefresh: () => void;
}) {
  const key = (SECTIONS.some((s) => s.key === initial) ? initial : "plan") as Section;
  return (
    <SubNav
      sections={SECTIONS}
      initial={key}
      slots={{
        plan: <PlanSection data={data} onRefresh={onRefresh} />,
        storage: <StorageSection data={data} onRefresh={onRefresh} />,
        php: <PhpSection data={data} onRefresh={onRefresh} />,
        access: <HostingAccessPanel data={data} onRefresh={onRefresh} />,
        danger: <DangerSection data={data} />,
      }}
    />
  );
}

/* ── plan ─────────────────────────────────────────────────────────────── */

function PlanSection({ data, onRefresh }: { data: HostingPanelData; onRefresh: () => void }) {
  const a = data.account;
  const [plans, setPlans] = useState<UpgradePlanView[] | null>(null);
  const [busy, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [confirming, setConfirming] = useState<UpgradePlanView | null>(null);

  useEffect(() => {
    listHostingUpgradePlans(a.id)
      .then((r) => setPlans(r.error ? [] : r.plans ?? []))
      .catch(() => setPlans([]));
  }, [a.id]);

  return (
    <>
      <Panel title="Your plan" accent="#8b5cff" icon="cloud" ink="text-violet-300" fill={false}>
        <div className="flex flex-wrap items-center gap-3">
          <span className="grid h-[42px] w-[42px] flex-none place-items-center overflow-hidden rounded-[12px] border border-rim-hi bg-well">
            {/* eslint-disable-next-line @next/next/no-img-element -- local product mark */}
            <img src="/nx/svc/hosting.webp" alt="" className="h-full w-full object-cover" />
          </span>
          <span className="flex min-w-0 flex-1 flex-col">
            <span className="text-[14px] font-extrabold text-tx">{a.planName}</span>
            <span className="num text-[11.5px] text-tx-dim">
              {fmtMoney(data.renewalCents)} {data.renewalTerm}
              {a.expiresAt && ` · renews ${new Date(a.expiresAt).toLocaleDateString()}`}
            </span>
          </span>
        </div>

        <dl className="mt-3 grid gap-2 border-t border-rim-soft pt-3 sm:grid-cols-2 xl:grid-cols-4">
          <Stat label="Websites" value={`${a.maxSites + 1}`} />
          <Stat label="Storage" value={`${Math.round(a.diskQuotaMB / 1024)} GB`} sub={data.extraDiskGB > 0 ? `incl. +${data.extraDiskGB} GB added` : undefined} />
          <Stat label="Databases" value={`${a.maxDatabases}`} />
          <Stat
            label="Mailboxes"
            value={data.mailboxesIncluded < 0 ? "Unlimited" : `${data.mailboxesIncluded}`}
          />
        </dl>
      </Panel>

      <Panel title="Move to a bigger plan" accent="#34d399" icon="bolt" ink="text-emerald-300" fill={false}>
        {plans === null ? (
          <p className="text-[12px] text-tx-faint">Loading options…</p>
        ) : plans.length === 0 ? (
          <p className="max-w-[72ch] text-[12.5px] leading-relaxed text-tx-dim">
            You’re on our largest hosting plan. If you’ve outgrown it, a VPS gives you the whole machine — more CPU,
            root access and no shared limits.
          </p>
        ) : (
          <>
            <p className="mb-3 max-w-[80ch] text-[11.5px] leading-relaxed text-tx-faint">
              Upgrades apply immediately and you’re charged only the price difference for the rest of your current term.
              Your renewal date doesn’t move. Downgrades aren’t self-service — they’d owe you money back, and that path
              doesn’t exist yet.
            </p>
            <ul className="flex flex-col gap-2">
              {plans.map((p) => (
                <li
                  key={p.id}
                  className="flex flex-wrap items-center gap-3 rounded-[12px] border border-rim-soft bg-well px-3.5 py-3"
                >
                  <span className="flex min-w-0 flex-1 flex-col">
                    <span className="text-[13px] font-extrabold text-tx">{p.name}</span>
                    <span className="text-[11.5px] text-tx-faint">
                      {p.diskGB} GB · {p.maxSites + 1} website{p.maxSites === 0 ? "" : "s"} · {p.maxDatabases} database
                      {p.maxDatabases === 1 ? "" : "s"} · {p.bandwidthTB} TB bandwidth
                      {p.tagline ? ` · ${p.tagline}` : ""}
                    </span>
                  </span>
                  <button
                    type="button"
                    disabled={busy}
                    onClick={() => setConfirming(p)}
                    className="nx-cta flex-none px-3.5 py-1.5 text-[12px] disabled:opacity-50"
                  >
                    Upgrade · +{fmtMoney(p.deltaCents)}
                  </button>
                </li>
              ))}
            </ul>
          </>
        )}
        {error && <p className="mt-2 text-[12px] text-rose-300">{error}</p>}
      </Panel>

      <Confirm
        open={confirming !== null}
        title={`Upgrade to ${confirming?.name ?? ""}?`}
        body={
          <>
            Your wallet is charged <span className="num font-bold text-tx">{fmtMoney(confirming?.deltaCents ?? 0)}</span>{" "}
            now — the price difference for this term. Your new limits apply within a moment, and future renewals bill at
            the new plan price.
          </>
        }
        confirmLabel="Upgrade plan"
        onClose={() => setConfirming(null)}
        onConfirm={() => {
          const p = confirming;
          if (!p) return;
          setError(null);
          start(async () => {
            const r = await upgradeHostingPlan(data.account.id, p.id);
            if (r.error) setError(r.error);
            else onRefresh();
          });
        }}
      />
    </>
  );
}

function Stat({ label, value, sub }: { label: string; value: string; sub?: string }) {
  return (
    <div className="rounded-[11px] border border-rim-soft bg-well px-3 py-2">
      <dt className="text-[9.5px] font-bold uppercase tracking-[0.13em] text-tx-faint">{label}</dt>
      <dd className="num mt-0.5 text-[15px] font-extrabold text-tx">{value}</dd>
      {sub && <p className="mt-0.5 text-[10px] text-tx-faint">{sub}</p>}
    </div>
  );
}

/* ── storage ──────────────────────────────────────────────────────────── */

function StorageSection({ data, onRefresh }: { data: HostingPanelData; onRefresh: () => void }) {
  const a = data.account;
  const [quote, setQuote] = useState<StorageQuote | null>(null);
  const [addGB, setAddGB] = useState(0);
  const [busy, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [done, setDone] = useState(false);
  const [confirming, setConfirming] = useState(false);

  useEffect(() => {
    quoteHostingStorage(a.id, 0)
      .then((q) => setQuote("error" in q ? null : q))
      .catch(() => setQuote(null));
  }, [a.id]);

  if (!quote) {
    return (
      <Panel title="Storage" accent="#3fbcd8" icon="database" ink="text-cyan-300" fill={false}>
        <p className="text-[12px] text-tx-faint">Loading…</p>
      </Panel>
    );
  }

  // The charge for the CURRENT slider position, computed with the same helpers
  // the action charges through — never a second formula beside the control.
  const monthlyCents = Math.round(addGB * quote.perGbCents);
  const prorate = Math.max(0, Math.round(monthlyCents * Math.max(0, quote.monthsRemaining)));

  return (
    <>
      <VpsStorageMeter
        planDiskGB={quote.planDiskGB}
        extraDiskGB={quote.extraDiskGB}
        perGbCents={quote.perGbCents}
        maxAddGB={quote.maxAddGB}
        addGB={addGB}
        onChange={setAddGB}
        prorateCents={prorate}
        disabled={busy || a.status !== "ACTIVE"}
        subtitle="applied to your account’s quota within a moment"
        atMaxNote={`This plan is at the maximum storage we can attach (${quote.effectiveGB} GB). A VPS is the next step up — it gives you the whole machine and a disk you size yourself.`}
      />

      {quote.maxAddGB > 0 && (
        <Panel title="Confirm" accent="#34d399" icon="card" ink="text-emerald-300" fill={false}>
          <div className="flex flex-wrap items-center justify-between gap-3">
            <div className="min-w-0">
              <p className="text-[12.5px] text-tx-dim">
                {addGB === 0 ? (
                  "Move the slider to choose how much to add."
                ) : (
                  <>
                    Adding <span className="num font-bold text-tx">{addGB} GB</span> — due now{" "}
                    <span className="num font-bold text-tx">{fmtMoney(prorate)}</span>, then{" "}
                    <span className="num font-bold text-tx">{fmtMoney(monthlyCents)}/mo</span> on every renewal.
                  </>
                )}
              </p>
              <p className="num mt-1 text-[11px] text-tx-faint">
                Wallet balance {fmtMoney(quote.walletCents)}
                {addGB > 0 && quote.walletCents < prorate && (
                  <span className="ml-1 text-amber-300">— top up before you can add this</span>
                )}
              </p>
            </div>
            <button
              type="button"
              disabled={busy || addGB === 0 || a.status !== "ACTIVE"}
              onClick={() => setConfirming(true)}
              className="nx-cta flex-none px-4 py-2 text-[12.5px] disabled:opacity-40"
            >
              {busy ? "Adding…" : "Add storage"}
            </button>
          </div>
          {error && <p className="mt-2 text-[12px] text-rose-300">{error}</p>}
          {done && <p className="mt-2 text-[12px] text-emerald-300">Storage added — your new quota is being applied on the server.</p>}
        </Panel>
      )}

      <Confirm
        open={confirming}
        title={`Add ${addGB} GB of storage?`}
        body={
          <>
            <span className="num font-bold text-tx">{fmtMoney(prorate)}</span> is taken from your wallet now for the rest
            of this term, and <span className="num font-bold text-tx">{fmtMoney(monthlyCents)}</span> is added to every
            renewal from here on. Storage can be added but never removed.
          </>
        }
        confirmLabel="Add storage"
        onClose={() => setConfirming(false)}
        onConfirm={() => {
          setError(null);
          setDone(false);
          start(async () => {
            const r = await expandHostingStorage(a.id, addGB);
            if (r.error) { setError(r.error); return; }
            setDone(true);
            setAddGB(0);
            const q = await quoteHostingStorage(a.id, 0).catch(() => null);
            if (q && !("error" in q)) setQuote(q);
            onRefresh();
          });
        }}
      />
    </>
  );
}

/* ── php ──────────────────────────────────────────────────────────────── */

function PhpSection({ data, onRefresh }: { data: HostingPanelData; onRefresh: () => void }) {
  const a = data.account;
  const [busy, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [note, setNote] = useState<string | null>(null);
  const [pick, setPick] = useState<string | null>(null);

  return (
    <>
      <Panel title="PHP version" accent="#8b5cff" icon="cube" ink="text-violet-300" fill={false}>
        <p className="mb-3 max-w-[80ch] text-[11.5px] leading-relaxed text-tx-faint">
          Every website on this plan runs in one PHP pool, so this applies to all of them at once. The switch takes a
          moment and no files are touched — but an app that isn’t ready for a newer PHP can stop rendering, so take a
          backup first if you are stepping up a major version.
        </p>

        <div className="flex flex-wrap gap-2">
          {a.phpVersions.map((v) => {
            const on = v === a.phpVersion;
            return (
              <button
                key={v}
                type="button"
                disabled={busy || a.status !== "ACTIVE" || on}
                onClick={() => setPick(v)}
                className={
                  "mono rounded-[11px] border px-4 py-2.5 text-[13px] font-bold transition disabled:cursor-default " +
                  (on
                    ? "border-[#8b5cff]/70 bg-[linear-gradient(120deg,rgba(80,40,190,.4),rgba(30,44,130,.3))] text-[#fff]"
                    : "border-rim-hi bg-well text-tx-body hover:border-[#8b5cff]/50 hover:text-tx disabled:opacity-50")
                }
              >
                PHP {v}
                {on && <span className="ml-2 text-[10px] font-bold uppercase tracking-wide opacity-80">current</span>}
              </button>
            );
          })}
        </div>

        {error && <p className="mt-3 text-[12px] text-rose-300">{error}</p>}
        {note && <p className="mt-3 text-[12px] text-emerald-300">{note}</p>}
      </Panel>

      <Confirm
        open={pick !== null}
        title={`Switch to PHP ${pick}?`}
        body={
          <>
            Every website on this plan moves to PHP {pick} within a moment. If a site breaks, switch back here — nothing
            is deleted, and the change is immediate in both directions.
          </>
        }
        confirmLabel={`Switch to PHP ${pick}`}
        onClose={() => setPick(null)}
        onConfirm={() => {
          const v = pick;
          if (!v) return;
          setError(null); setNote(null);
          start(async () => {
            const r = await setHostingPhpVersion(a.id, v);
            if (r.error) setError(r.error);
            else { setNote(`Switching to PHP ${v} — it applies within a moment.`); onRefresh(); }
          });
        }}
      />
    </>
  );
}

/* ── cancel ───────────────────────────────────────────────────────────── */

function DangerSection({ data }: { data: HostingPanelData }) {
  const a = data.account;
  const [open, setOpen] = useState(false);
  const [busy, start] = useTransition();
  const [error, setError] = useState<string | null>(null);

  return (
    <>
      <Panel title="Cancel this hosting plan" accent="#f43f5e" icon="warntriangle" ink="text-rose-300" fill={false}>
        <p className="max-w-[80ch] text-[12.5px] leading-relaxed text-tx-dim">
          Cancelling removes <span className="mono text-tx">{a.primaryDomain}</span> and{" "}
          <span className="font-semibold text-tx">every website on this plan</span> — all{" "}
          {data.sites.length} of them — along with their files, all {data.databases.length} database
          {data.databases.length === 1 ? "" : "s"}, and every backup. It cannot be undone and there is no copy
          afterwards.
        </p>

        <ul className="mt-3 flex flex-col gap-1.5">
          {data.sites.map((s) => (
            <li key={s.key} className="flex items-center gap-2 text-[11.5px] text-tx-faint">
              <Icon name="warncircle" size={11} tone="inherit" className="flex-none text-rose-400/70" />
              <span className="mono truncate">{s.hostname}</span>
            </li>
          ))}
        </ul>

        <div className="mt-4 rounded-[11px] border border-amber-400/30 bg-amber-500/[0.07] p-3">
          <p className="text-[11.5px] leading-relaxed text-tx-dim">
            Want your files first? Take a backup and open a ticket — we can get the archive to you. Once the plan is
            cancelled there is nothing left to send.
          </p>
        </div>

        <button
          type="button"
          onClick={() => setOpen(true)}
          className="mt-4 inline-flex items-center gap-1.5 rounded-[10px] border border-rose-400/45 px-3.5 py-2 text-[12.5px] font-bold text-rose-300 transition hover:bg-rose-500/10"
        >
          <Icon name="trash" size={13} tone="inherit" /> Cancel hosting plan
        </button>
        {error && <p className="mt-2 text-[12px] text-rose-300">{error}</p>}
      </Panel>

      <Confirm
        open={open}
        danger
        typeToConfirm={a.primaryDomain}
        title="Cancel this hosting plan?"
        body={
          <>
            Every website, file, database and backup on this plan is permanently removed. There is no recovery and no
            copy kept.
          </>
        }
        confirmLabel="Cancel the plan"
        onClose={() => setOpen(false)}
        onConfirm={() => {
          setError(null);
          start(async () => {
            const r = await cancelHostingAccount(a.id);
            if (r.error) { setError(r.error); return; }
            window.location.href = "/dashboard/hosting";
          });
        }}
      />
    </>
  );
}

import { notFound } from "next/navigation";
import {
  getHostingAccount, listWebsites, listHostingDatabases, listHostingBackups, listHostingAppMenu,
} from "@/lib/actions-hosting";
import {
  listSiteThumbs, listFtpUsers, hostingStorageBreakdown, listHostingActivity,
} from "@/lib/actions-hosting-sites";
import { db } from "@/lib/db";
import { termPriceCents } from "@/lib/billing-terms";
import { hostingProvisioningStep } from "@/lib/provisioning-step";
import { AutoRefresh } from "@/components/AutoRefresh";
import { Provisioning } from "@/components/nx/Provisioning";
import { HostingPanelShell } from "@/components/customer/hosting/v2/HostingPanelShell";
import type { HostingPanelData, HostingSiteCard } from "@/components/customer/hosting/v2/types";

export const dynamic = "force-dynamic";

/** "/ month", "/ year", "/ 2 years" — the unit the renewal actually bills on. */
function termLabel(months: number): string {
  if (months === 1) return "/ month";
  if (months % 12 === 0) return months === 12 ? "/ year" : `/ ${months / 12} years`;
  return `/ ${months} mo`;
}

/**
 * One shared-hosting plan.
 *
 * Everything the panel renders is resolved HERE, once, and threaded down — the
 * old page handed a single `account` to a client tab shell that then re-fetched
 * the same counts from four different components on four different timers, which
 * is how its Overview came to disagree with its own Websites tab.
 *
 * The provisioning overlay is unchanged: it is the same `<Provisioning/>` the VPS
 * and game flows use, driven by the same real signals (account status plus
 * `hostingProvisioningStep`, which reads the worker's own per-command-group
 * label and any content task still running).
 */
export default async function HostingAccountPage({
  params,
  searchParams,
}: {
  params: Promise<{ id: string }>;
  searchParams: Promise<{ tab?: string; path?: string; site?: string; section?: string }>;
}) {
  const [{ id }, { tab, path, site, section }] = await Promise.all([params, searchParams]);

  // getHostingAccount enforces owner-or-admin (throws) and returns null if missing.
  let account: Awaited<ReturnType<typeof getHostingAccount>> = null;
  try {
    account = await getHostingAccount(id);
  } catch {
    notFound();
  }
  if (!account) notFound();

  const transitional = account.status === "PENDING" || account.status === "PROVISIONING";

  const [raw, stepLabel, sites, thumbs, dbs, backups, appMenu, ftpUsers, storage, activity, upgradePlanCount] =
    await Promise.all([
      // A second, narrower lookup for the raw fields HostingAccountView doesn't
      // carry: whether an SFTP credential exists at all (never the secret itself —
      // that only ever leaves through the ownership-checked reveal action), and
      // the node's REAL ssh host/port, which is what a customer's SFTP client
      // must connect to and can differ from the public A-record target on NAT.
      db.hostingAccount.findUnique({
        where: { id: account.id },
        select: {
          sftpPasswordEnc: true,
          plan: { select: { bandwidthTB: true, mailboxes: true } },
          node: { select: { sshHost: true, sshPort: true, publicIp: true, hostnameFqdn: true } },
        },
      }),
      hostingProvisioningStep(account.id),
      listWebsites(account.id).catch(() => []),
      listSiteThumbs(account.id).catch(() => []),
      listHostingDatabases(account.id).catch(() => []),
      listHostingBackups(account.id).catch(() => []),
      listHostingAppMenu().catch(() => []),
      listFtpUsers(account.id).catch(() => []),
      hostingStorageBreakdown(account.id).catch(() => null),
      listHostingActivity(account.id, 24).catch(() => []),
      db.hostingPlan.count({
        where: { active: true, priceCents: { gt: account.planPriceCents } },
      }).catch(() => 0),
    ]);

  // The `siteKey` association lives on the row but isn't on HostingDbView — read
  // it alongside so the per-website Database section can name its database.
  const dbSiteKeys = await db.hostingDatabase
    .findMany({ where: { accountId: account.id }, select: { id: true, siteKey: true } })
    .catch(() => [] as { id: string; siteKey: string | null }[]);
  const siteKeyById = new Map(dbSiteKeys.map((d) => [d.id, d.siteKey]));

  // Real mailbox count for the plan's domain — only meaningful once the bundled
  // subscription exists. No subscription means there is nothing to count, which
  // is not the same as a count of zero, so it stays null and the tile says why.
  const emailSub = await db.emailSubscription
    .findFirst({
      where: { domainName: account.primaryDomain, status: { not: "CANCELLED" } },
      select: { id: true, _count: { select: { mailboxes: true } } },
    })
