  const lastBackup = backups[0] ?? null;
  const installStepActive = account.status === "ACTIVE" && stepLabel !== null;

  const data: HostingPanelData = {
    account,
    sites: siteCards,
    sftpHost: raw?.node?.sshHost || raw?.node?.hostnameFqdn || raw?.node?.publicIp || null,
    sftpPort: raw?.node?.sshPort ?? 22,
    hasSftpPassword: !!raw?.sftpPasswordEnc,
    mailboxesUsed: emailSub ? emailSub._count.mailboxes : null,
    emailReady: !!emailSub,
    mailboxesIncluded: raw?.plan?.mailboxes ?? account.planMailboxes,
    bandwidthTB: raw?.plan?.bandwidthTB ?? 0,
    databases: dbs.map((d) => ({ ...d, siteKey: siteKeyById.get(d.id) ?? null })),
    databasesUsed: dbs.length,
    appMenu,
    ftpUsers,
    backupCount: backups.length,
    lastBackupAt: lastBackup?.createdAt ?? null,
    lastBackupBytes: lastBackup?.sizeBytes ?? null,
    storage: storage && !("error" in storage) ? storage : null,
    activity,
    // The charge the renewal sweep actually takes, on the term this account was
    // SOLD on — never plan.priceCents, which is the monthly rate.
    renewalCents: termPriceCents(account.planPriceCents, account.termMonths, account.annualDiscountPct ?? undefined),
    renewalTerm: termLabel(account.termMonths),
    extraDiskGB: account.extraDiskGB,
    canUpgrade: upgradePlanCount > 0,
  };

  const sftpAddress = data.sftpHost ? `sftp://${account.username}@${data.sftpHost}` : null;

  return (
    <div>
      <Provisioning
        phase={account.status === "ERROR" || account.status === "FAILED" ? "error" : transitional ? "working" : "ready"}
        liveStep={stepLabel}
        simulate={process.env.NXEON_SANDBOX === "1" && !stepLabel}
        service="hosting"
        hostname={account.primaryDomain}
        planName={account.planName}
        osName=""
        connectAddress={sftpAddress}
        error={account.error}
        dashboardHref={`/dashboard/hosting/${account.id}`}
        specs={[
          { icon: "database", text: `${Math.round(account.diskQuotaMB / 1024)} GB storage` },
          { icon: "globe3", text: `${account.maxSites + 1} website${account.maxSites === 0 ? "" : "s"}` },
          {
            icon: "envelope",
            text: data.mailboxesIncluded < 0 ? "Unlimited mailboxes" : `${data.mailboxesIncluded} mailboxes`,
          },
        ]}
      />
      {(transitional || installStepActive) && <AutoRefresh />}

      <HostingPanelShell
        data={data}
        initialTab={tab}
        initialSite={site}
        initialPath={path}
        initialSection={section}
      />
    </div>
  );
