/**
 * Sandbox demo data for the shared-hosting panel.
 *
 * NODE-2 SANDBOX ONLY. It refuses to run unless NXEON_SANDBOX=1, because every
 * row it writes is a lie about a machine — an ACTIVE account with measured disk
 * usage on a node that does not exist. That is fine for looking at a design and
 * catastrophic anywhere else.
 *
 * Why it exists: the hosting panel's whole surface (websites, storage
 * breakdown, HTTPS state, databases, activity) is gated on
 * `status === "ACTIVE"`, and every seeded account on node-2 sits at PENDING
 * because nothing ever provisions them here. Without this there is nothing to
 * screenshot but an empty "still being set up" card.
 *
 *   NXEON_SANDBOX=1 npx tsx scripts/seed-hosting-demo.ts
 */
import { PrismaClient } from "@prisma/client";
import { encryptSecret } from "../lib/crypto-box";

const db = new PrismaClient();

async function main() {
  if (process.env.NXEON_SANDBOX !== "1") {
    throw new Error("Refusing to run: this writes fake measurements and is sandbox-only. Set NXEON_SANDBOX=1.");
  }

  const account = await db.hostingAccount.findFirst({
    where: { user: { email: "customer@nxeon.local" } },
    orderBy: { createdAt: "asc" },
    include: { plan: true },
  });
  if (!account) throw new Error("No hosting account for customer@nxeon.local — order one first.");

  const business = await db.hostingPlan.findUnique({ where: { slug: "business" } });
  if (!business) throw new Error("No 'business' hosting plan seeded.");

  const quotaMB = business.diskGB * 1024;
  await db.hostingAccount.update({
    where: { id: account.id },
    data: {
      planId: business.id,
      status: "ACTIVE",
      maxSites: business.maxSites,
      maxDatabases: business.maxDatabases,
      diskQuotaMB: quotaMB,
      phpVersion: "8.3",
      sslActive: true,
      serveHttpOk: true,
      serveHttpsOk: true,
      healthNote: "HTTPS live — verified",
      healthCheckedAt: new Date(),
      diskUsedMB: 5_640,
      inodesUsed: 41_233,
      usageAt: new Date(),
      usageBreakdown: JSON.stringify({
        v: 1,
        dirs: [
          { path: "public_html", mb: 3120 },
          { path: "subdomains/shop", mb: 1180 },
          { path: "domains/nxeon-demo.example", mb: 890 },
          { path: "tmp", mb: 310 },
          { path: "logs", mb: 96 },
        ],
      }),
      sftpPasswordEnc: encryptSecret("sandbox-demo-sftp-pw"),
      provisionedAt: new Date(),
      expiresAt: new Date(Date.now() + 23 * 86_400_000),
    },
  });

  // Two more websites, so the plan/website distinction is actually visible.
  const subFqdn = `shop.${account.primaryDomain}`;
  await db.hostingSubdomain.upsert({
    where: { fqdn: subFqdn },
    create: {
      accountId: account.id, label: "shop", fqdn: subFqdn,
      docroot: `/home/${account.username}/subdomains/shop/public_html`,
      sslActive: true, status: "ACTIVE",
    },
    update: { accountId: account.id, sslActive: true, status: "ACTIVE" },
  });
  await db.hostingAddonDomain.upsert({
    where: { domain: "nxeon-demo.example" },
    create: {
      accountId: account.id, domain: "nxeon-demo.example",
      docroot: `/home/${account.username}/domains/nxeon-demo.example/public_html`,
      sslActive: false, status: "ACTIVE",
    },
    update: { accountId: account.id, status: "ACTIVE" },
  });

  // Databases, one assigned to a website and one not.
  const sub = await db.hostingSubdomain.findUnique({ where: { fqdn: subFqdn } });
  for (const [slug, siteKey] of [["wp", "primary"], ["shop", sub ? `subdomain:${sub.id}` : null]] as const) {
    const name = `${account.username}_${slug}`;
    await db.hostingDatabase.upsert({
      where: { accountId_name: { accountId: account.id, name } },
      create: {
        accountId: account.id, name, dbUser: name.slice(0, 32),
        passwordEnc: encryptSecret(`sandbox-demo-${slug}`), status: "ACTIVE", siteKey,
      },
      update: { status: "ACTIVE", siteKey },
    });
  }

  // A finished WordPress install on the primary site, so the app mark, the app
  // credential card and the "nothing installed" states all have something real
  // to read. Same payload/result shape the sandbox task sweep writes.
  const existing = await db.hostingTask.findFirst({
    where: { accountId: account.id, kind: "WORDPRESS_INSTALL", status: "DONE" },
  });
  if (!existing) {
    await db.hostingTask.create({
      data: {
        accountId: account.id,
        kind: "WORDPRESS_INSTALL",
        status: "DONE",
        payload: JSON.stringify({ target: { kind: "primary" } }),
        result: JSON.stringify({
          app: "WordPress", adminUser: "admin", adminPassword: "sandbox-demo-pw",
          url: `https://${account.primaryDomain}/wp-admin/`,
        }),
      },
    });
    await db.hostingTask.create({
      data: { accountId: account.id, kind: "ENSURE_DBMGR", status: "DONE" },
    });
    await db.hostingTask.create({
      data: { accountId: account.id, kind: "CREATE_SUBDOMAIN", status: "DONE", payload: JSON.stringify({}) },
    });
  }

  await db.hostingAccount.update({ where: { id: account.id }, data: { dbMgrReady: true } });

  console.log(`Seeded ${account.primaryDomain} (${account.id}) as an ACTIVE Business plan with 3 websites.`);
}

main()
  .catch((e) => { console.error(e); process.exitCode = 1; })
  .finally(() => db.$disconnect());

