1	"use server";
2	
3	// Proprietary in-portal DB manager — server actions.
4	//
5	// A Nxeon-built replacement for the Adminer file we used to drop into the
6	// customer's webroot. Everything here runs SERVER-SIDE: the customer never
7	// receives a DB credential, and every query is executed as the account's SCOPED
8	// MySQL manager user (see lib/hosting-db.ts + buildDbMgrGrantSql), which MySQL
9	// confines to this account's own `<username>_*` databases and nothing else.
10	//
11	// AUTH: every action requires the authenticated OWNER of the account (or an
12	// ADMIN). Actions that RUN SQL or reveal row data additionally call
13	// assertNotImpersonating — an admin impersonating a customer must not read or
14	// mutate that customer's live data (same discipline as revealHostingSftpPassword
15	// / createHostingDatabase). Read-only "which databases exist" listing (from OUR
16	// portal tables, not the node) is owner-or-admin without that extra bar.
17	
18	import { randomBytes } from "node:crypto";
19	import { revalidatePath } from "next/cache";
20	import { db } from "./db";
21	import { requireUser, assertNotImpersonating } from "./auth";
22	import { SANDBOX } from "./sandbox";
23	import { encryptSecret } from "./crypto-box";
24	import { checkRateLimit } from "./rate-limit";
25	import { isValidUnixUsername, isValidDbIdentifier, dbMgrUserFor } from "./hosting";
26	import {
27	  dbTargetFor,
28	  runScopedSql,
29	  showTablesSql,
30	  browseTableSql,
31	  filteredBrowseSql,
32	  countTableSql,
33	  countFilteredSql,
34	  tableCountsSql,
35	  overviewSql,
36	  showFullColumnsSql,
37	  showIndexSql,
38	  showCreateTableSql,
39	  dumpSelectSql,
40	  insertRowSql,
41	  updateRowSql,
42	  deleteRowSql,
43	  dumpValueLiteral,
44	  toCsv,
45	  truncateTableSql,
46	  dropTableSql,
47	  renameTableSql,
48	  maintainTableSql,
49	  addColumnSql,
50	  dropColumnSql,
51	  addIndexSql,
52	  dropIndexSql,
53	  normalizeColumnType,
54	  isSimpleIdent,
55	  splitSqlStatements,
56	  MAX_IMPORT_STATEMENTS,
57	  quoteIdent,
58	  isPlausibleTableName,
59	  clampPageSize,
60	  MAX_SQL_BYTES,
61	  BROWSE_PAGE_SIZE,
62	  type QueryResult,
63	  type DbNodeTarget,
64	} from "./hosting-db";
65	
66	export type DbMgrStatus = {
67	  ready: boolean;
68	  provisioning: boolean;
69	  enabled: boolean;
70	  /**
71	   * True when there is no hosting node behind this — the sandbox branches below
72	   * answer every query from a fixed in-memory table set. The UI MUST say so:
73	   * without it the Studio draws confident row counts and byte sizes for tables
74	   * that do not exist, which is exactly the shape this tree's honesty rule
75	   * forbids. It is never true in production (SANDBOX is unset there).
76	   */
77	  sandbox?: boolean;
78	};
79	export type DbMgrDatabase = { name: string; status: string };
80	export type DbMgrResult = {
81	  columns: string[];
82	  rows: string[][];
83	  truncated: boolean;
84	  error: string | null;
85	  elapsedMs: number;
86	  /** For non-SELECT statements (empty result set) — a friendly "OK" note. */
87	  ok?: boolean;
88	};
89	
90	export type DbMgrColumn = {
91	  name: string;
92	  type: string;
93	  nullable: boolean;
94	  key: string;      // "PRI" | "UNI" | "MUL" | ""
95	  default: string | null;
96	  extra: string;    // e.g. "auto_increment"
97	  comment: string;
98	  /** SHOW FULL COLUMNS' Collation, or "" for a non-text column. Read from the
99	   *  result's third field — it was never read at all before, while the Structure
100	   *  tab drew a column HEADED "Collation" and filled it with `comment`, so every
101	   *  text column was reported as having no collation. */
102	  collation: string;
103	};
104	export type DbMgrIndex = { name: string; columns: string[]; unique: boolean };
105	export type DbMgrStructure = {
106	  columns: DbMgrColumn[];
107	  indexes: DbMgrIndex[];
108	  /** Column names of the PRIMARY KEY (empty when the table has none). */
109	  primaryKey: string[];
110	};
111	/** A value the row editor sends us: a string, or null for SQL NULL. */
112	export type DbCellValue = string | null;
113	
114	/** Owner-or-admin account load with the node relation + manager fields. */
115	async function loadOwned(accountId: string) {
116	  const user = await requireUser();
117	  const a = await db.hostingAccount.findUnique({
118	    where: { id: accountId },
119	    include: { node: { select: { sshHost: true, sshPort: true, rootPasswordEnc: true } } },
120	  });
121	  if (!a) return { error: "Account not found." as const };
122	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." as const };
123	  if (a.status !== "ACTIVE") return { error: "The account is still being set up." as const };
124	  return { user, a };
125	}
126	
127	/** Confirm a target db name actually belongs to THIS account (defence in depth
128	 *  on top of the MySQL grant). Returns the matched row or null. */
129	async function assertOwnedDatabase(accountId: string, dbName: string) {
130	  if (!isValidDbIdentifier(dbName)) return null;
131	  return db.hostingDatabase.findFirst({ where: { accountId, name: dbName } });
132	}
133	
134	/** A short, alphanumeric (shell/SQL-safe) secret. */
135	function newSecret(len = 24): string {
136	  return randomBytes(48).toString("base64url").replace(/[^A-Za-z0-9]/g, "").slice(0, len);
137	}
138	
139	/**
140	 * Make sure the account has a provisioned DB-manager user. Idempotent:
141	 *   - already ready → { ready:true }
142	 *   - has creds but no ACTIVE user yet (or first call) → generate creds if
143	 *     missing, queue ENSURE_DBMGR, report { provisioning:true }
144	 * Owner-or-admin + not-impersonating (this mints a live DB credential on the box).
145	 * SANDBOX: mark ready immediately (no real node).
146	 */
147	export async function ensureDbManager(accountId: string): Promise<DbMgrStatus & { error?: string }> {
148	  const ctx = await loadOwned(accountId);
149	  if ("error" in ctx) return { ready: false, provisioning: false, enabled: false, error: ctx.error };
150	  await assertNotImpersonating();
151	  const { a } = ctx;
152	  if (!isValidUnixUsername(a.username)) return { ready: false, provisioning: false, enabled: false, error: "Account not ready." };
153	
154	  if (SANDBOX) {
155	    if (!a.dbMgrReady) {
156	      await db.hostingAccount.update({
157	        where: { id: a.id },
158	        data: { dbMgrUser: dbMgrUserFor(a.username), dbMgrPassEnc: encryptSecret(newSecret()), dbMgrReady: true },
159	      });
160	    }
161	    return { ready: true, provisioning: false, enabled: true };
162	  }
163	
164	  if (a.dbMgrReady && a.dbMgrUser && a.dbMgrPassEnc) return { ready: true, provisioning: false, enabled: true };
165	
166	  // Generate + persist the manager credential once (encrypted at rest); the
167	  // worker applies it on the node. Keep the same password across re-queues so the
168	  // stored cred always matches what the node was told.
169	  if (!a.dbMgrUser || !a.dbMgrPassEnc) {
170	    await db.hostingAccount.update({
171	      where: { id: a.id },
172	      data: { dbMgrUser: dbMgrUserFor(a.username), dbMgrPassEnc: encryptSecret(newSecret()), dbMgrReady: false },
173	    });
174	  }
175	  const inFlight = await db.hostingTask.findFirst({ where: { accountId, kind: "ENSURE_DBMGR", status: { in: ["PENDING", "RUNNING"] } } });
176	  if (!inFlight) await db.hostingTask.create({ data: { accountId, kind: "ENSURE_DBMGR" } });
177	  revalidatePath(`/dashboard/hosting/${accountId}`);
178	  return { ready: false, provisioning: true, enabled: true };
179	}
180	
181	export async function dbmgrStatus(accountId: string): Promise<DbMgrStatus & { error?: string }> {
182	  const ctx = await loadOwned(accountId);
183	  if ("error" in ctx) return { ready: false, provisioning: false, enabled: false, error: ctx.error };
184	  const { a } = ctx;
185	  if (SANDBOX) return { ready: !!a.dbMgrReady, provisioning: false, enabled: true, sandbox: true };
186	  const provisioning = !a.dbMgrReady && !!(await db.hostingTask.findFirst({ where: { accountId, kind: "ENSURE_DBMGR", status: { in: ["PENDING", "RUNNING"] } } }));
187	  return { ready: !!a.dbMgrReady, provisioning, enabled: true };
188	}
