/** One connection field. The label is the CARD's, not the chip's — nesting a
 *  CopyChip (which prints its own label) inside a labelled box printed "HOST
 *  HOST 192.0.2.10". The copy affordance is a bare icon button instead. */
function Field({ label, value, copy }: { label: string; value: string; copy?: boolean }) {
  const [done, setDone] = useState(false);
  return (
    <div className="flex min-w-0 flex-col gap-1 rounded-[11px] border border-rim-soft bg-well px-3 py-2">
      <span className="text-[9.5px] font-bold uppercase tracking-[0.13em] text-tx-faint">{label}</span>
      <span className="flex min-w-0 items-center gap-2">
        <span className="mono min-w-0 flex-1 truncate text-[12px] text-tx-body" title={value}>{value}</span>
        {copy && (
          <button
            type="button"
            title={`Copy ${label.toLowerCase()}`}
            onClick={async () => {
              try {
                await navigator.clipboard.writeText(value);
                setDone(true);
                setTimeout(() => setDone(false), 1300);
              } catch { /* insecure origin or denied — the text is selectable */ }
            }}
            className="flex-none text-tx-faint transition hover:text-tx"
          >
            <Icon name={done ? "checkcircle" : "copy"} size={12} tone="inherit" className={done ? "text-emerald-300" : ""} />
          </button>
        )}
      </span>
    </div>
  );
}

