// Temporary: drive the hosting v2 panel's NEW write paths through the real UI,
// so the server actions are exercised rather than asserted about.
import { chromium } from "playwright";
import { mkdirSync } from "node:fs";
import { join } from "node:path";

const BASE = process.env.BASE_URL || "https://v2.q4w8zt3ky6vn2sm.nxeon.cloud";
const EMAIL = process.env.NX_EMAIL || "customer@nxeon.local";
const PASS = process.env.NX_PASS || "wGPZqhCbsLdz";
const [out, id] = process.argv.slice(2);
mkdirSync(out, { recursive: true });

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1600, height: 1100 } });
const page = await ctx.newPage();
page.on("pageerror", (e) => console.log("PAGEERROR:", String(e).split("\n")[0]));

await page.goto(`${BASE}/login`, { waitUntil: "domcontentloaded" });
await page.getByRole("button", { name: /got it/i }).click({ timeout: 5000 }).catch(() => {});
await page.fill('input[type="email"]', EMAIL);
await page.fill('input[type="password"]', PASS);
await page.getByRole("button", { name: /^sign in$/i }).click();
await page.waitForURL((u) => !u.pathname.includes("/login"), { timeout: 45000 }).catch(() => {});
await page.waitForTimeout(2000);
if (page.url().includes("/login")) { await page.getByRole("button", { name: /^sign in$/i }).click().catch(() => {}); await page.waitForTimeout(4000); }
console.log("logged in:", page.url());

// ── 1. create a folder-scoped SFTP login ────────────────────────────────
await page.goto(`${BASE}/dashboard/hosting/${id}?tab=settings&section=access`, { waitUntil: "networkidle" });
await page.waitForTimeout(1500);
await page.fill('input[placeholder="designer"]', "designer");
// Scope it to the subdomain, not the whole account — the point of the feature.
const scope = page.locator("select").first();
const opts = await scope.locator("option").allTextContents();
console.log("scopes offered:", opts);
const shop = opts.find((o) => o.startsWith("shop."));
if (shop) await scope.selectOption({ label: shop });
await page.getByRole("button", { name: /create login/i }).click();
await page.waitForTimeout(4000);
await page.screenshot({ path: join(out, "drive-ftp-created.png"), fullPage: true });
console.log("ftp create done");

// ── 2. request a real screenshot capture of the main site ───────────────
await page.goto(`${BASE}/dashboard/hosting/${id}`, { waitUntil: "networkidle" });
await page.waitForTimeout(1500);
await page.locator('button[title*="Take a fresh screenshot"]').first().click().catch((e) => console.log("capture click:", String(e).split("\n")[0]));
await page.waitForTimeout(3000);
await page.screenshot({ path: join(out, "drive-capture-queued.png"), fullPage: true });
console.log("capture queued");

await browser.close();

