 * A HYPHEN, not an underscore. Debian's default `NAME_REGEX` for adduser is
 * `^[a-z][-a-z0-9]*$` — an underscore is refused outright there, and shadow's
 * `useradd` only tolerates one with `--badname`. A hyphen is accepted by both and
 * is equally shell-inert. (Found the hard way: the first version generated
 * `acct_designer`, which `isValidUnixUsername` refused before it ever reached a
 * node, so no login could be created at all.)
 */
export function ftpUsernameFor(accountUsername: string, label: string): string {
  return `${accountUsername}-${label}`.slice(0, 32);
}

/**
 * Validator for those derived names specifically.
 *
 * `isValidUnixUsername` (lib/hosting.ts) is deliberately stricter than Linux —
 * `^[a-z][a-z0-9]{2,31}$`, no separators at all — because it guards the ACCOUNT
 * username, which is interpolated into shell commands and filesystem paths all
 * over the provisioner. Loosening it to admit a scoped login's hyphen would widen
 * every one of those call sites at once, so this is a second, narrower validator
 * for exactly this one shape instead: an account name, one hyphen, a label.
 */
const FTP_USER_RE = /^[a-z][a-z0-9]{1,20}-[a-z0-9](?:[a-z0-9-]{0,13}[a-z0-9])?$/;

export function isValidFtpUsername(name: string): boolean {
  const n = String(name ?? "");
  return n.length <= 32 && FTP_USER_RE.test(n);
}

