  const m = raw.toLowerCase();
  if (m.includes("err_name_not_resolved") || m.includes("err_name_")) {
    return "The domain doesn’t resolve yet.";
  }
  if (m.includes("err_connection_refused")) return "Nothing is answering on that domain yet.";
  if (m.includes("err_connection_timed_out") || m.includes("timeout")) {
    return "The site didn’t respond in time.";
  }
  if (m.includes("err_too_many_redirects")) return "The site redirects in a loop, so there was nothing to photograph.";
  if (m.includes("err_cert") || m.includes("ssl")) return "The site’s certificate couldn’t be used.";
  if (m.includes("err_aborted") || m.includes("interrupted by another navigation")) {
    return "The site redirected somewhere we couldn’t follow.";
  }
  if (m.includes("err_empty_response")) return "The server closed the connection without sending a page.";
  return raw.split("\n")[0].slice(0, 160) || "The site didn’t answer.";
}

